async function sbRest(path, { method = "GET", body, token } = {}) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    method,
    headers: {
      apikey: ANON_KEY,
      Authorization: `Bearer ${token || ANON_KEY}`,
      "Content-Type": "application/json",
      Prefer: method === "GET" ? "" : "return=representation",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(t || `Erro ${res.status}`);
  }
  if (res.status === 204) return null;
  const txt = await res.text();
  return txt ? JSON.parse(txt) : null;
}
async function sbAuth(path, body) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/${path}`, {
    method: "POST",
    headers: { apikey: ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || data.error || "Falha na autenticação");
  return data;
}
const RH_BUCKET = "documentos-rh";
function sanitizeFileName(nome) {
  const semAcento = nome.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  return semAcento.replace(/[^a-zA-Z0-9._-]/g, "_");
}
async function sbStorageUpload(path, file, token, bucket = RH_BUCKET) {
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${bucket}/${path}`, {
    method: "POST",
    headers: { apikey: ANON_KEY, Authorization: `Bearer ${token}`, "Content-Type": file.type || "application/octet-stream", "x-upsert": "true" },
    body: file,
  });
  if (!res.ok) throw new Error((await res.text()) || "Falha ao enviar arquivo");
  return true;
}
async function sbStorageSignedUrl(path, token, expiresIn = 120, bucket = RH_BUCKET) {
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/sign/${bucket}/${path}`, {
    method: "POST",
    headers: { apikey: ANON_KEY, Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({ expiresIn }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message || "Não foi possível gerar o link do arquivo");
  return `${SUPABASE_URL}/storage/v1${data.signedURL}`;
}

