function FinanceiroModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("financeiro");
  const { data: vacinasEstoque } = useRecords("vacinas");
  const { data: insumosEstoque } = useRecords("insumos");
  const [filtroMes, setFiltroMes] = useState("");
  const [filtroDe, setFiltroDe] = useState("");
  const [filtroAte, setFiltroAte] = useState("");
  const dataFiltrada = filtrarPorPeriodo(data, "data", filtroMes, filtroDe, filtroAte);
  const fields = [
    { key: "data", label: "Data", type: "date", default: todayISO() },
    { key: "tipo", label: "Tipo", type: "select", options: ["entrada", "saida"] },
    { key: "linha", label: "Linha do DRE", type: "select", options: TODAS_LINHAS_DRE },
    { key: "descricao", label: "Descrição", type: "text" },
    { key: "valor", label: "Valor (R$)", type: "currency" },
  ];
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) },
    { key: "tipo", label: "Tipo", render: (r) => <Badge tone={r.tipo === "entrada" ? "green" : "red"}>{r.tipo === "entrada" ? "Entrada" : "Saída"}</Badge> },
    { key: "linha", label: "Linha DRE" }, { key: "descricao", label: "Descrição" },
    { key: "valor", label: "Valor", render: (r) => <span style={{ color: r.tipo === "entrada" ? T.green : T.red, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.valor)}</span> },
  ];
  const entradas = dataFiltrada.filter((r) => r.tipo === "entrada").reduce((s, r) => s + r.valor, 0);
  const saidas = dataFiltrada.filter((r) => r.tipo === "saida").reduce((s, r) => s + r.valor, 0);
  const saldo = entradas - saidas;
  const porMes = useMemo(() => { const map = {}; data.forEach((r) => { const m = monthKey(r.data); if (!map[m]) map[m] = { mes: m, entradas: 0, saidas: 0 }; map[m][r.tipo === "entrada" ? "entradas" : "saidas"] += r.valor; }); return Object.values(map).sort((a, b) => a.mes.localeCompare(b.mes)); }, [data]);
  const dreLinha = (linhas) => linhas.map((l) => ({ linha: l, valor: dataFiltrada.filter((r) => r.linha === l).reduce((s, r) => s + r.valor, 0) })).filter((x) => x.valor > 0);
  const receitas = dreLinha(DRE_LINHAS_RECEITA), custos = dreLinha(DRE_LINHAS_CUSTO), despesas = dreLinha(DRE_LINHAS_DESPESA), impostos = dreLinha(DRE_LINHAS_IMPOSTO);
  const totalReceita = receitas.reduce((s, x) => s + x.valor, 0), totalCustos = custos.reduce((s, x) => s + x.valor, 0);
  const lucroBruto = totalReceita - totalCustos, totalDespesas = despesas.reduce((s, x) => s + x.valor, 0), totalImpostos = impostos.reduce((s, x) => s + x.valor, 0);
  const resultado = lucroBruto - totalDespesas - totalImpostos;
  const margem = totalReceita ? (resultado / totalReceita) * 100 : 0;
  const valorEstoqueVacinas = vacinasEstoque.reduce((s, r) => s + Number(r.qtdEstoque) * Number(r.valorVenda), 0);
  const valorEstoqueInsumos = insumosEstoque.reduce((s, r) => s + Number(r.qtd) * Number(r.valorUnitario), 0);
  const DreLine = ({ label, value, bold }) => (
    <div className="flex justify-between py-1.5" style={{ borderBottom: `1px solid ${T.border}`, paddingLeft: bold ? 0 : 16 }}>
      <span className={bold ? "font-bold" : ""} style={{ color: bold ? T.text : T.muted, fontSize: bold ? 14 : 13 }}>{label}</span>
      <span className={bold ? "font-bold" : ""} style={{ color: T.text, fontFamily: "'Roboto', sans-serif", fontSize: 13 }}>{fmtBRL(value)}</span>
    </div>
  );
  return (
    <>
      <FiltroPeriodoBar filtroMes={filtroMes} setFiltroMes={setFiltroMes} filtroDe={filtroDe} setFiltroDe={setFiltroDe} filtroAte={filtroAte} setFiltroAte={setFiltroAte} />
    <ModuleShell icon={Wallet} title="Financeiro" subtitle="Fluxo de caixa, entradas, saídas e DRE consolidado — lançamentos entram pela Importação de OFX ou por Importar planilha" tone="coral" loading={loading} erro={erro} ocultarLancamento
      dailyFields={fields} dailyCta="Registrar movimento" fields={fields} columns={columns} rows={dataFiltrada} onAdd={add} onUpdate={update} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Entradas", value: fmtBRL(entradas), tone: "green", icon: TrendingUp }, { label: "Saídas", value: fmtBRL(saidas), tone: "red", icon: TrendingDown },
        { label: "Resultado do período", value: fmtBRL(saldo), tone: saldo >= 0 ? "green" : "red", icon: Activity }, { label: "Margem líquida", value: fmtPct(margem), tone: margem >= 0 ? "green" : "red" },
        { label: "Valor em estoque — Vacinas", value: fmtBRL(valorEstoqueVacinas), tone: "teal" }, { label: "Valor em estoque — Insumos", value: fmtBRL(valorEstoqueInsumos), tone: "teal" }]}
      charts={<div className="grid md:grid-cols-2 gap-5">
        <ChartCard title="Entradas x saídas por mês (histórico completo)"><BarChart data={porMes}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="mes" tick={{ fontSize: 11, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} /><Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Legend wrapperStyle={{ fontSize: 12 }} /><Bar dataKey="entradas" name="Entradas" fill={T.green} radius={[4, 4, 0, 0]} /><Bar dataKey="saidas" name="Saídas" fill={T.red} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>
        <ChartCard title="Composição da receita (no período filtrado)"><PieChart><Pie data={receitas} dataKey="valor" nameKey="linha" innerRadius={55} outerRadius={85} paddingAngle={2}>{receitas.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip formatter={(v) => fmtBRL(v)} /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart></ChartCard>
      </div>}
      extra={<Card className="mb-5"><p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>DRE — Demonstrativo de Resultado (período filtrado)</p>
        <div className="max-w-lg">{receitas.map((r) => <DreLine key={r.linha} label={r.linha} value={r.valor} />)}<DreLine label="(=) Receita Total" value={totalReceita} bold />
        {custos.map((r) => <DreLine key={r.linha} label={`(-) ${r.linha}`} value={r.valor} />)}<DreLine label="(=) Lucro Bruto" value={lucroBruto} bold />
        {despesas.map((r) => <DreLine key={r.linha} label={`(-) ${r.linha}`} value={r.valor} />)}{impostos.map((r) => <DreLine key={r.linha} label={`(-) ${r.linha}`} value={r.valor} />)}
        <div className="flex justify-between py-2 mt-1"><span className="font-bold text-sm" style={{ color: T.text }}>(=) Resultado do Período</span><span className="font-bold" style={{ color: resultado >= 0 ? T.green : T.red, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(resultado)}</span></div></div></Card>} />
    </>
  );
}

function ConveniosModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("convenios");
  const fields = [
    { key: "data", label: "Data", type: "date", default: todayISO() },
    { key: "convenio", label: "Convênio", type: "select", options: CONVENIOS },
    { key: "quantidade", label: "Qtd. atendimentos", type: "number" },
    { key: "valorUnitario", label: "Valor por atendimento (R$)", type: "currency" },
    { key: "aliquotaImposto", label: "Imposto (%)", type: "number", required: false, default: 0 },
  ];
  const computar = (r) => {
    const valorBruto = Number(r.quantidade || 0) * Number(r.valorUnitario || 0);
    const valorImposto = valorBruto * (Number(r.aliquotaImposto || 0) / 100);
    return { valor: valorBruto, valorLiquido: valorBruto - valorImposto };
  };
  const onAddComputado = (record) => add({ ...record, ...computar(record) });
  const onUpdateComputado = (id, record) => update(id, { ...record, ...computar(record) });
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) }, { key: "convenio", label: "Convênio" }, { key: "quantidade", label: "Atendimentos" },
    { key: "valorUnitario", label: "Valor unit.", render: (r) => fmtBRL(r.valorUnitario) },
    { key: "valor", label: "Valor bruto", render: (r) => fmtBRL(r.valor) },
    { key: "aliquotaImposto", label: "Imposto", render: (r) => fmtPct(r.aliquotaImposto) },
    { key: "valorLiquido", label: "Valor líquido", render: (r) => <span style={{ color: T.green, fontWeight: 600, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.valorLiquido)}</span> },
  ];
  const porConvenio = useMemo(() => { const map = {}; data.forEach((r) => { if (!map[r.convenio]) map[r.convenio] = { convenio: r.convenio, quantidade: 0, valor: 0 }; map[r.convenio].quantidade += Number(r.quantidade); map[r.convenio].valor += Number(r.valorLiquido ?? r.valor); }); return Object.values(map).sort((a, b) => b.valor - a.valor); }, [data]);
  const totalAtend = data.reduce((s, r) => s + Number(r.quantidade), 0);
  const totalBruto = data.reduce((s, r) => s + Number(r.valor), 0);
  const totalLiquido = data.reduce((s, r) => s + Number(r.valorLiquido ?? r.valor), 0);
  const totalImposto = totalBruto - totalLiquido;
  const lider = porConvenio[0];
  return (
    <ModuleShell icon={HeartHandshake} title="Atendimentos por Convênio" subtitle="Bradesco Saúde, Unimed, IPSM, AMMP, Orizon, Sancoop e particular" tone="teal" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar atendimentos" fields={fields} columns={columns} rows={data} onAdd={onAddComputado} onUpdate={onUpdateComputado} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Atendimentos", value: fmtNum(totalAtend), icon: Activity, tone: "teal" }, { label: "Valor bruto", value: fmtBRL(totalBruto) }, { label: "Impostos", value: fmtBRL(totalImposto), tone: "amber" }, { label: "Valor líquido", value: fmtBRL(totalLiquido), tone: "green" }]}
      charts={<div className="grid md:grid-cols-2 gap-5">
        <ChartCard title="Atendimentos por convênio"><BarChart data={porConvenio} layout="vertical" margin={{ left: 10 }}><CartesianGrid strokeDasharray="3 3" stroke={T.border} horizontal={false} /><XAxis type="number" tick={{ fontSize: 11, fill: T.muted }} /><YAxis type="category" dataKey="convenio" width={110} tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="quantidade" fill={T.teal} radius={[0, 4, 4, 0]} /></BarChart></ChartCard>
        <ChartCard title="Valor líquido por convênio"><PieChart><Pie data={porConvenio} dataKey="valor" nameKey="convenio" innerRadius={55} outerRadius={85} paddingAngle={2}>{porConvenio.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip formatter={(v) => fmtBRL(v)} /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart></ChartCard>
      </div>} />
  );
}

function VacinasModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("vacinas");
  const { data: lotes, loading: loadingLotes } = useRecords("entradasEstoqueVacinas");
  const fields = [{ key: "nome", label: "Nome da vacina", type: "text" }, { key: "qtdEstoque", label: "Qtd. em estoque", type: "number" }, { key: "qtdVendidaMes", label: "Vendida no mês", type: "number" }, { key: "qtdMinima", label: "Estoque mínimo", type: "number" }, { key: "valorCompra", label: "Valor compra (un.)", type: "currency" }, { key: "valorVenda", label: "Valor revenda (un.)", type: "currency" }];
  const diasParaVencer = (validade) => validade ? Math.ceil((new Date(validade) - new Date(todayISO())) / 86400000) : null;
  const lotesDaVacina = (vacinaId) => lotes.filter((l) => l.vacinaId === vacinaId && l.validade).sort((a, b) => a.validade.localeCompare(b.validade));
  const columns = [{ key: "nome", label: "Vacina" }, { key: "qtdEstoque", label: "Em estoque", render: (r) => <span className="flex items-center gap-1.5">{r.qtdEstoque}{r.qtdEstoque < r.qtdMinima && <AlertTriangle size={12} style={{ color: T.red }} />}</span> }, { key: "qtdVendidaMes", label: "Vendidas/mês" }, { key: "valorCompra", label: "Compra (un.)", render: (r) => fmtBRL(r.valorCompra) }, { key: "valorVenda", label: "Venda (un.)", render: (r) => fmtBRL(r.valorVenda) }, { key: "margem", label: "Margem", render: (r) => <span style={{ color: T.green }}>{fmtPct(r.valorVenda ? ((r.valorVenda - r.valorCompra) / r.valorVenda) * 100 : 0)}</span> },
    { key: "lotes", label: "Lotes — Validade", render: (r) => {
      const ls = lotesDaVacina(r.id);
      if (ls.length === 0) return <span className="text-xs" style={{ color: T.muted }}>Sem lote registrado</span>;
      return (
        <div className="flex flex-col gap-0.5">
          {ls.map((l) => { const dias = diasParaVencer(l.validade); const cor = dias <= 45 ? T.red : dias <= 90 ? T.amber : T.text; return (
            <span key={l.id} className="text-xs" style={{ color: cor }}>{l.lote} — {fmtDate(l.validade)}{dias <= 90 && ` (${dias < 0 ? "vencido" : `${dias}d`})`}</span>
          ); })}
        </div>
      );
    } },
  ];
  const valorEstoqueCompra = data.reduce((s, r) => s + r.qtdEstoque * r.valorCompra, 0), valorEstoqueVenda = data.reduce((s, r) => s + r.qtdEstoque * r.valorVenda, 0), receitaVendasMes = data.reduce((s, r) => s + r.qtdVendidaMes * r.valorVenda, 0);
  const abaixoMinimo = data.filter((r) => r.qtdEstoque < r.qtdMinima);
  const todosLotesComValidade = lotes.filter((l) => l.validade);
  const vencendo90 = todosLotesComValidade.filter((l) => { const d = diasParaVencer(l.validade); return d !== null && d <= 90 && d > 45; });
  const vencendo45 = todosLotesComValidade.filter((l) => { const d = diasParaVencer(l.validade); return d !== null && d <= 45; });
  const nomeVacina = (id) => (data.find((v) => v.id === id) || {}).nome || "—";
  return (
    <ModuleShell icon={Syringe} title="Estoque de Vacinas" subtitle="Cadastro, estoque atual, valor de compra e revenda — validade por lote" tone="teal" loading={loading || loadingLotes} erro={erro}
      dailyFields={fields} dailyCta="Atualizar/cadastrar vacina" fields={fields} columns={columns} rows={data} onAdd={add} onUpdate={update} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Estoque (custo)", value: fmtBRL(valorEstoqueCompra) }, { label: "Estoque (revenda)", value: fmtBRL(valorEstoqueVenda), tone: "green" }, { label: "Receita de vendas/mês", value: fmtBRL(receitaVendasMes), tone: "coral" }, { label: "Abaixo do mínimo", value: abaixoMinimo.length, tone: abaixoMinimo.length ? "red" : "green" }]}
      charts={<ChartCard title="Estoque atual x estoque mínimo, por vacina"><BarChart data={data}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="nome" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Legend wrapperStyle={{ fontSize: 12 }} /><Bar dataKey="qtdEstoque" name="Em estoque" fill={T.amber} radius={[4, 4, 0, 0]} /><Bar dataKey="qtdMinima" name="Mínimo" fill={`${T.amber}55`} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>}
      extra={<>
        {abaixoMinimo.length > 0 && <Card className="mb-5" style={{ borderColor: `${T.red}55` }}><div className="flex items-center gap-2 mb-1"><AlertTriangle size={15} style={{ color: T.red }} /><span className="font-semibold text-sm" style={{ color: T.red }}>Reposição necessária</span></div><p className="text-sm" style={{ color: T.muted }}>{abaixoMinimo.map((r) => r.nome).join(", ")} — abaixo do estoque mínimo.</p></Card>}
        {vencendo45.length > 0 && <Card className="mb-5" style={{ borderColor: `${T.red}55` }}><div className="flex items-center gap-2 mb-1"><AlertTriangle size={15} style={{ color: T.red }} /><span className="font-semibold text-sm" style={{ color: T.red }}>Lotes vencendo em até 45 dias</span></div><p className="text-sm" style={{ color: T.muted }}>{vencendo45.map((l) => `${nomeVacina(l.vacinaId)} (lote ${l.lote})`).join(", ")}.</p></Card>}
        {vencendo90.length > 0 && <Card className="mb-5" style={{ borderColor: `${T.amber}55` }}><div className="flex items-center gap-2 mb-1"><AlertTriangle size={15} style={{ color: T.amber }} /><span className="font-semibold text-sm" style={{ color: T.text }}>Lotes vencendo em até 90 dias</span></div><p className="text-sm" style={{ color: T.muted }}>{vencendo90.map((l) => `${nomeVacina(l.vacinaId)} (lote ${l.lote})`).join(", ")}.</p></Card>}
      </>} />
  );
}

function PosVendaModulo() {
  const { session, perfil } = useAuth();
  const { data, add, update, remove, loading, erro } = useRecords("posVenda");
  const { data: pontos, add: addPonto, update: updatePonto, loading: loadingPonto } = useOwnRecords("pos_venda_ponto");
  const { data: colaboradoresUnidade } = usePerfisDaUnidade();
  const nomesColaboradores = colaboradoresUnidade.map((c) => c.nome);
  const fields = [
    { key: "paciente", label: "Paciente / contato", type: "text" },
    { key: "telefone", label: "Telefone", type: "text", required: false },
    { key: "data", label: "Data da ligação", type: "date", default: todayISO() },
    { key: "realizadoPor", label: "Realizado por", type: "select", options: nomesColaboradores.length ? nomesColaboradores : [perfil.nome], default: perfil.nome },
    { key: "convertida", label: "Ligação convertida?", type: "select", options: ["Sim", "Não"], default: "Não" },
    { key: "agendamentoFeito", label: "Agendamento feito?", type: "select", options: ["Sim", "Não"], default: "Não" },
    { key: "dataAgendamento", label: "Data do agendamento", type: "date", required: false, showIf: (f) => f.agendamentoFeito === "Sim" },
    { key: "observacoes", label: "Observações — anote tudo que o paciente falou", type: "textarea", required: false },
  ];
  const onAddConvertido = (record) => { const colab = colaboradoresUnidade.find((c) => c.nome === record.realizadoPor); return add({ ...record, convertida: record.convertida === "Sim", agendamentoFeito: record.agendamentoFeito === "Sim", colaboradorId: colab ? colab.id : perfil.id, colaboradorNome: record.realizadoPor || perfil.nome }); };
  const onUpdateConvertido = (id, record) => { const colab = colaboradoresUnidade.find((c) => c.nome === record.realizadoPor); return update(id, { ...record, convertida: record.convertida === "Sim", agendamentoFeito: record.agendamentoFeito === "Sim", colaboradorId: colab ? colab.id : undefined, colaboradorNome: record.realizadoPor }); };
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) }, { key: "paciente", label: "Paciente" }, { key: "telefone", label: "Telefone" },
    { key: "colaboradorNome", label: "Realizado por", render: (r) => r.colaboradorNome || "—" },
    { key: "convertida", label: "Convertida", render: (r) => <Badge tone={r.convertida ? "green" : "muted"}>{r.convertida ? "Sim" : "Não"}</Badge> },
    { key: "agendamentoFeito", label: "Agendamento", render: (r) => r.agendamentoFeito ? <Badge tone="teal">{fmtDate(r.dataAgendamento)}</Badge> : <span style={{ color: T.muted }}>—</span> },
    { key: "observacoes", label: "Observações" },
  ];
  const isAdmin = perfil.papel === "admin";
  const dataVisivel = isAdmin ? data : data.filter((r) => r.colaboradorId === perfil.id);
  const total = dataVisivel.length;
  const convertidas = dataVisivel.filter((r) => r.convertida).length;
  const agendamentos = dataVisivel.filter((r) => r.agendamentoFeito).length;
  const taxaConversao = total ? (convertidas / total) * 100 : 0;
  const taxaProdutividade = total ? (((convertidas / total) + (agendamentos / total)) / 2) * 100 : 0;
  const rowsParaForm = dataVisivel.map((r) => ({ ...r, convertida: r.convertida ? "Sim" : "Não", agendamentoFeito: r.agendamentoFeito ? "Sim" : "Não", realizadoPor: r.colaboradorNome }));

  const hoje = todayISO();
  const pontoHoje = pontos.find((p) => p.data === hoje);
  const proximaAcaoPonto = !pontoHoje ? "inicio" : !pontoHoje.hora_fim ? "fim" : "completo";
  const [busyPonto, setBusyPonto] = useState(false);
  const baterPontoPosVenda = async () => {
    setBusyPonto(true);
    const agora = new Date().toTimeString().slice(0, 5);
    if (proximaAcaoPonto === "inicio") await addPonto({ data: hoje, hora_inicio: agora });
    else if (proximaAcaoPonto === "fim") {
      const [h1, m1] = pontoHoje.hora_inicio.split(":").map(Number); const [h2, m2] = agora.split(":").map(Number);
      let mins = (h2 * 60 + m2) - (h1 * 60 + m1); if (mins < 0) mins += 24 * 60;
      await updatePonto(pontoHoje.id, { hora_fim: agora, horas_total: Math.round((mins / 60) * 100) / 100 });
    }
    setBusyPonto(false);
  };
  const horasMesPosVenda = pontos.filter((p) => p.data.slice(0, 7) === hoje.slice(0, 7)).reduce((s, p) => s + (Number(p.horas_total) || 0), 0);

  return (
    <div>
      <SectionHeader icon={Megaphone} title="Pós-venda" subtitle="Ligações realizadas, conversão e agendamentos — com observações detalhadas" tone="rose" />
      <Card className="mb-5" style={{ background: `linear-gradient(135deg, ${T.coralDeep}, ${T.coral})` }}>
        <p className="text-[11px] font-semibold uppercase mb-2" style={{ color: "#FBDADD", letterSpacing: "0.06em" }}>Ponto do pós-venda — {fmtDate(hoje)}</p>
        <div className="flex flex-wrap items-center gap-6 mb-4">
          <div><div className="text-[10px] uppercase" style={{ color: "#FBDADD" }}>Início</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{(pontoHoje && pontoHoje.hora_inicio) || "—"}</div></div>
          <div><div className="text-[10px] uppercase" style={{ color: "#FBDADD" }}>Fim</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{(pontoHoje && pontoHoje.hora_fim) || "—"}</div></div>
          <div><div className="text-[10px] uppercase" style={{ color: "#FBDADD" }}>Horas no mês</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{horasMesPosVenda.toFixed(1)}h</div></div>
        </div>
        <button disabled={busyPonto || loadingPonto || proximaAcaoPonto === "completo"} onClick={baterPontoPosVenda} className="px-6 py-3 rounded-xl font-bold text-sm" style={{ background: proximaAcaoPonto === "completo" ? "#FFFFFF30" : "#fff", color: proximaAcaoPonto === "completo" ? "#fff" : T.coralDeep, opacity: busyPonto ? 0.7 : 1 }}>
          {busyPonto ? "Registrando…" : proximaAcaoPonto === "inicio" ? "Bater início do pós-venda" : proximaAcaoPonto === "fim" ? "Bater fim do pós-venda" : "Ponto do dia completo ✓"}
        </button>
      </Card>
      <ModuleShell icon={Megaphone} title="Registro de ligações" subtitle={isAdmin ? "Mostrando as ligações de toda a equipe" : "Mostrando só as suas ligações"} tone="rose" loading={loading} erro={erro}
        dailyFields={fields} dailyCta="Registrar ligação" fields={fields} columns={columns} rows={rowsParaForm} onAdd={onAddConvertido} onUpdate={onUpdateConvertido} onDelete={remove}
        kpis={[{ label: "Ligações registradas", value: total }, { label: "Convertidas", value: convertidas, tone: "green" }, { label: "Atendidas (agendamentos)", value: agendamentos, tone: "teal" }, { label: "Taxa de conversão", value: fmtPct(taxaConversao), tone: taxaConversao >= 30 ? "green" : "amber" }, { label: "Taxa de produtividade", value: fmtPct(taxaProdutividade), tone: taxaProdutividade >= 40 ? "green" : "amber" }]} />
    </div>
  );
}

function VendasVacinasModulo() {
  const { data: vendas, add, update, remove, loading, erro } = useRecords("vendasVacinas");
  const { data: vacinasCat, update: updateVacina, loading: loadingVacinas } = useRecords("vacinas");
  const { data: metas } = useRecords("metas");
  const nomesVacinas = vacinasCat.map((v) => v.nome);
  const fields = [
    { key: "vacina", label: "Vacina", type: "select", options: nomesVacinas.length ? nomesVacinas : ["Cadastre em Estoque de Vacinas primeiro"] },
    { key: "data", label: "Data", type: "date", default: todayISO() },
    { key: "quantidade", label: "Quantidade vendida", type: "number" },
    { key: "descontoPct", label: "Desconto (%)", type: "number", required: false, default: 0 },
  ];
  const computarVenda = (record) => {
    const vac = vacinasCat.find((v) => v.nome === record.vacina);
    if (!vac) return null;
    const qtd = Number(record.quantidade) || 0;
    const desconto = Number(record.descontoPct) || 0;
    const valorUnitario = vac.valorVenda;
    const valorTotal = qtd * valorUnitario * (1 - desconto / 100);
    return { vac, qtd, valorUnitario, descontoPct: desconto, valorTotal };
  };
  const onAddVenda = async (record) => {
    const calc = computarVenda(record);
    if (!calc) return alert("Selecione uma vacina cadastrada.");
    await add({ vacinaId: calc.vac.id, data: record.data, quantidade: calc.qtd, valorUnitario: calc.valorUnitario, descontoPct: calc.descontoPct, valorTotal: calc.valorTotal });
    await updateVacina(calc.vac.id, { qtdEstoque: Math.max((calc.vac.qtdEstoque || 0) - calc.qtd, 0), qtdVendidaMes: (calc.vac.qtdVendidaMes || 0) + calc.qtd });
  };
  const onUpdateVenda = async (id, record) => {
    const vendaAnterior = vendas.find((v) => v.id === id);
    const calc = computarVenda(record);
    if (!calc) return alert("Selecione uma vacina cadastrada.");
    // desfaz o efeito da venda antiga no estoque antes de aplicar a nova
    if (vendaAnterior) {
      const vacAnterior = vacinasCat.find((v) => v.id === vendaAnterior.vacinaId);
      if (vacAnterior) await updateVacina(vacAnterior.id, { qtdEstoque: Number(vacAnterior.qtdEstoque) + Number(vendaAnterior.quantidade), qtdVendidaMes: Math.max(Number(vacAnterior.qtdVendidaMes) - Number(vendaAnterior.quantidade), 0) });
    }
    await update(id, { vacinaId: calc.vac.id, data: record.data, quantidade: calc.qtd, valorUnitario: calc.valorUnitario, descontoPct: calc.descontoPct, valorTotal: calc.valorTotal });
    await updateVacina(calc.vac.id, { qtdEstoque: Math.max((calc.vac.qtdEstoque || 0) - calc.qtd, 0), qtdVendidaMes: (calc.vac.qtdVendidaMes || 0) + calc.qtd });
  };
  const onRemoveVenda = async (id) => {
    const venda = vendas.find((v) => v.id === id);
    if (venda) {
      const vac = vacinasCat.find((v) => v.id === venda.vacinaId);
      if (vac) await updateVacina(vac.id, { qtdEstoque: Number(vac.qtdEstoque) + Number(venda.quantidade), qtdVendidaMes: Math.max(Number(vac.qtdVendidaMes) - Number(venda.quantidade), 0) });
    }
    await remove(id);
  };
  const rowsEnriquecidas = vendas.map((v) => ({ ...v, vacina: (vacinasCat.find((x) => x.id === v.vacinaId) || {}).nome || "—" }));
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) }, { key: "vacina", label: "Vacina" }, { key: "quantidade", label: "Qtd." },
    { key: "valorUnitario", label: "Valor unit.", render: (r) => fmtBRL(r.valorUnitario) },
    { key: "descontoPct", label: "Desconto", render: (r) => fmtPct(r.descontoPct) },
    { key: "valorTotal", label: "Total", render: (r) => <span style={{ color: T.green, fontWeight: 600, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.valorTotal)}</span> },
  ];
  const totalVendido = vendas.reduce((s, r) => s + r.valorTotal, 0);
  const totalQtd = vendas.reduce((s, r) => s + Number(r.quantidade), 0);
  const porVacina = useMemo(() => { const map = {}; rowsEnriquecidas.forEach((r) => { map[r.vacina] = (map[r.vacina] || 0) + r.valorTotal; }); return Object.entries(map).map(([vacina, valor]) => ({ vacina, valor })).sort((a, b) => b.valor - a.valor); }, [rowsEnriquecidas]);

  const mesAtual = todayISO().slice(0, 7);
  const totalVendidoMes = vendas.filter((r) => r.data.slice(0, 7) === mesAtual).reduce((s, r) => s + Number(r.valorTotal), 0);
  const metaVacinasMes = metas.find((m) => m.mes === mesAtual && m.categoria === "Faturamento em Vacinas");
  const faltaMeta = metaVacinasMes ? Math.max(Number(metaVacinasMes.valorMeta) - totalVendidoMes, 0) : null;
  const pctMeta = metaVacinasMes && metaVacinasMes.valorMeta ? (totalVendidoMes / metaVacinasMes.valorMeta) * 100 : null;

  return (
    <ModuleShell icon={Syringe} title="Vendas de Vacinas" subtitle="Selecione a vacina já cadastrada — valor e estoque atualizam automaticamente" tone="teal" loading={loading || loadingVacinas} erro={erro}
      dailyFields={fields} dailyCta="Registrar venda" fields={fields} columns={columns} rows={rowsEnriquecidas} onAdd={onAddVenda} onUpdate={onUpdateVenda} onDelete={onRemoveVenda}
      kpis={[{ label: "Vendas registradas", value: vendas.length }, { label: "Doses vendidas", value: fmtNum(totalQtd) }, { label: "Valor total vendido", value: fmtBRL(totalVendido), tone: "green" }]}
      extra={metaVacinasMes && (
        <Card className="mb-5" style={{ borderColor: `${T.teal}55` }}>
          <div className="flex items-center gap-2 mb-2"><ClipboardList size={15} style={{ color: T.teal }} /><span className="font-semibold text-sm" style={{ color: T.text }}>Meta do mês — Faturamento em Vacinas</span></div>
          <Progress pct={pctMeta} />
          <div className="flex justify-between text-sm mt-2">
            <span style={{ color: T.muted }}>Vendido: <b style={{ color: T.text }}>{fmtBRL(totalVendidoMes)}</b> de {fmtBRL(metaVacinasMes.valorMeta)}</span>
            <span style={{ color: faltaMeta > 0 ? T.amber : T.green, fontWeight: 600 }}>{faltaMeta > 0 ? `Falta ${fmtBRL(faltaMeta)}` : "Meta batida! 🎉"}</span>
          </div>
        </Card>
      )}
      charts={<ChartCard title="Valor vendido por vacina"><BarChart data={porVacina}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="vacina" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="valor" fill={T.teal} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
  );
}

function EntradaEstoqueInsumosModulo() {
  const { data: entradas, add, remove, loading, erro } = useRecords("entradasEstoqueInsumos");
  const { data: insumosCat, update: updateInsumo, loading: loadingInsumos } = useRecords("insumos");
  const nomesInsumos = insumosCat.map((i) => i.nome);
  const fields = [
    { key: "insumo", label: "Item", type: "select", options: nomesInsumos.length ? nomesInsumos : ["Cadastre em Estoque de Insumos primeiro"] },
    { key: "data", label: "Data (competência)", type: "date", default: todayISO() },
    { key: "quantidade", label: "Quantidade que chegou", type: "number" },
  ];
  const onAddEntrada = async (record) => {
    const item = insumosCat.find((i) => i.nome === record.insumo);
    if (!item) return alert("Selecione um item cadastrado.");
    const qtd = Number(record.quantidade) || 0;
    await add({ insumoId: item.id, data: record.data, quantidade: qtd });
    await updateInsumo(item.id, { qtd: Number(item.qtd || 0) + qtd });
  };
  const onRemoveEntrada = async (id) => {
    const entrada = entradas.find((e) => e.id === id);
    if (entrada) {
      const item = insumosCat.find((i) => i.id === entrada.insumoId);
      if (item) await updateInsumo(item.id, { qtd: Math.max(Number(item.qtd) - Number(entrada.quantidade), 0) });
    }
    await remove(id);
  };
  const rowsEnriquecidas = entradas.map((e) => ({ ...e, insumo: (insumosCat.find((x) => x.id === e.insumoId) || {}).nome || "—" }));
  const columns = [{ key: "data", label: "Data (competência)", render: (r) => fmtDate(r.data) }, { key: "insumo", label: "Item" }, { key: "quantidade", label: "Quantidade" }];
  const totalQtd = entradas.reduce((s, r) => s + Number(r.quantidade), 0);
  const porItem = useMemo(() => { const map = {}; rowsEnriquecidas.forEach((r) => { map[r.insumo] = (map[r.insumo] || 0) + Number(r.quantidade); }); return Object.entries(map).map(([insumo, quantidade]) => ({ insumo, quantidade })).sort((a, b) => b.quantidade - a.quantidade); }, [rowsEnriquecidas]);
  return (
    <ModuleShell icon={Package} title="Entrada de Estoque — Insumos" subtitle="Registre com data tudo que chegou — exporte por período quando quiser" tone="teal" loading={loading || loadingInsumos} erro={erro}
      dailyFields={fields} dailyCta="Registrar entrada" fields={fields} columns={columns} rows={rowsEnriquecidas} onAdd={onAddEntrada} onUpdate={() => {}} onDelete={onRemoveEntrada}
      kpis={[{ label: "Entradas registradas", value: entradas.length }, { label: "Itens recebidos", value: fmtNum(totalQtd), tone: "teal" }]}
      charts={<ChartCard title="Quantidade recebida por item"><BarChart data={porItem}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="insumo" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="quantidade" fill={T.teal} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
  );
}

function EntradaEstoqueVacinasModulo() {
  const { data: entradas, add, remove, loading, erro } = useRecords("entradasEstoqueVacinas");
  const { data: vacinasCat, update: updateVacina, loading: loadingVacinas } = useRecords("vacinas");
  const nomesVacinas = vacinasCat.map((v) => v.nome);
  const fields = [
    { key: "vacina", label: "Vacina", type: "select", options: nomesVacinas.length ? nomesVacinas : ["Cadastre em Estoque de Vacinas primeiro"] },
    { key: "data", label: "Data (competência)", type: "date", default: todayISO() },
    { key: "quantidade", label: "Quantidade que chegou", type: "number" },
    { key: "validade", label: "Validade deste lote", type: "date" },
  ];
  const gerarLote = (data) => (data || todayISO()).replace(/-/g, "");
  const onAddEntrada = async (record) => {
    const vac = vacinasCat.find((v) => v.nome === record.vacina);
    if (!vac) return alert("Selecione uma vacina cadastrada.");
    const qtd = Number(record.quantidade) || 0;
    await add({ vacinaId: vac.id, data: record.data, quantidade: qtd, lote: gerarLote(record.data), validade: record.validade || null });
    await updateVacina(vac.id, { qtdEstoque: Number(vac.qtdEstoque || 0) + qtd });
  };
  const onRemoveEntrada = async (id) => {
    const entrada = entradas.find((e) => e.id === id);
    if (entrada) {
      const vac = vacinasCat.find((v) => v.id === entrada.vacinaId);
      if (vac) await updateVacina(vac.id, { qtdEstoque: Math.max(Number(vac.qtdEstoque) - Number(entrada.quantidade), 0) });
    }
    await remove(id);
  };
  const diasParaVencer = (validade) => validade ? Math.ceil((new Date(validade) - new Date(todayISO())) / 86400000) : null;
  const rowsEnriquecidas = entradas.map((e) => ({ ...e, vacina: (vacinasCat.find((x) => x.id === e.vacinaId) || {}).nome || "—" }));
  const columns = [
    { key: "data", label: "Data (competência)", render: (r) => fmtDate(r.data) },
    { key: "lote", label: "Lote", render: (r) => <span className="text-xs" style={{ color: T.muted, fontFamily: "'Roboto', sans-serif" }}>{r.lote || "—"}</span> },
    { key: "vacina", label: "Vacina" }, { key: "quantidade", label: "Quantidade" },
    { key: "validade", label: "Validade", render: (r) => { if (!r.validade) return <span style={{ color: T.muted }}>—</span>; const dias = diasParaVencer(r.validade); return <span style={{ color: dias <= 45 ? T.red : dias <= 90 ? T.amber : T.text }}>{fmtDate(r.validade)}{dias <= 90 && <span className="block text-xs">{dias < 0 ? "vencido" : `${dias} dias`}</span>}</span>; } },
  ];
  const totalQtd = entradas.reduce((s, r) => s + Number(r.quantidade), 0);
  const porVacina = useMemo(() => { const map = {}; rowsEnriquecidas.forEach((r) => { map[r.vacina] = (map[r.vacina] || 0) + Number(r.quantidade); }); return Object.entries(map).map(([vacina, quantidade]) => ({ vacina, quantidade })).sort((a, b) => b.quantidade - a.quantidade); }, [rowsEnriquecidas]);
  const lotesVencendo = rowsEnriquecidas.filter((r) => { const d = diasParaVencer(r.validade); return d !== null && d <= 90; }).sort((a, b) => diasParaVencer(a.validade) - diasParaVencer(b.validade));
  return (
    <ModuleShell icon={Syringe} title="Entrada de Estoque — Vacinas" subtitle="Registre por lote (data + validade) tudo que chegou — cada lote fica guardado, nada é sobrescrito" tone="teal" loading={loading || loadingVacinas} erro={erro}
      dailyFields={fields} dailyCta="Registrar entrada" fields={fields} columns={columns} rows={rowsEnriquecidas} onAdd={onAddEntrada} onUpdate={() => {}} onDelete={onRemoveEntrada}
      kpis={[{ label: "Entradas registradas", value: entradas.length }, { label: "Doses recebidas", value: fmtNum(totalQtd), tone: "teal" }, { label: "Lotes vencendo (90 dias)", value: lotesVencendo.length, tone: lotesVencendo.length ? "amber" : "green" }]}
      extra={lotesVencendo.length > 0 && (
        <Card className="mb-5" style={{ borderColor: `${T.amber}55` }}>
          <div className="flex items-center gap-2 mb-2"><AlertTriangle size={15} style={{ color: T.amber }} /><span className="font-semibold text-sm" style={{ color: T.text }}>Lotes próximos do vencimento</span></div>
          <div className="flex flex-col gap-1.5">
            {lotesVencendo.map((r) => { const dias = diasParaVencer(r.validade); return (
              <div key={r.id} className="flex justify-between text-sm">
                <span style={{ color: T.muted }}>{r.vacina} — lote {r.lote} ({r.quantidade} un.)</span>
                <span style={{ color: dias <= 45 ? T.red : T.amber, fontWeight: 600 }}>{dias < 0 ? "vencido" : `${dias} dias`} — {fmtDate(r.validade)}</span>
              </div>
            ); })}
          </div>
        </Card>
      )}
      charts={<ChartCard title="Doses recebidas por vacina"><BarChart data={porVacina}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="vacina" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="quantidade" fill={T.teal} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
  );
}

