/* ============================== PROTOCOLO DE GUIAS ============================== */
function gerarNumeroProtocolo(nomeUsuario) {
  const iniciais = (nomeUsuario || "USUARIO").trim().split(" ").map((p) => p[0]).join("").toUpperCase().slice(0, 4);
  const agora = new Date();
  const dataParte = agora.toISOString().slice(0, 10).replace(/-/g, "");
  const horaParte = agora.toTimeString().slice(0, 8).replace(/:/g, "");
  return `${iniciais}-${dataParte}-${horaParte}`;
}
function ProtocoloBradescoModulo() {
  const { session, perfil } = useAuth();
  const { unidadeId } = useUnidade();
  const { data: protocolos, remove: removeLote, loading, erro, reload } = useRecords("protocoloBradesco");
  const { data: guiasDoLote, reload: reloadGuiasDoLote } = useRecords("protocoloBradescoGuias");
  const { data: faturamento, update: updateGuiaStatus } = useRecords("faturamento");
  const CONVENIOS_BRADESCO = ["Bradesco Saúde", "Bradesco Saúde Clínica", "Bradesco Operadora de Planos Clínica"];

  // --- formulário de novo lote ---
  const [numeroLote, setNumeroLote] = useState("");
  const [convenio, setConvenio] = useState("Bradesco Saúde Clínica");
  const [dataEmissao, setDataEmissao] = useState("");
  const [dataEnvio, setDataEnvio] = useState(todayISO());
  const [regimeTributario, setRegimeTributario] = useState("Simples Nacional");
  const [carrinhoGuias, setCarrinhoGuias] = useState([]);
  const [numeroGuiaAtual, setNumeroGuiaAtual] = useState("");
  const [valorGuiaAtual, setValorGuiaAtual] = useState("");
  const [busy, setBusy] = useState(false);

  const adicionarGuiaAoCarrinho = () => {
    if (!valorGuiaAtual) return;
    setCarrinhoGuias((p) => [...p, { numeroGuia: numeroGuiaAtual || `Guia ${p.length + 1}`, valor: Number(valorGuiaAtual) }]);
    setNumeroGuiaAtual(""); setValorGuiaAtual("");
  };
  const removerGuiaDoCarrinho = (idx) => setCarrinhoGuias((p) => p.filter((_, i) => i !== idx));
  const totalCarrinho = carrinhoGuias.reduce((s, g) => s + g.valor, 0);

  const fecharLote = async () => {
    if (!numeroLote || carrinhoGuias.length === 0) return alert("Preencha o nº do lote e adicione ao menos uma guia.");
    setBusy(true);
    try {
      const impostos = { ir_valor: totalCarrinho * 0.015, cofins_valor: totalCarrinho * 0.03, pis_valor: totalCarrinho * 0.0065, csll_valor: totalCarrinho * 0.01 };
      const loteCriado = await sbRest("protocolo_bradesco", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, numero_lote: numeroLote, data_emissao: dataEmissao || null, data_envio: dataEnvio, valor_nota: totalCarrinho, regime_tributario: regimeTributario, ...impostos } });
      const loteId = loteCriado && loteCriado[0] ? loteCriado[0].id : null;
      for (const g of carrinhoGuias) {
        const guiaCriada = await sbRest("faturamento_guias", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, convenio, numero_guia: g.numeroGuia, tipo: "Outro", data_protocolo: dataEnvio, valor: g.valor, status: "Protocolada" } });
        const guiaId = guiaCriada && guiaCriada[0] ? guiaCriada[0].id : null;
        await sbRest("protocolo_bradesco_guias", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, protocolo_bradesco_id: loteId, numero_guia: g.numeroGuia, valor: g.valor, faturamento_guia_id: guiaId } });
      }
      setNumeroLote(""); setDataEmissao(""); setDataEnvio(todayISO()); setCarrinhoGuias([]);
      await reload(); await reloadGuiasDoLote();
    } catch (e) { alert("Não foi possível salvar: " + e.message); }
    setBusy(false);
  };

  const statusDaGuiaFaturamento = (faturamentoGuiaId) => { const g = faturamento.find((x) => x.id === faturamentoGuiaId); return g ? g.status : "—"; };
  const alterarStatusGuia = async (faturamentoGuiaId, novoStatus) => {
    if (!faturamentoGuiaId) return;
    if (novoStatus === "Paga") {
      const data = window.prompt("Data em que foi paga (AAAA-MM-DD):", todayISO());
      if (!data) return;
      await updateGuiaStatus(faturamentoGuiaId, { status: novoStatus, dataPagamento: data });
    } else {
      await updateGuiaStatus(faturamentoGuiaId, { status: novoStatus });
    }
  };
  const numeroDoLote = (str) => { const m = String(str || "").match(/\d+/); return m ? parseInt(m[0], 10) : 0; };

  const [filtroMes, setFiltroMes] = useState("");
  const [filtroDe, setFiltroDe] = useState("");
  const [filtroAte, setFiltroAte] = useState("");
  const protocolosFiltrados = [...filtrarPorPeriodo(protocolos, "dataEnvio", filtroMes, filtroDe, filtroAte)].sort((a, b) => numeroDoLote(a.numeroLote) - numeroDoLote(b.numeroLote));
  const idsDosLotesFiltrados = new Set(protocolosFiltrados.map((p) => p.id));
  const guiasVisiveis = guiasDoLote.filter((g) => idsDosLotesFiltrados.has(g.protocoloBradescoId));

  const totalNotas = guiasVisiveis.reduce((s, g) => s + Number(g.valor), 0);
  const totalImpostos = protocolosFiltrados.reduce((s, r) => s + Number(r.irValor) + Number(r.cofinsValor) + Number(r.pisValor) + Number(r.csllValor), 0);
  const guiasPagas = guiasVisiveis.filter((g) => statusDaGuiaFaturamento(g.faturamentoGuiaId) === "Paga");
  const valorRecebido = guiasPagas.reduce((s, g) => s + Number(g.valor), 0);
  const valorAReceber = guiasVisiveis.filter((g) => statusDaGuiaFaturamento(g.faturamentoGuiaId) !== "Paga").reduce((s, g) => s + Number(g.valor), 0);

  // --- reconciliação: guias Bradesco em Contas a Receber que não vieram de nenhum lote daqui ---
  const idsGuiasVinculadas = new Set(guiasDoLote.map((g) => g.faturamentoGuiaId).filter(Boolean));
  const guiasOrfas = faturamento.filter((f) => f.convenio && f.convenio.toLowerCase().includes("bradesco") && !idsGuiasVinculadas.has(f.id));
  const [loteParaVincular, setLoteParaVincular] = useState({});
  const vincularOrfaExistente = async (guiaOrfa) => {
    const loteId = loteParaVincular[guiaOrfa.id];
    if (!loteId) return alert("Escolha um lote para vincular.");
    try {
      await sbRest("protocolo_bradesco_guias", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, protocolo_bradesco_id: loteId, numero_guia: guiaOrfa.numeroGuia || "—", valor: guiaOrfa.valor, faturamento_guia_id: guiaOrfa.id } });
      await reloadGuiasDoLote();
    } catch (e) { alert("Não foi possível vincular: " + e.message); }
  };
  const criarLoteSoParaOrfa = async (guiaOrfa) => {
    try {
      const loteCriado = await sbRest("protocolo_bradesco", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, numero_lote: guiaOrfa.numeroGuia || `AVULSO-${guiaOrfa.id.slice(0, 6)}`, data_envio: guiaOrfa.dataProtocolo, valor_nota: guiaOrfa.valor, regime_tributario: "Simples Nacional", ir_valor: guiaOrfa.valor * 0.015, cofins_valor: guiaOrfa.valor * 0.03, pis_valor: guiaOrfa.valor * 0.0065, csll_valor: guiaOrfa.valor * 0.01 } });
      const loteId = loteCriado && loteCriado[0] ? loteCriado[0].id : null;
      await sbRest("protocolo_bradesco_guias", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, protocolo_bradesco_id: loteId, numero_guia: guiaOrfa.numeroGuia || "—", valor: guiaOrfa.valor, faturamento_guia_id: guiaOrfa.id } });
      await reload(); await reloadGuiasDoLote();
    } catch (e) { alert("Não foi possível criar o lote: " + e.message); }
  };

  return (
    <>
      <FiltroPeriodoBar filtroMes={filtroMes} setFiltroMes={setFiltroMes} filtroDe={filtroDe} setFiltroDe={setFiltroDe} filtroAte={filtroAte} setFiltroAte={setFiltroAte} />
      <SectionHeader icon={ClipboardList} title="Protocolo Bradesco" subtitle="O Bradesco paga por guia, não por lote — cada guia tem seu próprio status" tone="coral" />

      <div className="grid gap-3 mb-6" style={{ gridTemplateColumns: "repeat(4, minmax(0,1fr))" }}>
        <KpiCard label="Lotes registrados" value={protocolosFiltrados.length} />
        <KpiCard label="Valor total das guias" value={fmtBRL(totalNotas)} tone="coral" />
        <KpiCard label="Valor recebido" value={fmtBRL(valorRecebido)} tone="green" />
        <KpiCard label="Valor a receber" value={fmtBRL(valorAReceber)} tone="amber" />
      </div>
      <div className="grid gap-3 mb-6" style={{ gridTemplateColumns: "repeat(3, minmax(0,1fr))" }}>
        <KpiCard label="Impostos retidos (total)" value={fmtBRL(totalImpostos)} tone="amber" />
        <KpiCard label="Guias pagas" value={guiasPagas.length} tone="green" />
        <KpiCard label="Guias registradas" value={guiasVisiveis.length} />
      </div>

      {erro && <Card className="mb-5"><span className="text-sm" style={{ color: T.red }}>Erro ao carregar: {erro}</span></Card>}

      <Card className="mb-5">
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Novo lote — adicione as guias que ele contém</p>
        <div className="grid md:grid-cols-3 gap-3 mb-4">
          <Field label="Nº do lote"><input className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} placeholder="ex: LOTE 65" value={numeroLote} onChange={(e) => setNumeroLote(e.target.value)} /></Field>
          <Field label="Convênio"><select className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={convenio} onChange={(e) => setConvenio(e.target.value)}>{CONVENIOS_BRADESCO.map((c) => <option key={c} value={c}>{c}</option>)}</select></Field>
          <Field label="Regime tributário"><select className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={regimeTributario} onChange={(e) => setRegimeTributario(e.target.value)}><option>Simples Nacional</option><option>Lucro Presumido</option><option>Lucro Real</option></select></Field>
          <Field label="Data de emissão"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={dataEmissao} onChange={(e) => setDataEmissao(e.target.value)} /></Field>
          <Field label="Data de envio do lote"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={dataEnvio} onChange={(e) => setDataEnvio(e.target.value)} /></Field>
        </div>
        <p className="text-[11px] font-semibold uppercase mb-2" style={{ color: T.muted, letterSpacing: "0.06em" }}>Adicionar guia ao lote (quantas tiver)</p>
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Nº da guia (opcional)"><input className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={numeroGuiaAtual} onChange={(e) => setNumeroGuiaAtual(e.target.value)} /></Field>
          <Field label="Valor da guia (R$)"><input type="number" step="0.01" className="rounded-lg px-3 py-2 text-sm outline-none w-36" style={inputStyle} value={valorGuiaAtual} onChange={(e) => setValorGuiaAtual(e.target.value)} /></Field>
          <Btn small tone="teal" icon={Plus} onClick={adicionarGuiaAoCarrinho}>Adicionar guia</Btn>
        </div>
        {carrinhoGuias.length > 0 && (
          <div className="mb-4">
            <table className="w-full text-sm">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Guia</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor</th><th></th></tr></thead>
              <tbody>{carrinhoGuias.map((g, idx) => (<tr key={idx} style={{ borderBottom: `1px solid ${T.border}` }}><td className="py-2 px-2" style={{ color: T.text }}>{g.numeroGuia}</td><td className="py-2 px-2">{fmtBRL(g.valor)}</td><td className="py-2 px-2 text-right"><button onClick={() => removerGuiaDoCarrinho(idx)}><Trash2 size={13} style={{ color: T.red }} /></button></td></tr>))}</tbody>
              <tfoot><tr><td className="py-2 px-2 font-bold" style={{ color: T.text }}>Total do lote</td><td className="py-2 px-2 font-bold">{fmtBRL(totalCarrinho)}</td><td></td></tr></tfoot>
            </table>
          </div>
        )}
        <Btn disabled={busy || carrinhoGuias.length === 0 || !numeroLote} onClick={fecharLote}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Fechar lote</Btn>
      </Card>

      {guiasOrfas.length > 0 && (
        <Card className="mb-5" style={{ borderColor: `${T.amber}55`, background: `${T.amber}10` }}>
          <div className="flex items-center gap-2 mb-2"><AlertTriangle size={15} style={{ color: T.amber }} /><span className="font-semibold text-sm" style={{ color: T.text }}>{guiasOrfas.length} guia(s) do Bradesco em Contas a Receber sem lote vinculado aqui</span></div>
          <p className="text-xs mb-3" style={{ color: T.muted }}>Isso é o que causava a diferença de valores entre as duas telas. Vincule cada uma a um lote já existente, ou crie um lote avulso só pra ela.</p>
          <div className="flex flex-col gap-2">
            {guiasOrfas.map((f) => (
              <div key={f.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl px-3 py-2" style={{ background: T.card, border: `1px solid ${T.border}` }}>
                <span className="text-sm" style={{ color: T.text }}>{f.convenio} — {f.numeroGuia || "sem nº"} — {fmtBRL(f.valor)} — <Badge tone="muted">{f.status}</Badge></span>
                <div className="flex items-center gap-2">
                  <select className="rounded-lg px-2 py-1.5 text-xs outline-none" style={inputStyle} value={loteParaVincular[f.id] || ""} onChange={(e) => setLoteParaVincular((p) => ({ ...p, [f.id]: e.target.value }))}>
                    <option value="">Escolher lote…</option>
                    {protocolos.map((p) => <option key={p.id} value={p.id}>{p.numeroLote}</option>)}
                  </select>
                  <Btn small variant="ghost" onClick={() => vincularOrfaExistente(f)}>Vincular</Btn>
                  <Btn small tone="teal" onClick={() => criarLoteSoParaOrfa(f)}>Criar lote avulso</Btn>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      <Card>
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Lotes ({protocolosFiltrados.length})</p>
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> :
          protocolosFiltrados.length === 0 ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}>Nenhum lote no período selecionado.</div> : (
          <div className="flex flex-col gap-3">
            {protocolosFiltrados.map((lote) => {
              const guiasDesteLote = guiasDoLote.filter((g) => g.protocoloBradescoId === lote.id);
              const totalLote = guiasDesteLote.reduce((s, g) => s + Number(g.valor), 0);
              return (
                <div key={lote.id} className="rounded-xl px-4 py-3" style={{ background: "#FBFAF6", border: `1px solid ${T.border}` }}>
                  <div className="flex items-center justify-between mb-2">
                    <span className="font-semibold text-sm" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>{lote.numeroLote} <span className="text-xs font-normal" style={{ color: T.muted }}>— envio {fmtDate(lote.dataEnvio)} — {guiasDesteLote.length} guia(s)</span></span>
                    <div className="flex items-center gap-3">
                      <span style={{ color: T.text, fontWeight: 700 }}>{fmtBRL(totalLote)}</span>
                      <button onClick={() => { if (confirm("Remover este lote e todas as suas guias?")) removeLote(lote.id); }}><Trash2 size={13} style={{ color: T.red }} /></button>
                    </div>
                  </div>
                  <table className="w-full text-sm">
                    <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}>
                      <th className="text-left py-1.5 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Guia</th>
                      <th className="text-left py-1.5 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor</th>
                      <th className="text-left py-1.5 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Status</th>
                    </tr></thead>
                    <tbody>{guiasDesteLote.map((g) => (
                      <tr key={g.id}>
                        <td className="py-1.5 px-2" style={{ color: T.text }}>{g.numeroGuia}</td>
                        <td className="py-1.5 px-2">{fmtBRL(g.valor)}</td>
                        <td className="py-1.5 px-2">
                          <select className="rounded-lg px-2 py-1 text-xs outline-none" style={inputStyle} value={statusDaGuiaFaturamento(g.faturamentoGuiaId)} onChange={(e) => alterarStatusGuia(g.faturamentoGuiaId, e.target.value)}>
                            <option value="Protocolada">Protocolada</option><option value="Faturada">Faturada</option><option value="Paga">Paga</option><option value="Vencida">Vencida</option>
                          </select>
                        </td>
                      </tr>
                    ))}</tbody>
                  </table>
                </div>
              );
            })}
          </div>
        )}
      </Card>
    </>
  );
}

function ProtocoloGuiasModulo() {
  const { perfil } = useAuth();
  const { data: profissionais } = useRecords("cadProfissionais");
  const { data: conveniosCadastro } = useRecords("cadConvenios");
  const { data: protocolos, add, remove, loading, erro } = useRecords("protocolosGuias");
  const nomesProfissionais = profissionais.map((p) => p.nome);
  const opcoesConvenio = conveniosCadastro.length ? conveniosCadastro.map((c) => c.nome) : CONVENIOS;
  const [dataProtocolo, setDataProtocolo] = useState(todayISO());
  const [itens, setItens] = useState([]);
  const [busy, setBusy] = useState(false);
  const [profissionalSel, setProfissionalSel] = useState("");
  const [convenioSel, setConvenioSel] = useState("");
  const [qtdSel, setQtdSel] = useState(1);

  const adicionarItem = () => {
    if (!profissionalSel || !convenioSel) return;
    setItens((p) => [...p, { profissional: profissionalSel, convenio: convenioSel, quantidade: Number(qtdSel) || 1 }]);
    setProfissionalSel(""); setConvenioSel(""); setQtdSel(1);
  };
  const removerItem = (idx) => setItens((p) => p.filter((_, i) => i !== idx));
  const totalGuias = itens.reduce((s, i) => s + Number(i.quantidade), 0);

  const fecharProtocolo = async () => {
    if (itens.length === 0) return alert("Adicione ao menos um item ao protocolo.");
    setBusy(true);
    const numero = gerarNumeroProtocolo(perfil.nome);
    await add({ numeroProtocolo: numero, dataProtocolo, itens, totalGuias, criadoPor: perfil.id, criadoPorNome: perfil.nome });
    setItens([]); setDataProtocolo(todayISO());
    setBusy(false);
  };

  return (
    <div>
      <SectionHeader icon={ClipboardList} title="Protocolo de Guias" subtitle="Monte o protocolo com vários profissionais e convênios, depois feche — o número é gerado automaticamente" tone="coral" />
      <Card className="mb-5">
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Data do protocolo"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={dataProtocolo} onChange={(e) => setDataProtocolo(e.target.value)} /></Field>
        </div>
        <p className="text-[11px] font-semibold uppercase mb-2" style={{ color: T.muted, letterSpacing: "0.06em" }}>Adicionar guia ao protocolo</p>
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Profissional">
            <select className="rounded-lg px-3 py-2 text-sm outline-none w-56" style={inputStyle} value={profissionalSel} onChange={(e) => setProfissionalSel(e.target.value)}>
              <option value="" disabled>Selecione…</option>
              {nomesProfissionais.map((p) => <option key={p} value={p}>{p}</option>)}
            </select>
          </Field>
          <Field label="Convênio">
            <select className="rounded-lg px-3 py-2 text-sm outline-none w-52" style={inputStyle} value={convenioSel} onChange={(e) => setConvenioSel(e.target.value)}>
              <option value="" disabled>Selecione…</option>
              {opcoesConvenio.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </Field>
          <Field label="Quantidade de guias"><input type="number" min="1" className="rounded-lg px-3 py-2 text-sm outline-none w-28" style={inputStyle} value={qtdSel} onChange={(e) => setQtdSel(e.target.value)} /></Field>
          <Btn small tone="teal" icon={Plus} onClick={adicionarItem}>Adicionar</Btn>
        </div>
        {itens.length > 0 && (
          <div className="mb-4">
            <table className="w-full text-sm">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Profissional</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Convênio</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Guias</th><th></th></tr></thead>
              <tbody>{itens.map((it, idx) => (
                <tr key={idx} style={{ borderBottom: `1px solid ${T.border}` }}>
                  <td className="py-2 px-2" style={{ color: T.text }}>{it.profissional}</td><td className="py-2 px-2">{it.convenio}</td><td className="py-2 px-2">{it.quantidade}</td>
                  <td className="py-2 px-2 text-right"><button onClick={() => removerItem(idx)}><Trash2 size={13} style={{ color: T.red }} /></button></td>
                </tr>
              ))}</tbody>
              <tfoot><tr><td className="py-2 px-2 font-bold" style={{ color: T.text }}>Total</td><td></td><td className="py-2 px-2 font-bold">{totalGuias}</td><td></td></tr></tfoot>
            </table>
          </div>
        )}
        <Btn disabled={busy || itens.length === 0} onClick={fecharProtocolo}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Fechar protocolo</Btn>
      </Card>
      <Card>
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Protocolos fechados ({protocolos.length})</p>
        {erro && <p className="text-sm mb-3" style={{ color: T.red }}>{erro}</p>}
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> :
          protocolos.length === 0 ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}>Nenhum protocolo fechado ainda.</div> : (
          <div className="flex flex-col gap-2">
            {protocolos.map((p) => (
              <div key={p.id} className="rounded-xl px-4 py-3" style={{ background: "#FBFAF6", border: `1px solid ${T.border}` }}>
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>Protocolo {p.numeroProtocolo}</span>
                  <div className="flex items-center gap-3">
                    <span style={{ color: T.green, fontWeight: 700 }}>{p.totalGuias} guia(s)</span>
                    <button onClick={() => { if (confirm("Remover este protocolo?")) remove(p.id); }}><Trash2 size={13} style={{ color: T.red }} /></button>
                  </div>
                </div>
                <p className="text-xs" style={{ color: T.muted }}>{fmtDate(p.dataProtocolo)} — lançado por {p.criadoPorNome}</p>
                <p className="text-xs mt-1" style={{ color: T.muted }}>{(p.itens || []).map((i) => `${i.profissional} (${i.convenio}: ${i.quantidade})`).join(", ")}</p>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

/* ============================== INDICAÇÃO ============================== */
function CadastroCampanhasIndicacaoModulo() {
  const { data, add, update, remove, loading, erro } = useRecords("cadCampanhasIndicacao");
  const fields = [
    { key: "nome", label: "Nome da campanha", type: "text", placeholder: "ex: Campanha Indique e Ganhe — Agosto" },
    { key: "dataInicio", label: "Data de início", type: "date", required: false },
    { key: "dataFim", label: "Data de fim", type: "date", required: false },
    { key: "descricao", label: "Descrição / prêmio", type: "textarea", required: false },
  ];
  const columns = [{ key: "nome", label: "Campanha" }, { key: "dataInicio", label: "Início", render: (r) => r.dataInicio ? fmtDate(r.dataInicio) : "—" }, { key: "dataFim", label: "Fim", render: (r) => r.dataFim ? fmtDate(r.dataFim) : "—" }, { key: "descricao", label: "Descrição" }];
  return (
    <ModuleShell icon={Megaphone} title="Campanhas de Indicação" subtitle="Cadastre as campanhas — depois é só escolher em qual cada indicação está concorrendo" tone="rose" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Cadastrar campanha" fields={fields} columns={columns} rows={data} onAdd={add} onUpdate={update} onDelete={remove} />
  );
}

function IndicacaoModulo() {
  const { perfil } = useAuth();
  const { data: campanhas } = useRecords("cadCampanhasIndicacao");
  const { data: conveniosCat } = useRecords("cadConvenios");
  const { data: indicacoes, add, remove, loading, erro } = useRecords("indicacoes");
  const nomesConvenios = conveniosCat.length ? conveniosCat.map((c) => c.nome) : CONVENIOS;
  const CANAIS = ["WhatsApp", "Google", "TikTok", "Instagram", "Facebook", "Ligação", "Presencial", "Outro"];

  const [data, setData] = useState(todayISO());
  const [nomeIndicador, setNomeIndicador] = useState("");
  const [telefoneIndicador, setTelefoneIndicador] = useState("");
  const [convenio, setConvenio] = useState("");
  const [canalContato, setCanalContato] = useState("");
  const [campanhaId, setCampanhaId] = useState("");
  const [indicados, setIndicados] = useState([]);
  const [nomeIndicado, setNomeIndicado] = useState("");
  const [telefoneIndicado, setTelefoneIndicado] = useState("");
  const [busy, setBusy] = useState(false);

  const adicionarIndicado = () => {
    if (!nomeIndicado) return;
    setIndicados((p) => [...p, { nome: nomeIndicado, telefone: telefoneIndicado }]);
    setNomeIndicado(""); setTelefoneIndicado("");
  };
  const removerIndicado = (idx) => setIndicados((p) => p.filter((_, i) => i !== idx));

  const registrarIndicacao = async () => {
    if (!nomeIndicador || indicados.length === 0) return alert("Informe quem indicou e adicione ao menos um indicado.");
    setBusy(true);
    await add({ data, nomeIndicador, telefoneIndicador, convenio: convenio || null, canalContato: canalContato || null, campanhaId: campanhaId || null, indicados, criadoPor: perfil.id, criadoPorNome: perfil.nome });
    setNomeIndicador(""); setTelefoneIndicador(""); setConvenio(""); setCanalContato(""); setCampanhaId(""); setIndicados([]); setData(todayISO());
    setBusy(false);
  };

  const nomeCampanha = (id) => (campanhas.find((c) => c.id === id) || {}).nome || "—";

  const [filtroMes, setFiltroMes] = useState("");
  const [filtroDe, setFiltroDe] = useState("");
  const [filtroAte, setFiltroAte] = useState("");
  const [filtroCampanha, setFiltroCampanha] = useState("");
  const indicacoesFiltradas = filtrarPorPeriodo(indicacoes, "data", filtroMes, filtroDe, filtroAte).filter((r) => !filtroCampanha || r.campanhaId === filtroCampanha);

  const totalIndicadores = indicacoesFiltradas.length;
  const totalIndicados = indicacoesFiltradas.reduce((s, r) => s + (r.indicados || []).length, 0);

  // Uma linha por indicado — pronto para o sorteio
  const linhasParaSorteio = indicacoesFiltradas.flatMap((r) => (r.indicados || []).map((ind) => ({
    data: fmtDate(r.data), campanha: nomeCampanha(r.campanhaId), nomeIndicador: r.nomeIndicador, telefoneIndicador: r.telefoneIndicador || "",
    nomeIndicado: ind.nome, telefoneIndicado: ind.telefone || "",
  })));
  const camposSorteio = [{ key: "data", label: "Data" }, { key: "campanha", label: "Campanha" }, { key: "nomeIndicador", label: "Indicado por" }, { key: "telefoneIndicador", label: "Telefone de quem indicou" }, { key: "nomeIndicado", label: "Nome do indicado" }, { key: "telefoneIndicado", label: "Telefone do indicado" }];

  return (
    <div>
      <SectionHeader icon={Megaphone} title="Indicação" subtitle="Registre quem indicou e quem foi indicado — gera lista pronta para sorteio" tone="rose" />
      <Card className="mb-5">
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Data"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={data} onChange={(e) => setData(e.target.value)} /></Field>
          <Field label="Nome de quem indicou"><input className="rounded-lg px-3 py-2 text-sm outline-none w-48" style={inputStyle} value={nomeIndicador} onChange={(e) => setNomeIndicador(e.target.value)} /></Field>
          <Field label="Telefone"><input className="rounded-lg px-3 py-2 text-sm outline-none w-36" style={inputStyle} value={telefoneIndicador} onChange={(e) => setTelefoneIndicador(e.target.value)} /></Field>
          <Field label="Convênio (opcional)"><select className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={convenio} onChange={(e) => setConvenio(e.target.value)}><option value="">— não informar —</option>{nomesConvenios.map((c) => <option key={c} value={c}>{c}</option>)}</select></Field>
          <Field label="Contatada por qual canal"><select className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={canalContato} onChange={(e) => setCanalContato(e.target.value)}><option value="">— não informar —</option>{CANAIS.map((c) => <option key={c} value={c}>{c}</option>)}</select></Field>
          <Field label="Campanha"><select className="rounded-lg px-3 py-2 text-sm outline-none w-52" style={inputStyle} value={campanhaId} onChange={(e) => setCampanhaId(e.target.value)}><option value="">— nenhuma —</option>{campanhas.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
        </div>
        <p className="text-[11px] font-semibold uppercase mb-2" style={{ color: T.muted, letterSpacing: "0.06em" }}>Adicionar indicação (quantas quiser)</p>
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Nome do indicado"><input className="rounded-lg px-3 py-2 text-sm outline-none w-48" style={inputStyle} value={nomeIndicado} onChange={(e) => setNomeIndicado(e.target.value)} /></Field>
          <Field label="Telefone do indicado"><input className="rounded-lg px-3 py-2 text-sm outline-none w-36" style={inputStyle} value={telefoneIndicado} onChange={(e) => setTelefoneIndicado(e.target.value)} /></Field>
          <Btn small tone="teal" icon={Plus} onClick={adicionarIndicado}>Adicionar indicado</Btn>
        </div>
        {indicados.length > 0 && (
          <div className="mb-4">
            <table className="w-full text-sm">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Indicado</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Telefone</th><th></th></tr></thead>
              <tbody>{indicados.map((ind, idx) => (<tr key={idx} style={{ borderBottom: `1px solid ${T.border}` }}><td className="py-2 px-2" style={{ color: T.text }}>{ind.nome}</td><td className="py-2 px-2">{ind.telefone}</td><td className="py-2 px-2 text-right"><button onClick={() => removerIndicado(idx)}><Trash2 size={13} style={{ color: T.red }} /></button></td></tr>))}</tbody>
            </table>
          </div>
        )}
        <Btn disabled={busy || indicados.length === 0 || !nomeIndicador} onClick={registrarIndicacao}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Registrar indicação</Btn>
      </Card>

      <Card className="mb-5">
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Filtrar por competência, período ou campanha — e exportar (inclusive para o sorteio)</p>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Competência (mês)"><input type="month" className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={filtroMes} onChange={(e) => { setFiltroMes(e.target.value); setFiltroDe(""); setFiltroAte(""); }} /></Field>
          <Field label="De"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={filtroDe} onChange={(e) => { setFiltroDe(e.target.value); setFiltroMes(""); }} /></Field>
          <Field label="Até"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={filtroAte} onChange={(e) => { setFiltroAte(e.target.value); setFiltroMes(""); }} /></Field>
          <Field label="Campanha"><select className="rounded-lg px-3 py-2 text-sm outline-none w-52" style={inputStyle} value={filtroCampanha} onChange={(e) => setFiltroCampanha(e.target.value)}><option value="">Todas</option>{campanhas.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
          {(filtroMes || filtroDe || filtroAte || filtroCampanha) && <Btn small variant="ghost" onClick={() => { setFiltroMes(""); setFiltroDe(""); setFiltroAte(""); setFiltroCampanha(""); }}>Limpar filtro</Btn>}
        </div>
        <div className="flex gap-2 mt-4">
          <Btn small variant="ghost" icon={Download} onClick={() => exportToCSV(camposSorteio, linhasParaSorteio, "indicacoes-sorteio")}>CSV</Btn>
          <Btn small tone="teal" icon={Download} onClick={() => exportToExcel(camposSorteio, linhasParaSorteio, "indicacoes-sorteio")}>Excel</Btn>
          <Btn small variant="ghost" icon={Printer} onClick={() => exportToPDF(camposSorteio, linhasParaSorteio, "indicacoes-sorteio")}>PDF</Btn>
        </div>
      </Card>

      <div className="grid gap-3 mb-5 md:grid-cols-3">
        <KpiCard label="Indicadores no período" value={totalIndicadores} tone="rose" />
        <KpiCard label="Total de indicados (entradas p/ sorteio)" value={totalIndicados} tone="teal" />
        <KpiCard label="Campanhas cadastradas" value={campanhas.length} />
      </div>

      <Card>
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Indicações registradas</p>
        {erro && <p className="text-sm mb-3" style={{ color: T.red }}>{erro}</p>}
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> :
          indicacoesFiltradas.length === 0 ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}>Nenhuma indicação no período/campanha selecionado.</div> : (
          <div className="flex flex-col gap-2">
            {indicacoesFiltradas.map((r) => (
              <div key={r.id} className="rounded-xl px-4 py-3" style={{ background: "#FBFAF6", border: `1px solid ${T.border}` }}>
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm" style={{ color: T.text }}>{r.nomeIndicador} <span className="text-xs font-normal" style={{ color: T.muted }}>({r.telefoneIndicador || "sem telefone"})</span></span>
                  <div className="flex items-center gap-3">
                    {r.campanhaId && <Badge tone="rose">{nomeCampanha(r.campanhaId)}</Badge>}
                    <span style={{ color: T.muted }}>{fmtDate(r.data)}</span>
                    <button onClick={() => { if (confirm("Remover esta indicação?")) remove(r.id); }}><Trash2 size={13} style={{ color: T.red }} /></button>
                  </div>
                </div>
                <p className="text-xs" style={{ color: T.muted }}>{(r.indicados || []).length} indicado(s): {(r.indicados || []).map((i) => i.nome).join(", ")}</p>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

function PacoteVacinasModulo() {
  const { data: vacinasCat, update: updateVacina, loading: loadingVacinas } = useRecords("vacinas");
  const { data: pacotes, add, remove, loading, erro } = useRecords("vendasVacinasPacotes");
  const [paciente, setPaciente] = useState("");
  const [data, setData] = useState(todayISO());
  const [itens, setItens] = useState([]);
  const [descontoTipo, setDescontoTipo] = useState("Nenhum");
  const [descontoValor, setDescontoValor] = useState("");
  const [busy, setBusy] = useState(false);
  const [selecionada, setSelecionada] = useState("");
  const [qtdSelecionada, setQtdSelecionada] = useState(1);

  const adicionarItem = () => {
    const vac = vacinasCat.find((v) => v.nome === selecionada);
    if (!vac) return;
    setItens((p) => [...p, { vacinaId: vac.id, nome: vac.nome, quantidade: Number(qtdSelecionada) || 1, valorUnitario: vac.valorVenda, subtotal: (Number(qtdSelecionada) || 1) * vac.valorVenda }]);
    setSelecionada(""); setQtdSelecionada(1);
  };
  const removerItem = (idx) => setItens((p) => p.filter((_, i) => i !== idx));

  const subtotalGeral = itens.reduce((s, i) => s + i.subtotal, 0);
  const valorDesconto = descontoTipo === "Reais" ? Number(descontoValor || 0) : descontoTipo === "Percentual" ? subtotalGeral * (Number(descontoValor || 0) / 100) : 0;
  const valorFinal = Math.max(subtotalGeral - valorDesconto, 0);

  const finalizarPacote = async () => {
    if (!paciente || itens.length === 0) return alert("Informe o paciente e adicione ao menos uma vacina.");
    setBusy(true);
    await add({ data, paciente, itens, descontoTipo, descontoValor: Number(descontoValor || 0), valorTotal: valorFinal });
    for (const item of itens) {
      const vac = vacinasCat.find((v) => v.id === item.vacinaId);
      if (vac) await updateVacina(vac.id, { qtdEstoque: Math.max(Number(vac.qtdEstoque) - item.quantidade, 0), qtdVendidaMes: Number(vac.qtdVendidaMes) + item.quantidade });
    }
    setPaciente(""); setItens([]); setDescontoTipo("Nenhum"); setDescontoValor(""); setData(todayISO());
    setBusy(false);
  };

  const totalPacotes = pacotes.reduce((s, p) => s + Number(p.valorTotal), 0);

  return (
    <div>
      <SectionHeader icon={Syringe} title="Pacote Personalizado de Vacinas" subtitle="Monte um pacote com várias vacinas, aplique desconto e o total calcula sozinho" tone="teal" />
      <Card className="mb-5">
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Paciente"><input className="rounded-lg px-3 py-2 text-sm outline-none w-48" style={inputStyle} value={paciente} onChange={(e) => setPaciente(e.target.value)} /></Field>
          <Field label="Data"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={data} onChange={(e) => setData(e.target.value)} /></Field>
        </div>
        <p className="text-[11px] font-semibold uppercase mb-2" style={{ color: T.muted, letterSpacing: "0.06em" }}>Adicionar vacina ao pacote</p>
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Vacina">
            <select className="rounded-lg px-3 py-2 text-sm outline-none w-56" style={inputStyle} value={selecionada} onChange={(e) => setSelecionada(e.target.value)}>
              <option value="" disabled>Selecione…</option>
              {vacinasCat.map((v) => <option key={v.id} value={v.nome}>{v.nome} — {fmtBRL(v.valorVenda)}</option>)}
            </select>
          </Field>
          <Field label="Quantidade"><input type="number" min="1" className="rounded-lg px-3 py-2 text-sm outline-none w-24" style={inputStyle} value={qtdSelecionada} onChange={(e) => setQtdSelecionada(e.target.value)} /></Field>
          <Btn small tone="teal" icon={Plus} onClick={adicionarItem}>Adicionar ao pacote</Btn>
        </div>
        {itens.length > 0 && (
          <div className="mb-4">
            <table className="w-full text-sm">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Vacina</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Qtd.</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor unit.</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Subtotal</th><th></th></tr></thead>
              <tbody>{itens.map((item, idx) => (
                <tr key={idx} style={{ borderBottom: `1px solid ${T.border}` }}>
                  <td className="py-2 px-2" style={{ color: T.text }}>{item.nome}</td><td className="py-2 px-2">{item.quantidade}</td><td className="py-2 px-2">{fmtBRL(item.valorUnitario)}</td><td className="py-2 px-2">{fmtBRL(item.subtotal)}</td>
                  <td className="py-2 px-2 text-right"><button onClick={() => removerItem(idx)}><Trash2 size={13} style={{ color: T.red }} /></button></td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
        <div className="flex flex-wrap gap-3 items-end mb-4">
          <Field label="Desconto — tipo"><select className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={descontoTipo} onChange={(e) => setDescontoTipo(e.target.value)}><option value="Nenhum">Nenhum</option><option value="Reais">Em Reais (R$)</option><option value="Percentual">Em Porcentagem (%)</option></select></Field>
          {descontoTipo !== "Nenhum" && <Field label={descontoTipo === "Reais" ? "Valor do desconto (R$)" : "Desconto (%)"}><input type="number" className="rounded-lg px-3 py-2 text-sm outline-none w-32" style={inputStyle} value={descontoValor} onChange={(e) => setDescontoValor(e.target.value)} /></Field>}
        </div>
        <div className="rounded-xl p-4 mb-4" style={{ background: `${T.teal}10`, border: `1px solid ${T.teal}30` }}>
          <div className="flex justify-between text-sm mb-1"><span style={{ color: T.muted }}>Subtotal</span><span style={{ color: T.text }}>{fmtBRL(subtotalGeral)}</span></div>
          {valorDesconto > 0 && <div className="flex justify-between text-sm mb-1"><span style={{ color: T.muted }}>Desconto</span><span style={{ color: T.red }}>- {fmtBRL(valorDesconto)}</span></div>}
          <div className="flex justify-between text-base font-bold mt-2 pt-2" style={{ borderTop: `1px solid ${T.teal}30` }}><span style={{ color: T.text }}>Total do pacote</span><span style={{ color: T.green }}>{fmtBRL(valorFinal)}</span></div>
        </div>
        <Btn disabled={busy || loadingVacinas} onClick={finalizarPacote}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Finalizar pacote</Btn>
      </Card>
      <Card>
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Pacotes registrados ({fmtBRL(totalPacotes)} no total)</p>
        {erro && <p className="text-sm mb-3" style={{ color: T.red }}>{erro}</p>}
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> :
          pacotes.length === 0 ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}>Nenhum pacote registrado ainda.</div> : (
          <div className="flex flex-col gap-2">
            {pacotes.map((p) => (
              <div key={p.id} className="rounded-xl px-4 py-3" style={{ background: "#FBFAF6", border: `1px solid ${T.border}` }}>
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm" style={{ color: T.text }}>{p.paciente} — {fmtDate(p.data)}</span>
                  <div className="flex items-center gap-3">
                    <span style={{ color: T.green, fontWeight: 700 }}>{fmtBRL(p.valorTotal)}</span>
                    <button onClick={() => { if (confirm("Remover este pacote? (não devolve ao estoque automaticamente)")) remove(p.id); }}><Trash2 size={13} style={{ color: T.red }} /></button>
                  </div>
                </div>
                <p className="text-xs" style={{ color: T.muted }}>{(p.itens || []).map((i) => `${i.nome} (${i.quantidade}x)`).join(", ")}</p>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

function MarcarPagoCell({ vencimento, onConfirmar }) {
  const [abrir, setAbrir] = useState(false);
  const [data, setData] = useState(vencimento || todayISO());
  const [busy, setBusy] = useState(false);
  if (!abrir) return <Btn small tone="green" onClick={() => setAbrir(true)}>Marcar como pago</Btn>;
  return (
    <div className="flex items-center gap-1.5">
      <input type="date" className="rounded-lg px-2 py-1.5 text-xs outline-none" style={inputStyle} value={data} onChange={(e) => setData(e.target.value)} />
      <Btn small tone="green" disabled={busy || !data} onClick={async () => { setBusy(true); await onConfirmar(data); setBusy(false); setAbrir(false); }}>{busy ? "…" : "Confirmar"}</Btn>
      <button onClick={() => setAbrir(false)} className="text-xs" style={{ color: T.muted }}>Cancelar</button>
    </div>
  );
}

function AjusteEstoqueCell({ onAjustar, placeholder, tone = "ink" }) {
  const [valor, setValor] = useState("");
  const [busy, setBusy] = useState(false);
  return (
    <div className="flex items-center gap-1.5">
      <input type="number" min="0" className="rounded-lg px-2 py-1.5 text-xs outline-none w-16" style={inputStyle} placeholder={placeholder} value={valor} onChange={(e) => setValor(e.target.value)} />
      <Btn small tone={tone} disabled={busy || !valor} onClick={async () => { setBusy(true); await onAjustar(Number(valor)); setValor(""); setBusy(false); }}>{busy ? "…" : "OK"}</Btn>
    </div>
  );
}

function InsumosModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("insumos");
  const fields = [
    { key: "nome", label: "Item", type: "text" },
    { key: "categoria", label: "Categoria", type: "select", options: ["Material médico", "EPI", "Limpeza", "Escritório", "Outros"] },
    { key: "qtd", label: "Qtd. atual (nº de embalagens)", type: "number" },
    { key: "tipoEmbalagem", label: "Tipo de embalagem", type: "select", options: ["Unidade", "Bloco", "Caixa", "Pacote"], default: "Unidade" },
    { key: "quantidadePorEmbalagem", label: "Quantos vêm em cada embalagem", type: "number", required: false, default: 1, showIf: (f) => f.tipoEmbalagem && f.tipoEmbalagem !== "Unidade" },
    { key: "qtdMinima", label: "Qtd. mínima (em embalagens)", type: "number" },
    { key: "unidade", label: "O que se conta dentro (opcional)", type: "text", placeholder: "folhas, litros, pares…", required: false },
    { key: "valorUnitario", label: "Valor por embalagem (R$)", type: "currency" },
  ];
  const totalReal = (r) => Number(r.qtd || 0) * Number(r.quantidadePorEmbalagem || 1);
  const columns = [
    { key: "nome", label: "Item" }, { key: "categoria", label: "Categoria" },
    { key: "qtd", label: "Qtd.", render: (r) => <span className="flex items-center gap-1.5">{r.qtd} {r.tipoEmbalagem}{r.qtd < r.qtdMinima && <AlertTriangle size={12} style={{ color: T.red }} />}</span> },
    { key: "totalReal", label: "Total real", render: (r) => r.tipoEmbalagem !== "Unidade" && r.quantidadePorEmbalagem > 1 ? <span className="text-xs" style={{ color: T.muted }}>{fmtNum(totalReal(r))} {r.unidade || "un."}</span> : "—" },
    { key: "qtdMinima", label: "Mínimo" }, { key: "valorUnitario", label: "Valor unit.", render: (r) => fmtBRL(r.valorUnitario) }, { key: "total", label: "Valor total", render: (r) => fmtBRL(r.qtd * r.valorUnitario) },
    { key: "retirar", label: "Registrar retirada", render: (r) => <AjusteEstoqueCell placeholder="qtd" tone="coral" onAjustar={async (qtd) => update(r.id, { qtd: Math.max(Number(r.qtd) - qtd, 0) })} /> },
  ];
  const valorTotal = data.reduce((s, r) => s + r.qtd * r.valorUnitario, 0); const critico = data.filter((r) => r.qtd < r.qtdMinima);
  return (
    <ModuleShell icon={Package} title="Estoque de Insumos" subtitle="Materiais médicos, EPIs, limpeza e escritório" tone="teal" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Atualizar/cadastrar item" fields={fields} columns={columns} rows={data} onAdd={add} onUpdate={update} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Itens cadastrados", value: data.length }, { label: "Valor em estoque", value: fmtBRL(valorTotal) }, { label: "Ponto crítico", value: critico.length, tone: critico.length ? "red" : "green" }, { label: "Categorias", value: new Set(data.map((r) => r.categoria)).size }]}
      charts={<ChartCard title="Itens críticos (atual x mínimo)"><BarChart data={critico.length ? critico : data}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="nome" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Legend wrapperStyle={{ fontSize: 12 }} /><Bar dataKey="qtd" name="Atual" fill={T.amber} radius={[4, 4, 0, 0]} /><Bar dataKey="qtdMinima" name="Mínimo" fill={`${T.amber}55`} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
  );
}

const CONVENIOS_TELA_PROPRIA = ["Particular", "Bradesco Clínica", "Aurora Saúde", "IPSM"];
const normalizarTexto = (s) => (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();

function ProducaoConvenioModulo({ convenioFixo, titulo, subtitulo, icon }) {
  const { data: todaProducao, add, bulkAdd, update, remove, loading, erro } = useRecords("producao");
  const { data: profissionais } = useRecords("cadProfissionais");
  const { data: conveniosCadastro } = useRecords("cadConvenios");
  const profissionaisDoConvenio = (convenioFixo && convenioFixo !== "Particular")
    ? profissionais.filter((p) => Array.isArray(p.conveniosAtendidos) && p.conveniosAtendidos.includes(convenioFixo))
    : profissionais;
  const nomesProfissionais = (profissionaisDoConvenio.length ? profissionaisDoConvenio : profissionais).map((p) => p.nome);
  const opcoesConvenio = convenioFixo ? [convenioFixo] : conveniosCadastro.map((c) => c.nome).filter((n) => !CONVENIOS_TELA_PROPRIA.includes(n));

  const data = convenioFixo ? todaProducao.filter((r) => r.convenio === convenioFixo) : todaProducao.filter((r) => r.convenio && !CONVENIOS_TELA_PROPRIA.includes(r.convenio));

  const fields = [
    { key: "profissional", label: "Profissional", type: "select", options: nomesProfissionais.length ? nomesProfissionais : ["Cadastre em Cadastros → Profissionais"] },
    ...(convenioFixo ? [] : [{ key: "convenio", label: "Convênio", type: "select", options: opcoesConvenio.length ? opcoesConvenio : ["Cadastre em Cadastros → Convênios"] }]),
    { key: "data", label: "Data do atendimento", type: "date", default: todayISO() },
    { key: "atendimentos", label: "Atendimentos", type: "number" },
    { key: "descontoTipo", label: "Desconto — tipo", type: "select", options: ["Nenhum", "Reais", "Percentual"], required: false, default: "Nenhum" },
    { key: "descontoValor", label: "Valor do desconto", type: "number", required: false, default: 0, showIf: (f) => f.descontoTipo && f.descontoTipo !== "Nenhum" },
  ];
  const computar = (r) => {
    const convenio = convenioFixo || r.convenio;
    let valorPorAtendimento = 0;
    if (convenio === "Particular") {
      const prof = profissionais.find((p) => p.nome === r.profissional);
      valorPorAtendimento = prof ? Number(prof.valorConsultaParticular || 0) : 0;
    } else {
      const cfgConvenio = conveniosCadastro.find((c) => normalizarTexto(c.nome) === normalizarTexto(convenio));
      valorPorAtendimento = cfgConvenio ? Number(cfgConvenio.valorPadrao || 0) : 0;
    }
    const valorBruto = Number(r.atendimentos || 0) * valorPorAtendimento;
    const descontoTipo = r.descontoTipo || "Nenhum";
    const descontoValor = Number(r.descontoValor || 0);
    const desconto = descontoTipo === "Reais" ? descontoValor : descontoTipo === "Percentual" ? valorBruto * (descontoValor / 100) : 0;
    const receita = Math.max(valorBruto - desconto, 0);
    return { convenio, receita, descontoTipo, descontoValor };
  };
  const onAddComputado = (record) => add({ ...record, ...computar(record) });
  const onUpdateComputado = (id, record) => update(id, { ...record, ...computar(record) });
  const tipoRepasseDe = (nomeProfissional) => { const p = profissionais.find((x) => x.nome === nomeProfissional); return p && p.tipoSublocacao ? p.tipoSublocacao : "—"; };
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) },
    { key: "profissional", label: "Profissional" },
    { key: "tipoRepasseInfo", label: "Tipo de repasse (cadastro)", render: (r) => <span className="text-xs" style={{ color: T.muted }}>{tipoRepasseDe(r.profissional)}</span> },
    ...(convenioFixo ? [] : [{ key: "convenio", label: "Convênio" }]),
    { key: "atendimentos", label: "Atendimentos" },
    { key: "desconto", label: "Desconto", render: (r) => r.descontoTipo && r.descontoTipo !== "Nenhum" ? <span className="text-xs" style={{ color: T.muted }}>{r.descontoTipo === "Reais" ? fmtBRL(r.descontoValor) : fmtPct(r.descontoValor)}</span> : <span style={{ color: T.muted }}>—</span> },
    { key: "receita", label: "Receita (automática)", render: (r) => <span style={{ color: T.green, fontWeight: 600 }}>{fmtBRL(r.receita)}</span> },
  ];

  // Resumo por profissional — junta automaticamente vários lançamentos do mesmo profissional
  const resumoPorProfissional = useMemo(() => {
    const map = {};
    data.forEach((r) => {
      if (!map[r.profissional]) map[r.profissional] = { profissional: r.profissional, atendimentos: 0, receita: 0 };
      map[r.profissional].atendimentos += Number(r.atendimentos);
      map[r.profissional].receita += Number(r.receita);
    });
    return Object.values(map).sort((a, b) => b.receita - a.receita);
  }, [data]);

  const totalReceita = data.reduce((s, r) => s + Number(r.receita), 0);
  const totalAtendimentos = data.reduce((s, r) => s + Number(r.atendimentos), 0);
  const maisProdutivo = resumoPorProfissional[0];

  return (
    <ModuleShell icon={icon || Stethoscope} title={titulo} subtitle={subtitulo} tone="teal" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar produção" fields={fields} columns={columns} rows={data} onAdd={onAddComputado} onUpdate={onUpdateComputado} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Receita gerada", value: fmtBRL(totalReceita), tone: "green" }, { label: "Atendimentos", value: fmtNum(totalAtendimentos), tone: "teal" }, { label: "Mais produtivo(a)", value: maisProdutivo ? maisProdutivo.profissional : "—", tone: "coral" }]}
      extra={<>
        {conveniosCadastro.length === 0 && <Card className="mb-5" style={{ borderColor: `${T.amber}55` }}><span className="text-sm" style={{ color: T.text }}>Nenhum convênio cadastrado ainda em Cadastros → Convênios — cadastre lá o "valor padrão por atendimento" para a receita ser calculada aqui.</span></Card>}
        {convenioFixo && convenioFixo !== "Particular" && !conveniosCadastro.find((c) => normalizarTexto(c.nome) === normalizarTexto(convenioFixo)) && (
          <Card className="mb-5" style={{ borderColor: `${T.red}55` }}><span className="text-sm" style={{ color: T.red }}>Não encontrei "{convenioFixo}" em Cadastros → Convênios — por isso a receita está saindo R$ 0,00. Cadastre esse convênio lá (o nome não precisa ser idêntico letra por letra, mas precisa existir).</span></Card>
        )}
        {convenioFixo && convenioFixo !== "Particular" && profissionaisDoConvenio.length === 0 && <Card className="mb-5" style={{ borderColor: `${T.amber}55` }}><span className="text-sm" style={{ color: T.text }}>Nenhum profissional marcado como atendendo "{convenioFixo}" ainda em Cadastros → Profissionais — por enquanto mostrando todos.</span></Card>}
        {resumoPorProfissional.length > 0 && (
          <Card className="mb-5">
            <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Resumo por profissional (lançamentos do mesmo dia já somados)</p>
            <div className="overflow-x-auto -mx-5 px-5">
              <table className="w-full text-sm">
                <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Profissional</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Atendimentos</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Receita</th></tr></thead>
                <tbody>{resumoPorProfissional.map((c) => (<tr key={c.profissional} style={{ borderBottom: `1px solid ${T.border}` }}><td className="py-2 px-2 font-medium" style={{ color: T.text }}>{c.profissional}</td><td className="py-2 px-2">{fmtNum(c.atendimentos)}</td><td className="py-2 px-2" style={{ color: T.green, fontWeight: 600 }}>{fmtBRL(c.receita)}</td></tr>))}</tbody>
                <tfoot><tr><td className="py-2 px-2 font-bold" style={{ color: T.text }}>Total</td><td className="py-2 px-2 font-bold">{fmtNum(totalAtendimentos)}</td><td className="py-2 px-2 font-bold" style={{ color: T.green }}>{fmtBRL(totalReceita)}</td></tr></tfoot>
              </table>
            </div>
          </Card>
        )}
      </>}
      charts={<ChartCard title="Receita por profissional"><BarChart data={resumoPorProfissional}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="profissional" tick={{ fontSize: 11, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} /><Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="receita" name="Receita" fill={T.teal} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
  );
}
function ProducaoParticularesModulo() { return <ProducaoConvenioModulo convenioFixo="Particular" titulo="Produção Médica — Particulares" subtitulo="Atendimentos particulares" icon={Stethoscope} />; }
function ProducaoConveniosGeralModulo() { return <ProducaoConvenioModulo titulo="Produção Médica — Convênios" subtitulo="Demais convênios cadastrados" icon={HeartHandshake} />; }
function ProducaoBradescoClinicaModulo() { return <ProducaoConvenioModulo convenioFixo="Bradesco Clínica" titulo="Produção Médica — Bradesco Clínica" subtitulo="Atendimentos pelo convênio Bradesco Clínica" icon={HeartHandshake} />; }
function ProducaoAuroraSaudeModulo() { return <ProducaoConvenioModulo convenioFixo="Aurora Saúde" titulo="Produção Médica — Aurora Saúde" subtitulo="Atendimentos pelo convênio Aurora Saúde" icon={HeartHandshake} />; }
function ProducaoIpsmModulo() { return <ProducaoConvenioModulo convenioFixo="IPSM" titulo="Produção Médica — IPSM" subtitulo="Atendimentos pelo convênio IPSM" icon={HeartHandshake} />; }

function ProducaoResumoGeralModulo() {
  const { data, loading, erro } = useRecords("producao");
  const porMedico = useMemo(() => { const map = {}; data.forEach((r) => { if (!map[r.profissional]) map[r.profissional] = { profissional: r.profissional, atendimentos: 0, receita: 0 }; map[r.profissional].atendimentos += Number(r.atendimentos); map[r.profissional].receita += Number(r.receita); }); return Object.values(map).sort((a, b) => b.receita - a.receita); }, [data]);
  const porConvenio = useMemo(() => { const map = {}; data.forEach((r) => { if (!r.convenio) return; if (!map[r.convenio]) map[r.convenio] = { convenio: r.convenio, atendimentos: 0, receita: 0 }; map[r.convenio].atendimentos += Number(r.atendimentos); map[r.convenio].receita += Number(r.receita); }); return Object.values(map).sort((a, b) => b.receita - a.receita); }, [data]);
  const totalReceita = data.reduce((s, r) => s + Number(r.receita), 0);
  const totalAtendimentos = data.reduce((s, r) => s + Number(r.atendimentos), 0);
  return (
    <div>
      <SectionHeader icon={Stethoscope} title="Produção Médica — Valores Gerais" subtitle="Resumo de todas as telas de produção (particular, convênios) somadas — só administradores e gestores" tone="coral" />
      {erro && <Card className="mb-5" style={{ borderColor: `${T.red}55` }}><span className="text-sm" style={{ color: T.red }}>Erro ao carregar: {erro}</span></Card>}
      <div className="grid gap-3 mb-6 md:grid-cols-3">
        <KpiCard label="Receita total produzida" value={fmtBRL(totalReceita)} tone="green" />
        <KpiCard label="Atendimentos totais" value={fmtNum(totalAtendimentos)} tone="teal" />
        <KpiCard label="Profissionais ativos" value={porMedico.length} tone="coral" />
      </div>
      <div className="grid md:grid-cols-2 gap-5 mb-5">
        <ChartCard title="Valor produzido por médico"><BarChart data={porMedico}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="profissional" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} /><YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} /><Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="receita" fill={T.teal} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>
        <ChartCard title="Valor produzido por convênio"><PieChart><Pie data={porConvenio} dataKey="receita" nameKey="convenio" innerRadius={55} outerRadius={85} paddingAngle={2}>{porConvenio.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip formatter={(v) => fmtBRL(v)} /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart></ChartCard>
      </div>
      <div className="grid md:grid-cols-2 gap-5">
        <Card>
          <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Atendimentos e valor por médico</p>
          {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> : (
            <div className="overflow-x-auto -mx-5 px-5"><table className="w-full text-sm"><thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Médico</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Atendimentos</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor</th></tr></thead>
              <tbody>{porMedico.map((m) => (<tr key={m.profissional} style={{ borderBottom: `1px solid ${T.border}` }}><td className="py-2 px-2 font-medium" style={{ color: T.text }}>{m.profissional}</td><td className="py-2 px-2">{fmtNum(m.atendimentos)}</td><td className="py-2 px-2" style={{ color: T.green, fontWeight: 600 }}>{fmtBRL(m.receita)}</td></tr>))}</tbody>
            </table></div>
          )}
        </Card>
        <Card>
          <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Atendimentos e valor por convênio</p>
          {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> : (
            <div className="overflow-x-auto -mx-5 px-5"><table className="w-full text-sm"><thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Convênio</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Atendimentos</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor</th></tr></thead>
              <tbody>{porConvenio.map((c) => (<tr key={c.convenio} style={{ borderBottom: `1px solid ${T.border}` }}><td className="py-2 px-2 font-medium" style={{ color: T.text }}>{c.convenio}</td><td className="py-2 px-2">{fmtNum(c.atendimentos)}</td><td className="py-2 px-2" style={{ color: T.green, fontWeight: 600 }}>{fmtBRL(c.receita)}</td></tr>))}</tbody>
            </table></div>
          )}
        </Card>
      </div>
    </div>
  );
}

function ContasModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("contas");
  const { data: categoriasCadastro } = useRecords("cadCategorias");
  const { data: tiposPagamentoCadastro } = useRecords("cadTiposPagamento");
  const { data: bancosCadastro } = useRecords("cadBancos");
  const opcoesCategoria = categoriasCadastro.filter((c) => c.aplicacao === "Contas a Pagar" || c.aplicacao === "Geral").map((c) => c.nome);
  const opcoesTipoPagamento = tiposPagamentoCadastro.length ? tiposPagamentoCadastro.map((t) => t.nome) : TIPOS_PAGAMENTO_PADRAO;
  const nomesBancos = bancosCadastro.map((b) => b.nome);
  const fields = [
    { key: "descricao", label: "Descrição", type: "text" },
    { key: "categoria", label: "Categoria", type: "select", options: opcoesCategoria.length ? opcoesCategoria : ["Fornecedores", "Aluguel", "Salários", "Impostos", "Serviços", "Outros"] },
    { key: "valor", label: "Valor (R$)", type: "currency" },
    { key: "vencimento", label: "Vencimento", type: "date", default: todayISO() },
    { key: "status", label: "Status", type: "select", options: ["Pendente", "Pago", "Atrasado"] },
    { key: "dataPagamento", label: "Data de pagamento", type: "date", required: false },
    { key: "tipoPagamento", label: "Tipo de pagamento", type: "select", options: opcoesTipoPagamento, required: false },
    { key: "bancoNome", label: "Banco de onde será pago", type: "select", options: nomesBancos.length ? nomesBancos : ["Cadastre em Cadastros → Bancos"], required: false },
    { key: "recorrente", label: "Conta recorrente (repete todo mês)?", type: "checkbox", required: false, default: false },
    { key: "repetirMeses", label: "Repetir por quantos meses", type: "number", required: false, default: 12, showIf: (f) => !!f.recorrente },
  ];
  const onAddComputado = (record) => {
    const banco = bancosCadastro.find((b) => b.nome === record.bancoNome);
    const bancoId = banco ? banco.id : null;
    if (record.recorrente) {
      const meses = Number(record.repetirMeses) || 12;
      const grupoId = (typeof crypto !== "undefined" && crypto.randomUUID) ? crypto.randomUUID() : `grp-${Date.now()}`;
      const linhas = [];
      for (let i = 0; i < meses; i++) {
        const dt = new Date(record.vencimento + "T00:00:00");
        dt.setMonth(dt.getMonth() + i);
        linhas.push({ ...record, vencimento: dt.toISOString().slice(0, 10), bancoId, recorrente: true, grupoRecorrencia: grupoId, status: i === 0 ? record.status : "Pendente", dataPagamento: i === 0 ? record.dataPagamento : null });
      }
      return bulkAdd(linhas);
    }
    return add({ ...record, bancoId });
  };
  const onUpdateComputado = (id, record) => { const banco = bancosCadastro.find((b) => b.nome === record.bancoNome); return update(id, { ...record, bancoId: banco ? banco.id : null }); };
  const columns = [{ key: "descricao", label: "Descrição", render: (r) => <span>{r.descricao}{r.recorrente && <span className="ml-1.5" title="Conta recorrente">🔁</span>}</span> }, { key: "categoria", label: "Categoria" }, { key: "valor", label: "Valor", render: (r) => fmtBRL(r.valor) }, { key: "vencimento", label: "Vencimento", render: (r) => fmtDate(r.vencimento) },
    { key: "tipoPagamento", label: "Tipo pgto.", render: (r) => r.tipoPagamento || "—" },
    { key: "bancoNome", label: "Banco", render: (r) => (bancosCadastro.find((b) => b.id === r.bancoId) || {}).nome || "—" },
    { key: "status", label: "Status", render: (r) => <Badge tone={r.status === "Pago" ? "green" : r.status === "Atrasado" ? "red" : "amber"}>{r.status}</Badge> },
    { key: "acaoPagar", label: "", render: (r) => r.status !== "Pago" ? <MarcarPagoCell vencimento={r.vencimento} onConfirmar={(data) => update(r.id, { status: "Pago", dataPagamento: data })} /> : <span className="text-xs" style={{ color: T.muted }}>Pago em {fmtDate(r.dataPagamento)}</span> },
  ];
  const [filtroMes, setFiltroMes] = useState("");
  const [filtroDe, setFiltroDe] = useState("");
  const [filtroAte, setFiltroAte] = useState("");
  const dataFiltrada = filtrarPorPeriodo(data, "vencimento", filtroMes, filtroDe, filtroAte);
  const pendentes = dataFiltrada.filter((r) => r.status !== "Pago"), pagos = dataFiltrada.filter((r) => r.status === "Pago"); const atrasados = dataFiltrada.filter((r) => r.status === "Atrasado" || (r.status === "Pendente" && r.vencimento < todayISO()));
  const totalPendente = pendentes.reduce((s, r) => s + r.valor, 0), totalPago = pagos.reduce((s, r) => s + r.valor, 0);
  const proximos = pendentes.filter((r) => { const diff = (new Date(r.vencimento) - new Date(todayISO())) / 86400000; return diff >= 0 && diff <= 7; }).sort((a, b) => a.vencimento.localeCompare(b.vencimento));
  const porCategoria = useMemo(() => { const map = {}; pendentes.forEach((r) => { map[r.categoria] = (map[r.categoria] || 0) + r.valor; }); return Object.entries(map).map(([categoria, valor]) => ({ categoria, valor })); }, [pendentes]);
  return (
    <>
      <FiltroPeriodoBar filtroMes={filtroMes} setFiltroMes={setFiltroMes} filtroDe={filtroDe} setFiltroDe={setFiltroDe} filtroAte={filtroAte} setFiltroAte={setFiltroAte} />
    <ModuleShell icon={Receipt} title="Contas a Pagar" subtitle="Contas pendentes e pagas, mês a mês" tone="coral" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Lançar conta" fields={fields} columns={columns} rows={dataFiltrada} onAdd={onAddComputado} onUpdate={onUpdateComputado} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Total pendente", value: fmtBRL(totalPendente), tone: "amber" }, { label: "Total pago", value: fmtBRL(totalPago), tone: "green" }, { label: "Atrasadas", value: atrasados.length, tone: atrasados.length ? "red" : "green" }, { label: "Vencendo em 7 dias", value: proximos.length, tone: proximos.length ? "amber" : "green" }]}
      charts={<ChartCard title="Valor pendente por categoria"><BarChart data={porCategoria}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="categoria" tick={{ fontSize: 11, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="valor" fill={T.coral} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>}
      extra={proximos.length > 0 && <Card className="mb-5" style={{ borderColor: `${T.amber}55` }}><div className="flex items-center gap-2 mb-2"><AlertTriangle size={15} style={{ color: T.amber }} /><span className="font-semibold text-sm" style={{ color: T.text }}>Vencimentos nos próximos 7 dias</span></div><div className="flex flex-col gap-1.5">{proximos.map((r) => (<div key={r.id} className="flex justify-between text-sm"><span style={{ color: T.muted }}>{r.descricao} — {fmtDate(r.vencimento)}</span><span style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.valor)}</span></div>))}</div></Card>} />
    </>
  );
}

/* ============================== RECEITA DE SUBLOCAÇÃO (calculada automaticamente) ============================== */
function SublocacaoModulo() {
  const { data: producao, loading: loadingProd, erro: erroProd } = useRecords("producao");
  const { data: profissionais, loading: loadingProf, erro: erroProf } = useRecords("cadProfissionais");
  const loading = loadingProd || loadingProf;
  const erro = erroProd || erroProf;

  const calcular = (p, config) => {
    if (config.tipoSublocacao === "Percentual") return p.receita * ((config.percentualSublocacao || 0) / 100);
    if (config.tipoSublocacao === "Valor fixo com abatimento") return (config.valorFixoSublocacao || 0) - (config.valorAbatimento || 0);
    return config.valorFixoSublocacao || 0;
  };

  const linhas = producao
    .map((p) => { const config = profissionais.find((prof) => prof.nome === p.profissional); return config && config.direcaoSublocacao === "Profissional paga à clínica" ? { ...p, config, valorSublocacao: calcular(p, config) } : null; })
    .filter(Boolean);

  const totalSublocacao = linhas.reduce((s, l) => s + l.valorSublocacao, 0);
  const porProfissional = useMemo(() => { const map = {}; linhas.forEach((l) => { map[l.profissional] = (map[l.profissional] || 0) + l.valorSublocacao; }); return Object.entries(map).map(([profissional, valor]) => ({ profissional, valor })).sort((a, b) => b.valor - a.valor); }, [linhas]);

  return (
    <div>
      <SectionHeader icon={Building2} title="Receita de Sublocação" subtitle="Valores que os profissionais pagam à clínica pela sublocação da sala — calculado a partir da Produção Médica" tone="coral" />
      {erro && <Card className="mb-5" style={{ borderColor: `${T.red}55` }}><span className="text-sm" style={{ color: T.red }}>Erro ao carregar: {erro}</span></Card>}
      <div className="grid gap-3 mb-6 md:grid-cols-3">
        <KpiCard label="Receita de sublocação (total)" value={fmtBRL(totalSublocacao)} tone="green" />
        <KpiCard label="Profissionais nessa modalidade" value={porProfissional.length} tone="coral" />
        <KpiCard label="Lançamentos considerados" value={linhas.length} />
      </div>
      {!loading && porProfissional.length > 0 && (
        <ChartCard title="Receita de sublocação por profissional">
          <BarChart data={porProfissional}>
            <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
            <XAxis dataKey="profissional" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} />
            <YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} />
            <Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} />
            <Bar dataKey="valor" fill={T.coral} radius={[4, 4, 0, 0]} />
          </BarChart>
        </ChartCard>
      )}
      <Card>
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Detalhamento por lançamento de produção</p>
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> :
          linhas.length === 0 ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}>Nenhum profissional com sublocação "profissional paga à clínica" cadastrada, ou nenhum lançamento de produção correspondente.</div> : (
          <div className="overflow-x-auto -mx-5 px-5">
            <table className="w-full text-sm min-w-[560px]">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Profissional</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Mês</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Forma</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor</th>
              </tr></thead>
              <tbody>{linhas.map((l) => (
                <tr key={l.id} style={{ borderBottom: `1px solid ${T.border}` }}>
                  <td className="py-2 px-2 font-medium" style={{ color: T.text }}>{l.profissional}</td>
                  <td className="py-2 px-2">{l.mes}</td>
                  <td className="py-2 px-2">{l.config.tipoSublocacao}</td>
                  <td className="py-2 px-2" style={{ color: T.green, fontWeight: 600, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(l.valorSublocacao)}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
}

function RelatorioCaixaModulo() {
  const { data, add, update, remove, loading, erro } = useRecords("caixaLancamentos");
  const { data: categoriasCadastro } = useRecords("cadCategorias");
  const { data: saldosIniciais } = useRecords("caixaSaldoInicial");
  const opcoesCategoria = categoriasCadastro.filter((c) => c.aplicacao === "Caixa" || c.aplicacao === "Geral").map((c) => c.nome);
  const [caixaAtivo, setCaixaAtivo] = useState("Vacinas");
  const [mesAtivo, setMesAtivo] = useState(todayISO().slice(0, 7));
  const fields = [
    { key: "tipoCaixa", label: "Caixa", type: "select", options: ["Vacinas", "Recepção"], default: caixaAtivo },
    { key: "data", label: "Data", type: "date", default: todayISO() },
    { key: "tipo", label: "Tipo", type: "select", options: ["entrada", "saida"] },
    { key: "categoria", label: "Categoria", type: "select", options: opcoesCategoria.length ? opcoesCategoria : ["Cadastre em Cadastros → Categorias"], required: false },
    { key: "descricao", label: "Descrição", type: "text", required: false },
    { key: "valor", label: "Valor (R$)", type: "currency" },
  ];
  const dadosCaixa = data.filter((r) => r.tipoCaixa === caixaAtivo);
  const dados = dadosCaixa.filter((r) => monthKey(r.data) === mesAtivo);
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) },
    { key: "tipo", label: "Tipo", render: (r) => <Badge tone={r.tipo === "entrada" ? "green" : "red"}>{r.tipo === "entrada" ? "Entrada" : "Saída"}</Badge> },
    { key: "categoria", label: "Categoria" }, { key: "descricao", label: "Descrição" },
    { key: "valor", label: "Valor", render: (r) => <span style={{ color: r.tipo === "entrada" ? T.green : T.red, fontWeight: 600 }}>{fmtBRL(r.valor)}</span> },
  ];
  const saldoInicialCadastrado = saldosIniciais.find((s) => s.tipoCaixa === caixaAtivo && s.mes === mesAtivo);
  const valorInicial = saldoInicialCadastrado ? Number(saldoInicialCadastrado.valorInicial) : 0;
  const totalEntradas = dados.filter((r) => r.tipo === "entrada").reduce((s, r) => s + Number(r.valor), 0);
  const totalSaidas = dados.filter((r) => r.tipo === "saida").reduce((s, r) => s + Number(r.valor), 0);
  const saldo = valorInicial + totalEntradas - totalSaidas;
  const porDia = useMemo(() => { const map = {}; dados.forEach((r) => { if (!map[r.data]) map[r.data] = { data: r.data, entradas: 0, saidas: 0 }; map[r.data][r.tipo === "entrada" ? "entradas" : "saidas"] += Number(r.valor); }); return Object.values(map).sort((a, b) => a.data.localeCompare(b.data)); }, [dados]);
  return (
    <div>
      <SectionHeader icon={Wallet} title="Relatório de Caixa" subtitle="Entradas e saídas do caixa físico — Vacinas ou Recepção" tone="coral" />
      <div className="flex gap-2 mb-5">
        <button onClick={() => setCaixaAtivo("Vacinas")} className="flex-1 py-2.5 rounded-xl text-sm font-semibold" style={{ background: caixaAtivo === "Vacinas" ? T.teal : "#F1EEE4", color: caixaAtivo === "Vacinas" ? "#fff" : T.muted }}>Caixa — Vacinas</button>
        <button onClick={() => setCaixaAtivo("Recepção")} className="flex-1 py-2.5 rounded-xl text-sm font-semibold" style={{ background: caixaAtivo === "Recepção" ? T.coral : "#F1EEE4", color: caixaAtivo === "Recepção" ? "#fff" : T.muted }}>Caixa — Recepção</button>
      </div>
      <Card className="mb-5">
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Mês (competência)"><input type="month" className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={mesAtivo} onChange={(e) => setMesAtivo(e.target.value)} /></Field>
          <div className="text-sm" style={{ color: T.muted }}>
            {saldoInicialCadastrado ? <>Saldo inicial cadastrado: <b style={{ color: T.text }}>{fmtBRL(valorInicial)}</b></> : <span style={{ color: T.amber }}>Nenhum saldo inicial cadastrado para este mês/caixa — cadastre em Cadastros → Saldo Inicial do Caixa.</span>}
          </div>
        </div>
      </Card>
      <ModuleShell icon={Wallet} title={`Caixa — ${caixaAtivo}`} subtitle={`Lançamentos deste caixa em ${mesAtivo}`} tone={caixaAtivo === "Vacinas" ? "teal" : "coral"} loading={loading} erro={erro}
        dailyFields={fields} dailyCta="Registrar lançamento" fields={fields} columns={columns} rows={dados} onAdd={(r) => add({ ...r, tipoCaixa: caixaAtivo })} onUpdate={update} onDelete={remove}
        kpis={[{ label: "Saldo inicial", value: fmtBRL(valorInicial) }, { label: "Entradas", value: fmtBRL(totalEntradas), tone: "green" }, { label: "Saídas", value: fmtBRL(totalSaidas), tone: "red" }, { label: "Saldo do caixa", value: fmtBRL(saldo), tone: saldo >= 0 ? "green" : "red" }]}
        charts={<ChartCard title="Entradas x saídas por dia"><BarChart data={porDia}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="data" tickFormatter={fmtDate} tick={{ fontSize: 10, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip formatter={(v) => fmtBRL(v)} labelFormatter={fmtDate} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Legend wrapperStyle={{ fontSize: 12 }} /><Bar dataKey="entradas" name="Entradas" fill={T.green} radius={[4, 4, 0, 0]} /><Bar dataKey="saidas" name="Saídas" fill={T.red} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
    </div>
  );
}

function RepasseMedicoModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("repasse");
  const fields = [
    { key: "medico", label: "Médico(a)", type: "text" },
    { key: "mes", label: "Mês (AAAA-MM)", type: "text", default: todayISO().slice(0, 7) },
    { key: "valorConvenio", label: "Repasse de convênios (R$)", type: "currency" },
    { key: "valorPlantao", label: "Repasse de plantão (R$)", type: "currency" },
    { key: "qtdVacinas", label: "Qtd. vacinas por prescrição", type: "number" },
    { key: "valorPorVacina", label: "Valor por vacina prescrita (R$)", type: "currency" },
  ];
  const withTotal = data.map((r) => { const valorVacinas = r.qtdVacinas * r.valorPorVacina; return { ...r, valorVacinas, total: r.valorConvenio + r.valorPlantao + valorVacinas }; });
  const columns = [
    { key: "medico", label: "Médico(a)" }, { key: "mes", label: "Mês" },
    { key: "valorConvenio", label: "Convênios", render: (r) => fmtBRL(r.valorConvenio) },
    { key: "valorPlantao", label: "Plantão", render: (r) => fmtBRL(r.valorPlantao) },
    { key: "valorVacinas", label: "Vacinas", render: (r) => <span title={`${r.qtdVacinas} × ${fmtBRL(r.valorPorVacina)}`}>{fmtBRL(r.valorVacinas)}</span> },
    { key: "total", label: "Total a repassar", render: (r) => <span style={{ color: T.green, fontWeight: 700, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.total)}</span> },
  ];
  const totalGeral = withTotal.reduce((s, r) => s + r.total, 0);
  const porMedico = useMemo(() => { const map = {}; withTotal.forEach((r) => { map[r.medico] = (map[r.medico] || 0) + r.total; }); return Object.entries(map).map(([medico, total]) => ({ medico, total })).sort((a, b) => b.total - a.total); }, [withTotal]);
  const maiorRepasse = porMedico[0];
  return (
    <ModuleShell icon={Stethoscope} title="Repasse Médico" subtitle="Convênios + plantão + vacinas por prescrição — total calculado automaticamente" tone="coral" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar repasse" fields={fields} columns={columns} rows={withTotal} onAdd={add} onUpdate={update} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Total a repassar (todos)", value: fmtBRL(totalGeral), tone: "green" }, { label: "Maior repasse", value: maiorRepasse ? maiorRepasse.medico : "—", tone: "coral" }, { label: "Médicos no período", value: porMedico.length }]}
      charts={<ChartCard title="Total a repassar por médico(a)">
        <BarChart data={porMedico}>
          <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
          <XAxis dataKey="medico" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} />
          <YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} />
          <Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} />
          <Bar dataKey="total" fill={T.coral} radius={[4, 4, 0, 0]} />
        </BarChart>
      </ChartCard>} />
  );
}

function FaturamentoModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("faturamento");
  const { data: tiposPagamentoCadastro } = useRecords("cadTiposPagamento");
  const { data: bancosCadastro } = useRecords("cadBancos");
  const opcoesTipoPagamento = tiposPagamentoCadastro.length ? tiposPagamentoCadastro.map((t) => t.nome) : TIPOS_PAGAMENTO_PADRAO;
  const nomesBancos = bancosCadastro.map((b) => b.nome);
  const fields = [
    { key: "tipoRecebimento", label: "Tipo de recebimento", type: "select", options: ["Convênio", "Outro serviço"], default: "Convênio" },
    { key: "convenio", label: "Convênio", type: "select", options: CONVENIOS, showIf: (f) => f.tipoRecebimento !== "Outro serviço" },
    { key: "servicoOutro", label: "Qual serviço", type: "text", placeholder: "ex: Aluguel de sala, Curso, Consultoria…", showIf: (f) => f.tipoRecebimento === "Outro serviço" },
    { key: "numeroGuia", label: "Nº da guia (se houver)", type: "text", required: false },
    { key: "tipo", label: "Tipo", type: "select", options: ["Consulta", "Plantão", "Exame", "SADT", "Outro"] },
    { key: "dataProtocolo", label: "Data de protocolo/emissão", type: "date", default: todayISO() },
    { key: "valor", label: "Valor (R$)", type: "currency" },
    { key: "status", label: "Status", type: "select", options: ["Protocolada", "Faturada", "Paga", "Vencida"] },
    { key: "dataPagamento", label: "Data de pagamento", type: "date", required: false },
    { key: "tipoPagamento", label: "Tipo de pagamento", type: "select", options: opcoesTipoPagamento, required: false },
    { key: "bancoNome", label: "Banco de recebimento", type: "select", options: nomesBancos.length ? nomesBancos : ["Cadastre em Cadastros → Bancos"], required: false },
  ];
  const mesclarConvenio = (record) => ({ ...record, convenio: record.tipoRecebimento === "Outro serviço" ? (record.servicoOutro || "Outro serviço") : record.convenio });
  const onAddComputado = (record) => { const r = mesclarConvenio(record); const banco = bancosCadastro.find((b) => b.nome === r.bancoNome); return add({ ...r, bancoId: banco ? banco.id : null }); };
  const onUpdateComputado = (id, record) => { const r = mesclarConvenio(record); const banco = bancosCadastro.find((b) => b.nome === r.bancoNome); return update(id, { ...r, bancoId: banco ? banco.id : null }); };
  const columns = [
    { key: "convenio", label: "Convênio / Serviço" }, { key: "numeroGuia", label: "Nº guia" }, { key: "tipo", label: "Tipo" },
    { key: "dataProtocolo", label: "Protocolo", render: (r) => fmtDate(r.dataProtocolo) },
    { key: "valor", label: "Valor", render: (r) => fmtBRL(r.valor) },
    { key: "bancoNome", label: "Banco", render: (r) => (bancosCadastro.find((b) => b.id === r.bancoId) || {}).nome || "—" },
    { key: "status", label: "Status", render: (r) => (
      <select className="rounded-lg px-2 py-1 text-xs outline-none" style={inputStyle} value={r.status} onChange={(e) => {
        const novoStatus = e.target.value;
        if (novoStatus === "Paga") {
          const data = window.prompt("Data em que foi paga (AAAA-MM-DD):", r.dataProtocolo || todayISO());
          if (!data) return;
          update(r.id, { status: novoStatus, dataPagamento: data });
        } else update(r.id, { status: novoStatus, dataPagamento: r.dataPagamento });
      }}>
        <option value="Protocolada">Protocolada</option><option value="Faturada">Faturada</option><option value="Paga">Paga</option><option value="Vencida">Vencida</option>
      </select>
    ) },
  ];
  const [filtroMes, setFiltroMes] = useState("");
  const [filtroDe, setFiltroDe] = useState("");
  const [filtroAte, setFiltroAte] = useState("");
  const dataFiltrada = data.filter((r) => {
    if (filtroMes && monthKey(r.dataProtocolo) !== filtroMes) return false;
    if (filtroDe && r.dataProtocolo < filtroDe) return false;
    if (filtroAte && r.dataProtocolo > filtroAte) return false;
    return true;
  });
  const pendentes = dataFiltrada.filter((r) => r.status !== "Paga");

  const porStatus = useMemo(() => { const map = {}; dataFiltrada.forEach((r) => { if (!map[r.status]) map[r.status] = { status: r.status, valor: 0, qtd: 0 }; map[r.status].valor += r.valor; map[r.status].qtd += 1; }); const ordem = ["Protocolada", "Faturada", "Paga", "Vencida"]; return ordem.filter((s) => map[s]).map((s) => map[s]); }, [dataFiltrada]);
  const totalProtocolado = dataFiltrada.reduce((s, r) => s + r.valor, 0);
  const totalPago = dataFiltrada.filter((r) => r.status === "Paga").reduce((s, r) => s + r.valor, 0);
  const totalVencido = dataFiltrada.filter((r) => r.status === "Vencida").reduce((s, r) => s + r.valor, 0);
  const totalFaturado = dataFiltrada.filter((r) => r.status === "Faturada").reduce((s, r) => s + r.valor, 0);
  const porConvenio = useMemo(() => { const map = {}; dataFiltrada.forEach((r) => { map[r.convenio] = (map[r.convenio] || 0) + r.valor; }); return Object.entries(map).map(([convenio, valor]) => ({ convenio, valor })).sort((a, b) => b.valor - a.valor); }, [dataFiltrada]);

  return (
    <>
      <Card className="mb-5">
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Filtrar por competência ou período</p>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Competência (mês)"><input type="month" className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={filtroMes} onChange={(e) => { setFiltroMes(e.target.value); setFiltroDe(""); setFiltroAte(""); }} /></Field>
          <Field label="De"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={filtroDe} onChange={(e) => { setFiltroDe(e.target.value); setFiltroMes(""); }} /></Field>
          <Field label="Até"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={filtroAte} onChange={(e) => { setFiltroAte(e.target.value); setFiltroMes(""); }} /></Field>
          {(filtroMes || filtroDe || filtroAte) && <Btn small variant="ghost" onClick={() => { setFiltroMes(""); setFiltroDe(""); setFiltroAte(""); }}>Limpar filtro</Btn>}
        </div>
      </Card>
    <ModuleShell icon={ClipboardList} title="Contas a Receber" subtitle="Mostrando só o que ainda falta receber — as pagas ficam completas em Protocolo Bradesco" tone="coral" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar guia" fields={fields} columns={columns} rows={pendentes} onAdd={onAddComputado} onUpdate={onUpdateComputado} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Total protocolado", value: fmtBRL(totalProtocolado) }, { label: "Faturado", value: fmtBRL(totalFaturado), tone: "amber" }, { label: "Pago", value: fmtBRL(totalPago), tone: "green" }, { label: "Vencido", value: fmtBRL(totalVencido), tone: totalVencido ? "red" : "green" }]}
      charts={<div className="grid md:grid-cols-2 gap-5">
        <ChartCard title="Valor por status da guia"><BarChart data={porStatus}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="status" tick={{ fontSize: 11, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="valor" radius={[4, 4, 0, 0]}>{porStatus.map((s, i) => <Cell key={i} fill={{ Protocolada: T.muted, Faturada: T.amber, Paga: T.green, Vencida: T.red }[s.status]} />)}</Bar></BarChart></ChartCard>
        <ChartCard title="Valor por convênio"><PieChart><Pie data={porConvenio} dataKey="valor" nameKey="convenio" innerRadius={55} outerRadius={85} paddingAngle={2}>{porConvenio.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip formatter={(v) => fmtBRL(v)} /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart></ChartCard>
      </div>} />
    </>
  );
}

/* ============================== RELATÓRIO DE COLABORADOR ============================== */
function RelatorioColaboradorModulo() {
  const { data: perfis, loading: loadingPerfis } = usePerfisDaUnidade();
  const { data: producao, loading: loadingProd } = useProducaoDiariaEquipe();
  const { session } = useAuth();
  const { unidadeId } = useUnidade();
  const [horas, setHoras] = useState([]);
  const [metas, setMetas] = useState([]);
  const [agendamentos, setAgendamentos] = useState([]);
  const [loadingExtra, setLoadingExtra] = useState(true);
  const [colaboradorId, setColaboradorId] = useState("todos");
  const [de, setDe] = useState(""); const [ate, setAte] = useState("");

  useEffect(() => {
    setLoadingExtra(true);
    Promise.all([
      sbRest(`rh_horas?unidade_id=eq.${unidadeId}&select=*`, { token: session.access_token }),
      sbRest(`metas_colaborador?unidade_id=eq.${unidadeId}&select=*`, { token: session.access_token }),
      sbRest(`agendamentos_pacientes?unidade_id=eq.${unidadeId}&select=*`, { token: session.access_token }),
    ]).then(([h, m, ag]) => { setHoras(h || []); setMetas(m || []); setAgendamentos(ag || []); }).finally(() => setLoadingExtra(false));
  }, [unidadeId]);

  const noPeriodo = (data) => (!de || data >= de) && (!ate || data <= ate);
  const loading = loadingPerfis || loadingProd || loadingExtra;

  const alvo = colaboradorId === "todos" ? perfis : perfis.filter((p) => p.id === colaboradorId);
  const linhas = alvo.map((p) => {
    const prodP = producao.filter((r) => r.colaborador_id === p.id && noPeriodo(r.data));
    const horasP = horas.filter((r) => r.colaborador_id === p.id && noPeriodo(r.data));
    const metasP = metas.filter((m) => m.colaborador_id === p.id);
    const agP = agendamentos.filter((a) => a.colaborador_id === p.id && noPeriodo(a.data_agendamento));
    const ligacoes = prodP.reduce((s, r) => s + (Number(r.ligacoes) || 0), 0);
    const mensagens = prodP.reduce((s, r) => s + (Number(r.mensagens) || 0), 0);
    const agendados = prodP.reduce((s, r) => s + (Number(r.agendados) || 0), 0);
    const horasTotal = horasP.reduce((s, r) => s + (Number(r.horas_total) || 0), 0);
    const metasResumo = metasP.map((m) => `${m.tipo_meta}: meta ${m.quantidade_total}`).join(" | ") || "Sem meta cadastrada";
    const agendamentosRegistrados = agP.length;
    const compareceram = agP.filter((a) => a.compareceu === "Sim").length;
    const naoCompareceram = agP.filter((a) => a.compareceu === "Não").length;
    return { nome: p.nome, cargo: p.cargo || "—", ligacoes, mensagens, agendados, horasTrabalhadas: horasTotal.toFixed(1), metas: metasResumo, agendamentosRegistrados, compareceram, naoCompareceram };
  });

  const camposExport = [
    { key: "nome", label: "Nome" }, { key: "cargo", label: "Cargo" }, { key: "ligacoes", label: "Ligações" }, { key: "mensagens", label: "Mensagens Respondidas" },
    { key: "agendados", label: "Agendamentos" }, { key: "agendamentosRegistrados", label: "Agendamentos Detalhados" }, { key: "compareceram", label: "Compareceram" }, { key: "naoCompareceram", label: "Não Compareceram" },
    { key: "horasTrabalhadas", label: "Horas Trabalhadas" }, { key: "metas", label: "Acompanhamento de Meta" },
  ];
  const nomeArquivo = `relatorio-colaborador-${colaboradorId === "todos" ? "todos" : (perfis.find((p) => p.id === colaboradorId) || {}).nome || "colaborador"}`;

  return (
    <div>
      <SectionHeader icon={Users} title="Relatório de Colaborador" subtitle="Ligação, mensagem respondida, jornada de trabalho e acompanhamento de meta" tone="purple" />
      <Card className="mb-5">
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Colaborador(a)">
            <select className="rounded-lg px-3 py-2 text-sm outline-none w-56" style={inputStyle} value={colaboradorId} onChange={(e) => setColaboradorId(e.target.value)}>
              <option value="todos">Todos</option>
              {perfis.map((p) => <option key={p.id} value={p.id}>{p.nome}</option>)}
            </select>
          </Field>
          <Field label="De"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={de} onChange={(e) => setDe(e.target.value)} /></Field>
          <Field label="Até"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={ate} onChange={(e) => setAte(e.target.value)} /></Field>
          <Btn tone="teal" onClick={() => exportToExcel(camposExport, linhas, nomeArquivo)}>Excel</Btn>
          <Btn variant="ghost" onClick={() => exportToPDF(camposExport, linhas, nomeArquivo)}>PDF</Btn>
          <Btn variant="ghost" onClick={() => exportToCSV(camposExport, linhas, nomeArquivo)}>CSV</Btn>
        </div>
      </Card>
      <Card>
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> : (
          <div className="overflow-x-auto -mx-5 px-5">
            <table className="w-full text-sm min-w-[760px]">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}>{camposExport.map((c) => <th key={c.key} className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>{c.label}</th>)}</tr></thead>
              <tbody>{linhas.map((l, i) => (
                <tr key={i} style={{ borderBottom: `1px solid ${T.border}` }}>
                  <td className="py-2 px-2 font-medium" style={{ color: T.text }}>{l.nome}</td><td className="py-2 px-2">{l.cargo}</td><td className="py-2 px-2">{l.ligacoes}</td><td className="py-2 px-2">{l.mensagens}</td><td className="py-2 px-2">{l.agendados}</td><td className="py-2 px-2">{l.agendamentosRegistrados}</td><td className="py-2 px-2" style={{ color: T.green }}>{l.compareceram}</td><td className="py-2 px-2" style={{ color: T.red }}>{l.naoCompareceram}</td><td className="py-2 px-2">{l.horasTrabalhadas}</td><td className="py-2 px-2 text-xs" style={{ color: T.muted }}>{l.metas}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
}

function PessoalModulo() {
  const { perfil } = useAuth();
  const canManageRH = perfil && ["admin", "colaborador"].includes(perfil.papel);
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("pessoal");
  const fields = [{ key: "nome", label: "Colaborador(a)", type: "text" }, { key: "cargo", label: "Cargo", type: "text" }, { key: "equipe", label: "Equipe", type: "select", options: ["Recepção", "Financeiro", "Marketing", "Enfermagem", "Administrativo", "Outra"] }, { key: "mes", label: "Mês (AAAA-MM)", type: "text", default: todayISO().slice(0, 7) }, { key: "metaMensal", label: "Meta mensal (agendados)", type: "number" }, { key: "ligacoes", label: "Ligações atendidas", type: "number" }, { key: "mensagens", label: "Mensagens respondidas", type: "number" }, { key: "agendados", label: "Pacientes agendados", type: "number" }];
  const withPct = data.map((r) => ({ ...r, pct: r.metaMensal ? (r.agendados / r.metaMensal) * 100 : (r.ligacoes + r.mensagens > 0 ? 100 : 0) }));
  const columns = [{ key: "nome", label: "Colaborador(a)" }, { key: "equipe", label: "Equipe" }, { key: "ligacoes", label: "Ligações" }, { key: "mensagens", label: "Mensagens" }, { key: "agendados", label: "Agendados" }, { key: "pct", label: "Meta atingida", render: (r) => (<div className="flex items-center gap-2 min-w-[110px]"><Progress pct={r.pct} /><span className="text-xs font-semibold" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>{fmtPct(r.pct)}</span></div>) }];
  const porEquipe = useMemo(() => { const map = {}; withPct.forEach((r) => { if (!map[r.equipe]) map[r.equipe] = { equipe: r.equipe, soma: 0, n: 0 }; map[r.equipe].soma += r.pct; map[r.equipe].n += 1; }); return Object.values(map).map((e) => ({ equipe: e.equipe, media: e.soma / e.n })).sort((a, b) => b.media - a.media); }, [withPct]);
  const destaque = [...withPct].sort((a, b) => b.pct - a.pct)[0]; const mediaGeral = withPct.length ? withPct.reduce((s, r) => s + r.pct, 0) / withPct.length : 0;
  return (
    <ModuleShell icon={Users} title="Departamento Pessoal" subtitle="Produtividade individual, metas e desempenho por equipe" tone="purple" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar desempenho" fields={fields} columns={columns} rows={withPct} onAdd={add} onUpdate={update} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Colaboradores", value: data.length }, { label: "Meta média", value: fmtPct(mediaGeral), tone: mediaGeral >= 90 ? "green" : mediaGeral >= 70 ? "amber" : "red" }, { label: "Destaque do mês", value: destaque ? destaque.nome : "—", tone: "purple" }, { label: "Equipe líder", value: porEquipe[0] ? porEquipe[0].equipe : "—" }]}
      charts={<div className="grid md:grid-cols-2 gap-5">
        <ChartCard title="Meta atingida por colaborador(a)"><BarChart data={withPct} layout="vertical" margin={{ left: 10 }}><CartesianGrid strokeDasharray="3 3" stroke={T.border} horizontal={false} /><XAxis type="number" tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v}%`} /><YAxis type="category" dataKey="nome" width={130} tick={{ fontSize: 11, fill: T.muted }} /><Tooltip formatter={(v) => `${v.toFixed(0)}%`} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="pct" radius={[0, 4, 4, 0]}>{withPct.map((r, i) => <Cell key={i} fill={r.pct >= 100 ? T.green : r.pct >= 70 ? T.amber : T.red} />)}</Bar></BarChart></ChartCard>
        <ChartCard title="Desempenho médio por equipe"><BarChart data={porEquipe}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="equipe" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-10} textAnchor="end" height={50} /><YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v}%`} /><Tooltip formatter={(v) => `${v.toFixed(0)}%`} contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="media" fill={T.purple} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>
      </div>} />
  );
}

/* ============================== CALENDÁRIO DE MARKETING ============================== */
function ehHojeOuAniversarioHoje(item) {
  const hoje = todayISO();
  if (item.recorrenteAnual) return item.data.slice(5) === hoje.slice(5);
  return item.data === hoje;
}
function proximaOcorrencia(item) {
  if (!item.recorrenteAnual) return item.data;
  const hoje = todayISO();
  const anoAtual = hoje.slice(0, 4);
  let proxima = `${anoAtual}-${item.data.slice(5)}`;
  if (proxima < hoje) proxima = `${Number(anoAtual) + 1}-${item.data.slice(5)}`;
  return proxima;
}
function CalendarioMarketingModulo() {
  const { data, add, update, remove, loading, erro } = useRecords("marketingCalendario");
  const fields = [
    { key: "tipo", label: "Tipo", type: "select", options: ["Ação", "Evento", "Aniversário"] },
    { key: "titulo", label: "Título", type: "text", placeholder: "ex: Campanha Dia das Crianças, Aniversário Dra. Ana" },
    { key: "data", label: "Data", type: "date" },
    { key: "recorrenteAnual", label: "Repete todo ano (use para aniversários)", type: "checkbox", required: false, default: false },
    { key: "descricao", label: "Descrição / observações", type: "textarea", required: false },
  ];
  const columns = [
    { key: "tipo", label: "Tipo", render: (r) => <Badge tone={r.tipo === "Aniversário" ? "coral" : r.tipo === "Evento" ? "teal" : "amber"}>{r.tipo}</Badge> },
    { key: "titulo", label: "Título" }, { key: "data", label: "Data", render: (r) => `${fmtDate(r.data)}${r.recorrenteAnual ? " (todo ano)" : ""}` },
    { key: "descricao", label: "Descrição" },
  ];
  const hojeItens = data.filter(ehHojeOuAniversarioHoje);
  const proximos = [...data].map((r) => ({ ...r, proxima: proximaOcorrencia(r) })).sort((a, b) => a.proxima.localeCompare(b.proxima)).filter((r) => r.proxima >= todayISO()).slice(0, 8);
  return (
    <ModuleShell icon={CalendarDays} title="Calendário de Marketing" subtitle="Ações, eventos e aniversários — o sistema avisa no dia" tone="rose" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Adicionar ao calendário" fields={fields} columns={columns} rows={data} onAdd={add} onUpdate={update} onDelete={remove}
      kpis={[{ label: "Itens no calendário", value: data.length }, { label: "Hoje", value: hojeItens.length, tone: hojeItens.length ? "coral" : "green" }, { label: "Próximos 8", value: proximos.length }]}
      extra={<>
        {hojeItens.length > 0 && (
          <Card className="mb-5" style={{ borderColor: `${T.coral}55`, background: `${T.coral}10` }}>
            <div className="flex items-center gap-2 mb-2"><Bell size={15} style={{ color: T.coral }} /><span className="font-semibold text-sm" style={{ color: T.text }}>É hoje! 🎉</span></div>
            <div className="flex flex-col gap-1.5">{hojeItens.map((r) => (<div key={r.id} className="text-sm" style={{ color: T.text }}><b>{r.titulo}</b> <span style={{ color: T.muted }}>— {r.tipo}{r.descricao ? `: ${r.descricao}` : ""}</span></div>))}</div>
          </Card>
        )}
        {proximos.length > 0 && (
          <Card className="mb-5">
            <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Próximos no calendário</p>
            <div className="flex flex-col gap-1.5">{proximos.map((r) => (<div key={r.id} className="flex justify-between text-sm py-1" style={{ borderBottom: `1px solid ${T.border}` }}><span style={{ color: T.text }}>{r.titulo} <Badge tone={r.tipo === "Aniversário" ? "coral" : r.tipo === "Evento" ? "teal" : "amber"}>{r.tipo}</Badge></span><span style={{ color: T.muted }}>{fmtDate(r.proxima)}</span></div>))}</div>
          </Card>
        )}
      </>} />
  );
}

function MarketingModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("marketing");
  const { data: profissionais } = useRecords("cadProfissionais");
  const nomesProfissionais = profissionais.map((p) => p.nome);
  const fields = [
    { key: "data", label: "Data do lead", type: "date", default: todayISO() },
    { key: "cliente", label: "Cliente (criança/paciente)", type: "text" },
    { key: "responsavel", label: "Pai/Mãe", type: "text", required: false },
    { key: "telefone", label: "Telefone", type: "text", required: false },
    { key: "dataNascimentoCrianca", label: "Data de nascimento da criança", type: "date", required: false },
    { key: "especialidadeMedica", label: "Especialidade médica", type: "text", required: false },
    { key: "profissionalAtendeu", label: "Profissional que atendeu", type: "select", options: nomesProfissionais.length ? nomesProfissionais : ["Cadastre em Cadastros → Profissionais"], required: false },
    { key: "dataAgendamento", label: "Data do agendamento", type: "date", required: false },
    { key: "canal", label: "Como nos conheceu", type: "select", options: ["WhatsApp", "Google", "TikTok", "Instagram", "Facebook", "Indicação", "Outro"] },
    { key: "indicadoPor", label: "Indicado por (nome)", type: "text", required: false, showIf: (f) => f.canal === "Indicação" },
    { key: "telefoneIndicacao", label: "Telefone de quem indicou", type: "text", required: false, showIf: (f) => f.canal === "Indicação" },
    { key: "status", label: "Status", type: "select", options: ["Novo", "Contatado", "Agendado", "Convertido", "Perdido"] },
  ];
  const columns = [
    { key: "data", label: "Data", render: (r) => fmtDate(r.data) }, { key: "cliente", label: "Cliente" }, { key: "responsavel", label: "Pai/Mãe" }, { key: "telefone", label: "Telefone" },
    { key: "canal", label: "Canal", render: (r) => r.canal === "Indicação" && r.indicadoPor ? <span>{r.canal} <span className="text-xs" style={{ color: T.muted }}>({r.indicadoPor})</span></span> : r.canal },
    { key: "profissionalAtendeu", label: "Profissional" }, { key: "dataAgendamento", label: "Agendamento", render: (r) => r.dataAgendamento ? fmtDate(r.dataAgendamento) : "—" },
    { key: "status", label: "Status", render: (r) => { const tone = { Novo: "ink", Contatado: "amber", Agendado: "amber", Convertido: "green", Perdido: "red" }[r.status]; return <Badge tone={tone}>{r.status}</Badge>; } },
  ];

  const [filtroMes, setFiltroMes] = useState("");
  const [filtroDe, setFiltroDe] = useState("");
  const [filtroAte, setFiltroAte] = useState("");
  const [filtroCanal, setFiltroCanal] = useState("");
  const [filtroProfissional, setFiltroProfissional] = useState("");
  const dataFiltrada = filtrarPorPeriodo(data, "data", filtroMes, filtroDe, filtroAte)
    .filter((r) => !filtroCanal || r.canal === filtroCanal)
    .filter((r) => !filtroProfissional || r.profissionalAtendeu === filtroProfissional);

  const porCanal = useMemo(() => { const map = {}; dataFiltrada.forEach((r) => { map[r.canal] = (map[r.canal] || 0) + 1; }); return Object.entries(map).map(([canal, total]) => ({ canal, total })).sort((a, b) => b.total - a.total); }, [dataFiltrada]);
  const porStatus = useMemo(() => { const ordem = ["Novo", "Contatado", "Agendado", "Convertido", "Perdido"]; const map = {}; dataFiltrada.forEach((r) => { map[r.status] = (map[r.status] || 0) + 1; }); return ordem.filter((s) => map[s]).map((status) => ({ status, total: map[status] })); }, [dataFiltrada]);
  const convertidos = dataFiltrada.filter((r) => r.status === "Convertido").length; const taxaConversao = dataFiltrada.length ? (convertidos / dataFiltrada.length) * 100 : 0; const agendadosPendentes = dataFiltrada.filter((r) => r.status === "Agendado").length;

  return (
    <>
      <Card className="mb-5">
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Filtrar por competência, período, canal ou profissional</p>
        <div className="flex flex-wrap gap-3 items-end">
          <Field label="Competência (mês)"><input type="month" className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={filtroMes} onChange={(e) => { setFiltroMes(e.target.value); setFiltroDe(""); setFiltroAte(""); }} /></Field>
          <Field label="De"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={filtroDe} onChange={(e) => { setFiltroDe(e.target.value); setFiltroMes(""); }} /></Field>
          <Field label="Até"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={filtroAte} onChange={(e) => { setFiltroAte(e.target.value); setFiltroMes(""); }} /></Field>
          <Field label="Canal"><select className="rounded-lg px-3 py-2 text-sm outline-none w-36" style={inputStyle} value={filtroCanal} onChange={(e) => setFiltroCanal(e.target.value)}><option value="">Todos</option>{["WhatsApp", "Google", "TikTok", "Instagram", "Facebook", "Indicação", "Outro"].map((c) => <option key={c} value={c}>{c}</option>)}</select></Field>
          <Field label="Profissional"><select className="rounded-lg px-3 py-2 text-sm outline-none w-44" style={inputStyle} value={filtroProfissional} onChange={(e) => setFiltroProfissional(e.target.value)}><option value="">Todos</option>{nomesProfissionais.map((p) => <option key={p} value={p}>{p}</option>)}</select></Field>
          {(filtroMes || filtroDe || filtroAte || filtroCanal || filtroProfissional) && <Btn small variant="ghost" onClick={() => { setFiltroMes(""); setFiltroDe(""); setFiltroAte(""); setFiltroCanal(""); setFiltroProfissional(""); }}>Limpar filtro</Btn>}
        </div>
      </Card>
    <ModuleShell icon={Megaphone} title="Marketing — Leads" subtitle="Leads recebidos via redes sociais e canais digitais" tone="rose" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar lead" fields={fields} columns={columns} rows={dataFiltrada} onAdd={add} onUpdate={update} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Leads no período", value: dataFiltrada.length }, { label: "Taxa de conversão", value: fmtPct(taxaConversao), tone: taxaConversao >= 20 ? "green" : "amber" }, { label: "Canal líder", value: porCanal[0] ? porCanal[0].canal : "—", tone: "rose" }, { label: "Agendados aguardando", value: agendadosPendentes, tone: "amber" }]}
      charts={<div className="grid md:grid-cols-2 gap-5">
        <ChartCard title="Funil de status dos leads"><BarChart data={porStatus}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="status" tick={{ fontSize: 11, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Bar dataKey="total" radius={[4, 4, 0, 0]}>{porStatus.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Bar></BarChart></ChartCard>
        <ChartCard title="Leads por canal"><PieChart><Pie data={porCanal} dataKey="total" nameKey="canal" innerRadius={55} outerRadius={85} paddingAngle={2}>{porCanal.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart></ChartCard>
      </div>} />
    </>
  );
}

function ProcedimentosModulo() {
  const { data, add, bulkAdd, update, remove, loading, erro } = useRecords("procedimentos");
  const { data: testesCat } = useRecords("cadTestesGeneticos");
  const nomesTestes = testesCat.map((t) => t.nome);
  const fields = [
    { key: "tipo", label: "Tipo de procedimento", type: "select", options: ["Teste Genético", "Fototerapia"] },
    { key: "tipoTeste", label: "Qual teste (preenche o valor sozinho)", type: "select", options: nomesTestes.length ? nomesTestes : ["Cadastre em Cadastros → Testes Genéticos"], required: false, showIf: (f) => f.tipo === "Teste Genético" },
    { key: "paciente", label: "Paciente (iniciais/idade)", type: "text" },
    { key: "data", label: "Data", type: "date", default: todayISO() },
    { key: "status", label: "Status", type: "select", options: ["Solicitado", "Em Andamento", "Concluído", "Cancelado"] },
    { key: "valor", label: "Valor (R$)", type: "currency" },
  ];
  const computarValor = (record) => {
    if (record.tipo === "Teste Genético" && record.tipoTeste) { const t = testesCat.find((x) => x.nome === record.tipoTeste); if (t) return { valor: t.valorTeste }; }
    return {};
  };
  const onAddComputado = (record) => add({ ...record, ...computarValor(record) });
  const onUpdateComputado = (id, record) => update(id, { ...record, ...computarValor(record) });
  const columns = [{ key: "tipo", label: "Tipo", render: (r) => <Badge tone={r.tipo === "Teste Genético" ? "purple" : "teal"}>{r.tipo}</Badge> }, { key: "paciente", label: "Paciente" }, { key: "data", label: "Data", render: (r) => fmtDate(r.data) }, { key: "status", label: "Status", render: (r) => { const tone = { Solicitado: "muted", "Em Andamento": "amber", "Concluído": "green", Cancelado: "red" }[r.status]; return <Badge tone={tone}>{r.status}</Badge>; } }, { key: "valor", label: "Valor", render: (r) => fmtBRL(r.valor) }];
  const porTipo = useMemo(() => { const map = {}; data.forEach((r) => { if (!map[r.tipo]) map[r.tipo] = { tipo: r.tipo, total: 0, receita: 0 }; map[r.tipo].total += 1; map[r.tipo].receita += r.valor; }); return Object.values(map); }, [data]);
  const concluidos = data.filter((r) => r.status === "Concluído"), pendentes = data.filter((r) => r.status === "Solicitado" || r.status === "Em Andamento"); const receitaTotal = concluidos.reduce((s, r) => s + r.valor, 0);
  return (
    <ModuleShell icon={FlaskConical} title="Testes Genéticos e Fototerapia" subtitle="Procedimentos especiais por paciente" tone="teal" loading={loading} erro={erro}
      dailyFields={fields} dailyCta="Registrar procedimento" fields={fields} columns={columns} rows={data} onAdd={onAddComputado} onUpdate={onUpdateComputado} onDelete={remove} onBulkImport={bulkAdd}
      kpis={[{ label: "Procedimentos", value: data.length }, { label: "Concluídos", value: concluidos.length, tone: "green" }, { label: "Em andamento", value: pendentes.length, tone: "amber" }, { label: "Receita (concluídos)", value: fmtBRL(receitaTotal), tone: "teal" }]}
      charts={<ChartCard title="Volume por tipo de procedimento"><BarChart data={porTipo}><CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} /><XAxis dataKey="tipo" tick={{ fontSize: 11, fill: T.muted }} /><YAxis tick={{ fontSize: 11, fill: T.muted }} /><Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} /><Legend wrapperStyle={{ fontSize: 12 }} /><Bar dataKey="total" name="Qtd." fill={T.teal} radius={[4, 4, 0, 0]} /></BarChart></ChartCard>} />
  );
}

/* ============================== VISÃO GERAL ============================== */
function SeletorPeriodo({ labelMes, mesSelecionado, onAnterior, onProximo, onSelecionarMes, onAtualizar, atualizando, tone = "coral" }) {
  const cor = T[tone] || T.coral;
  return (
    <div className="flex items-center justify-end gap-2 mb-5 flex-wrap">
      <div className="relative">
        <button className="px-4 py-2.5 rounded-xl text-sm font-semibold text-white flex items-center gap-2" style={{ background: cor }}><CalendarDays size={14} /> Mês: {labelMes}</button>
        <input type="month" value={mesSelecionado} onChange={(e) => onSelecionarMes(e.target.value)} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full" title="Escolher mês" />
      </div>
      <button onClick={onAnterior} title="Mês anterior" className="w-9 h-9 rounded-xl flex items-center justify-center text-white flex-shrink-0" style={{ background: cor }}><ChevronLeft size={16} /></button>
      <button onClick={onProximo} title="Próximo mês" className="w-9 h-9 rounded-xl flex items-center justify-center text-white flex-shrink-0" style={{ background: cor }}><ChevronRight size={16} /></button>
      <button onClick={onAtualizar} disabled={atualizando} title="Atualizar dados" className="w-9 h-9 rounded-xl flex items-center justify-center text-white flex-shrink-0" style={{ background: cor, opacity: atualizando ? 0.6 : 1 }}>{atualizando ? <Loader2 size={14} className="animate-spin" /> : <RefreshCw size={16} />}</button>
    </div>
  );
}

function VisaoGeral() {
  const { unidade } = useUnidade();
  const { perfil } = useAuth();
  const canFinance = perfil && perfil.papel !== "operacional";
  const financeiro = useRecords("financeiro", canFinance), atendimentos = useRecords("convenios"), vacinas = useRecords("vacinas"), insumos = useRecords("insumos"), contas = useRecords("contas", canFinance), pessoal = useRecords("pessoal"), leads = useRecords("marketing"), procedimentos = useRecords("procedimentos"), faturamento = useRecords("faturamento", canFinance), producao = useRecords("producao"), metas = useRecords("metas", canFinance);
  const caixaLanc = useRecords("caixaLancamentos", canFinance), caixaSaldoIni = useRecords("caixaSaldoInicial", canFinance), bancosCad = useRecords("cadBancos", canFinance), investimentosCad = useRecords("investimentos", canFinance);
  const anyLoading = [financeiro, atendimentos, vacinas, insumos, contas, pessoal, leads, procedimentos, faturamento, producao, metas].some((m) => m.loading);
  const [mesSelecionado, setMesSelecionado] = useState(todayISO().slice(0, 7));
  const [atualizando, setAtualizando] = useState(false);
  const mesAtual = mesSelecionado;
  const mesAnterior = (() => { const [y, m] = mesAtual.split("-").map(Number); const d = new Date(y, m - 2, 1); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`; })();
  const mudarMes = (delta) => { const [y, m] = mesSelecionado.split("-").map(Number); const d = new Date(y, m - 1 + delta, 1); setMesSelecionado(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`); };
  const recarregarTudo = async () => { setAtualizando(true); await Promise.all([financeiro, atendimentos, vacinas, insumos, contas, pessoal, leads, procedimentos, faturamento, producao, metas].map((m) => m.reload && m.reload())); setAtualizando(false); };
  const NOMES_MESES = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
  const labelMes = (() => { const [y, m] = mesAtual.split("-").map(Number); return `${NOMES_MESES[m - 1]}/${y}`; })();

  const entradas = financeiro.data.filter((r) => r.tipo === "entrada").reduce((s, r) => s + r.valor, 0);
  const saidas = financeiro.data.filter((r) => r.tipo === "saida").reduce((s, r) => s + r.valor, 0);
  const resultado = entradas - saidas;
  const entradasMes = financeiro.data.filter((r) => r.tipo === "entrada" && monthKey(r.data) === mesAtual).reduce((s, r) => s + r.valor, 0);
  const entradasMesAnterior = financeiro.data.filter((r) => r.tipo === "entrada" && monthKey(r.data) === mesAnterior).reduce((s, r) => s + r.valor, 0);
  const receitaHoje = financeiro.data.filter((r) => r.tipo === "entrada" && r.data === todayISO()).reduce((s, r) => s + r.valor, 0);
  const tendenciaReceita = entradasMesAnterior ? ((entradasMes - entradasMesAnterior) / entradasMesAnterior) * 100 : null;

  const totalAtendConvenio = atendimentos.data.reduce((s, r) => s + Number(r.quantidade), 0);
  const pacientesMes = atendimentos.data.filter((r) => monthKey(r.data) === mesAtual).reduce((s, r) => s + Number(r.quantidade), 0);
  const consultasMes = producao.data.filter((p) => p.mes === mesAtual).reduce((s, p) => s + Number(p.atendimentos), 0);
  const contasReceber = faturamento.data.filter((f) => f.status === "Protocolada" || f.status === "Faturada").reduce((s, f) => s + f.valor, 0);
  const metaReceitaMes = metas.data.find((m) => m.mes === mesAtual && m.categoria === "Receita Total");
  const metaPct = metaReceitaMes && metaReceitaMes.valorMeta ? (entradasMes / metaReceitaMes.valorMeta) * 100 : null;

  const alertaVacinas = vacinas.data.filter((v) => v.qtdEstoque < v.qtdMinima).length;
  const alertaInsumos = insumos.data.filter((i) => i.qtd < i.qtdMinima).length;
  const contasPendentes = contas.data.filter((c) => c.status !== "Pago").reduce((s, c) => s + c.valor, 0);
  const contasAtrasadas = contas.data.filter((c) => c.status === "Atrasado" || (c.status === "Pendente" && c.vencimento < todayISO())).length;
  const metaMediaEquipe = pessoal.data.length ? pessoal.data.reduce((s, p) => s + (p.metaMensal ? Math.min((p.agendados / p.metaMensal) * 100, 999) : 0), 0) / pessoal.data.length : 0;
  const leadsConvertidos = leads.data.filter((l) => l.status === "Convertido").length;
  const taxaConversao = leads.data.length ? (leadsConvertidos / leads.data.length) * 100 : 0;
  const procConcluidos = procedimentos.data.filter((p) => p.status === "Concluído").length;
  const porConvenio = useMemo(() => { const map = {}; atendimentos.data.forEach((r) => { map[r.convenio] = (map[r.convenio] || 0) + Number(r.valor); }); return Object.entries(map).map(([convenio, valor]) => ({ convenio, valor })).sort((a, b) => b.valor - a.valor); }, [atendimentos.data]);
  const fluxoPorMes = useMemo(() => { const map = {}; financeiro.data.forEach((r) => { const m = monthKey(r.data); if (!map[m]) map[m] = { mes: m, entradas: 0, saidas: 0 }; map[m][r.tipo === "entrada" ? "entradas" : "saidas"] += r.valor; }); return Object.values(map).sort((a, b) => a.mes.localeCompare(b.mes)).map((r) => ({ ...r, saldo: r.entradas - r.saidas })); }, [financeiro.data]);
  const ultimosRecebimentos = [...financeiro.data].filter((r) => r.tipo === "entrada").sort((a, b) => b.data.localeCompare(a.data)).slice(0, 5);
  const ultimosPagamentos = [...financeiro.data].filter((r) => r.tipo === "saida").sort((a, b) => b.data.localeCompare(a.data)).slice(0, 5);

  const saldoCaixa = (tipo) => {
    const inicial = caixaSaldoIni.data.find((s) => s.tipoCaixa === tipo && s.mes === mesAtual);
    const doMes = caixaLanc.data.filter((r) => r.tipoCaixa === tipo && monthKey(r.data) === mesAtual);
    const ent = doMes.filter((r) => r.tipo === "entrada").reduce((s, r) => s + Number(r.valor), 0);
    const sai = doMes.filter((r) => r.tipo === "saida").reduce((s, r) => s + Number(r.valor), 0);
    return (inicial ? Number(inicial.valorInicial) : 0) + ent - sai;
  };
  const saldoBanco = (banco) => {
    const inicial = Number(banco.saldoInicial) || 0;
    const desde = banco.dataSaldoInicial;
    const movimentos = financeiro.data.filter((r) => r.banco === banco.nome && (!desde || r.data >= desde));
    return inicial + movimentos.reduce((s, r) => s + (r.tipo === "entrada" ? Number(r.valor) : -Number(r.valor)), 0);
  };
  const contasCorrentes = [
    { grupo: "Caixa", nome: "Caixa Recepção", valor: saldoCaixa("Recepção") },
    { grupo: "Caixa", nome: "Caixa Vacina", valor: saldoCaixa("Vacinas") },
    ...bancosCad.data.map((b) => ({ grupo: "Conta Corrente", nome: b.nome, valor: saldoBanco(b) })),
    ...investimentosCad.data.map((i) => ({ grupo: "Investimento", nome: i.nome, valor: Number(i.valorInicial) || 0 })),
  ];
  const disponibilidadeTotal = contasCorrentes.reduce((s, c) => s + c.valor, 0);

  const alertas = [
    alertaVacinas > 0 && { texto: `${alertaVacinas} vacina(s) abaixo do estoque mínimo`, tone: "red" },
    alertaInsumos > 0 && { texto: `${alertaInsumos} insumo(s) em ponto crítico`, tone: "red" },
    canFinance && perfil.papel === "admin" && contasAtrasadas > 0 && { texto: `${contasAtrasadas} conta(s) atrasada(s) ou vencendo`, tone: "amber" },
    canFinance && resultado < 0 && { texto: "Resultado financeiro do período está negativo", tone: "red" },
  ].filter(Boolean);

  if (anyLoading) return <div className="text-center py-20" style={{ color: T.muted }}><Loader2 size={20} className="animate-spin inline mr-2" />Carregando painel…</div>;

  const primeiroNome = perfil && perfil.nome ? perfil.nome.split(" ")[0] : "";

  return (
    <div>
      <SeletorPeriodo labelMes={labelMes} mesSelecionado={mesSelecionado} onAnterior={() => mudarMes(-1)} onProximo={() => mudarMes(1)} onSelecionarMes={setMesSelecionado} onAtualizar={recarregarTudo} atualizando={atualizando} tone="coral" />
      {/* Saudação */}
      <div className="mb-6">
        <h1 className="text-2xl font-bold mb-1" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>Olá, {primeiroNome} 👋</h1>
        <p className="text-sm" style={{ color: T.muted }}>Bem-vinda ao Painel Administrativo — {unidade ? unidade.nome : "Olhar de Mãe"}</p>
        <p className="text-xs mt-0.5" style={{ color: T.muted }}>Hoje é {weekdayLong()}</p>
      </div>

      {alertas.length > 0 && <Card className="mb-6" style={{ borderColor: `${T.red}40` }}><div className="flex items-center gap-2 mb-2"><AlertTriangle size={15} style={{ color: T.red }} /><span className="font-semibold text-sm" style={{ color: T.text }}>Pontos de atenção</span></div><div className="flex flex-col gap-1.5">{alertas.map((a, i) => (<div key={i} className="flex items-center gap-2 text-sm"><span className="w-1.5 h-1.5 rounded-full" style={{ background: a.tone === "red" ? T.red : T.amber }} /><span style={{ color: T.muted }}>{a.texto}</span></div>))}</div></Card>}

      {canFinance ? (
        <>
          {/* Receita — hierarquia visual: número gigante primeiro */}
          <div className="rounded-[20px] p-7 mb-6 shadow-sm" style={{ background: `linear-gradient(135deg, ${T.tealDeep}, ${T.teal})` }}>
            <div className="flex items-center gap-2 mb-2"><span style={{ color: "#D7F2F4" }}>📈</span><span className="text-xs font-semibold uppercase" style={{ color: "#D7F2F4", letterSpacing: "0.08em" }}>Receita do mês</span></div>
            <div className="text-5xl font-extrabold mb-2" style={{ color: "#fff", fontFamily: "'Roboto', sans-serif", letterSpacing: "-0.02em" }}>{fmtBRL(entradasMes)}</div>
            {tendenciaReceita !== null && (
              <div className="flex items-center gap-1.5 text-sm font-medium" style={{ color: tendenciaReceita >= 0 ? "#C8F5D8" : "#FBD5D0" }}>
                <span>{tendenciaReceita >= 0 ? "▲" : "▼"} {Math.abs(tendenciaReceita).toFixed(0)}%</span>
                <span style={{ color: "#D7F2F4" }}>em relação ao mês anterior</span>
              </div>
            )}
          </div>

          {/* Indicadores secundários — hierarquia menor */}
          <div className="grid gap-3 mb-6 md:grid-cols-5">
            <KpiCard label="📈 Receita hoje" value={fmtBRL(receitaHoje)} tone="teal" />
            <KpiCard label="👶 Pacientes (mês)" value={fmtNum(pacientesMes)} tone="coral" />
            <KpiCard label="💰 Contas a receber" value={fmtBRL(contasReceber)} tone="amber" />
            <KpiCard label="🏥 Consultas (mês)" value={fmtNum(consultasMes)} tone="teal" />
            <KpiCard label="📊 Meta do mês" value={metaPct !== null ? fmtPct(metaPct) : "—"} tone={metaPct !== null ? (metaPct >= 100 ? "green" : metaPct >= 60 ? "amber" : "red") : "ink"} sub={metaPct !== null ? undefined : "sem meta definida"} />
          </div>

          <div className="grid md:grid-cols-2 gap-5 mb-5">
            <ChartCard title="Receita x Despesas do mês" height={220}>
              <BarChart data={[{ nome: "Este mês", entradas: entradasMes, saidas: financeiro.data.filter((r) => r.tipo === "saida" && monthKey(r.data) === mesAtual).reduce((s, r) => s + r.valor, 0) }]} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" stroke={T.border} horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} />
                <YAxis type="category" dataKey="nome" width={70} tick={{ fontSize: 11, fill: T.muted }} />
                <Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} />
                <Legend wrapperStyle={{ fontSize: 12 }} />
                <Bar dataKey="entradas" name="Receita" fill={T.teal} radius={[0, 4, 4, 0]} />
                <Bar dataKey="saidas" name="Despesas" fill={T.coral} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ChartCard>
            <ChartCard title="Faturamento por convênio" height={220}>
              <PieChart><Pie data={porConvenio} dataKey="valor" nameKey="convenio" innerRadius={50} outerRadius={80} paddingAngle={2}>{porConvenio.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip formatter={(v) => fmtBRL(v)} /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart>
            </ChartCard>
          </div>

          <div className="grid md:grid-cols-2 gap-5">
            <Card>
              <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Últimos recebimentos</p>
              {ultimosRecebimentos.length === 0 ? <p className="text-sm py-4" style={{ color: T.muted }}>Nenhum lançamento ainda.</p> : (
                <div className="flex flex-col gap-2">{ultimosRecebimentos.map((r) => (<div key={r.id} className="flex items-center justify-between text-sm py-1.5" style={{ borderBottom: `1px solid ${T.border}` }}><span style={{ color: T.text }}>{r.descricao || r.linha}<span className="block text-xs" style={{ color: T.muted }}>{fmtDate(r.data)}</span></span><span style={{ color: T.green, fontWeight: 600, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.valor)}</span></div>))}</div>
              )}
            </Card>
            <Card>
              <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Últimos pagamentos</p>
              {ultimosPagamentos.length === 0 ? <p className="text-sm py-4" style={{ color: T.muted }}>Nenhum lançamento ainda.</p> : (
                <div className="flex flex-col gap-2">{ultimosPagamentos.map((r) => (<div key={r.id} className="flex items-center justify-between text-sm py-1.5" style={{ borderBottom: `1px solid ${T.border}` }}><span style={{ color: T.text }}>{r.descricao || r.linha}<span className="block text-xs" style={{ color: T.muted }}>{fmtDate(r.data)}</span></span><span style={{ color: T.coral, fontWeight: 600, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(r.valor)}</span></div>))}</div>
              )}
            </Card>
          </div>

          <Card className="mb-6">
            <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Saldo das contas — {labelMes}</p>
            {["Caixa", "Conta Corrente", "Investimento"].map((grupo) => {
              const itens = contasCorrentes.filter((c) => c.grupo === grupo);
              if (itens.length === 0) return null;
              return (
                <div key={grupo} className="mb-3">
                  <div className="flex justify-between py-1.5" style={{ borderBottom: `1px solid ${T.border}` }}>
                    <span className="font-bold text-sm" style={{ color: T.text }}>{grupo}</span>
                    <span className="font-bold text-sm" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(itens.reduce((s, i) => s + i.valor, 0))}</span>
                  </div>
                  {itens.map((c) => (
                    <div key={c.nome} className="flex justify-between py-1.5 pl-4" style={{ borderBottom: `1px solid ${T.border}` }}>
                      <span className="text-sm" style={{ color: T.muted }}>{c.nome}</span>
                      <span className="text-sm" style={{ color: c.valor < 0 ? T.red : T.text, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(c.valor)}</span>
                    </div>
                  ))}
                </div>
              );
            })}
            <div className="flex justify-between py-2 mt-1">
              <span className="font-bold" style={{ color: T.text }}>Disponibilidade total</span>
              <span className="font-bold" style={{ color: disponibilidadeTotal >= 0 ? T.green : T.red, fontFamily: "'Roboto', sans-serif" }}>{fmtBRL(disponibilidadeTotal)}</span>
            </div>
            {bancosCad.data.length === 0 && <p className="text-xs mt-2" style={{ color: T.muted }}>Cadastre seus bancos em Cadastros → Bancos para eles aparecerem aqui automaticamente.</p>}
          </Card>
        </>
      ) : (
        <>
          <div className="grid gap-3 mb-6 md:grid-cols-4">
            <KpiCard label="👶 Pacientes (mês)" value={fmtNum(pacientesMes)} tone="coral" />
            <KpiCard label="Taxa de conversão (leads)" value={fmtPct(taxaConversao)} tone="teal" />
            <KpiCard label="Itens em alerta de estoque" value={alertaVacinas + alertaInsumos} tone={alertaVacinas + alertaInsumos ? "red" : "green"} />
            <KpiCard label="Convênio líder" value={porConvenio[0] ? porConvenio[0].convenio : "—"} tone="teal" />
          </div>
          <ChartCard title="Faturamento por convênio">
            <PieChart><Pie data={porConvenio} dataKey="valor" nameKey="convenio" innerRadius={55} outerRadius={85} paddingAngle={2}>{porConvenio.map((_, i) => <Cell key={i} fill={CHART_SET[i % CHART_SET.length]} />)}</Pie><Tooltip formatter={(v) => fmtBRL(v)} /><Legend wrapperStyle={{ fontSize: 11 }} /></PieChart>
          </ChartCard>
        </>
      )}
    </div>
  );
}

