function EnviarAtestado() {
  const { session } = useAuth();
  const { data, add, remove, loading } = useOwnRecords("rh_atestados");
  const [descricao, setDescricao] = useState(""); const [dataAtestado, setDataAtestado] = useState(todayISO());
  const [arquivo, setArquivo] = useState(null); const [busy, setBusy] = useState(false);
  const enviar = async () => {
    if (!arquivo) return alert("Escolha um arquivo para enviar.");
    setBusy(true);
    try {
      const path = `${session.user.id}/atestados/${Date.now()}-${sanitizeFileName(arquivo.name)}`;
      await sbStorageUpload(path, arquivo, session.access_token);
      await add({ data: dataAtestado, descricao, caminho_arquivo: path });
      setDescricao(""); setArquivo(null);
    } catch (e) { alert("Não foi possível enviar: " + e.message); }
    setBusy(false);
  };
  return (
    <Card className="mb-5">
      <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Enviar atestado</p>
      <div className="flex flex-wrap gap-3 items-end mb-4">
        <Field label="Data"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={dataAtestado} onChange={(e) => setDataAtestado(e.target.value)} /></Field>
        <Field label="Descrição (opcional)"><input className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={descricao} onChange={(e) => setDescricao(e.target.value)} placeholder="ex: consulta médica, 1 dia" /></Field>
        <Field label="Arquivo (PDF ou imagem)"><input type="file" accept=".pdf,.jpg,.jpeg,.png" className="text-sm" onChange={(e) => setArquivo(e.target.files[0])} /></Field>
        <Btn icon={busy ? undefined : Upload} disabled={busy} onClick={enviar}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Enviar atestado</Btn>
      </div>
      {!loading && data.length > 0 && (
        <div className="flex flex-col gap-2">
          {data.map((a) => (
            <div key={a.id} className="flex items-center justify-between rounded-xl px-4 py-2.5" style={{ background: "#FBFAF6", border: `1px solid ${T.border}` }}>
              <span className="text-sm" style={{ color: T.text }}>{fmtDate(a.data)} {a.descricao ? `— ${a.descricao}` : ""}</span>
              <button onClick={() => { if (confirm("Remover este atestado?")) remove(a.id); }}><Trash2 size={13} style={{ color: T.red }} /></button>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

function MeusHorarios() {
  const { perfil } = useAuth();
  const { data, add, update, remove, loading } = useOwnRecords("rh_horas");
  const { data: colaboradoresCat } = useRecords("cadColaboradores");
  const [form, setForm] = useState({ data: todayISO(), hora_entrada: "", hora_saida: "", hora_saida_almoco: "", hora_volta_almoco: "" });
  const [busy, setBusy] = useState(false);
  const [busyPonto, setBusyPonto] = useState(false);
  const paraMinutos = (h) => { const [hh, mm] = h.split(":").map(Number); return hh * 60 + mm; };
  const calcHoras = (e, s, almocoSaida, almocoVolta) => {
    if (!e || !s) return null;
    let mins = paraMinutos(s) - paraMinutos(e);
    if (mins < 0) mins += 24 * 60;
    if (almocoSaida && almocoVolta) { let almoco = paraMinutos(almocoVolta) - paraMinutos(almocoSaida); if (almoco < 0) almoco += 24 * 60; mins -= almoco; }
    return Math.round((mins / 60) * 100) / 100;
  };
  const hoje = todayISO();
  const registroHoje = data.find((r) => r.data === hoje);
  const proximaAcao = !registroHoje ? "entrada" : !registroHoje.hora_saida_almoco ? "saida_almoco" : !registroHoje.hora_volta_almoco ? "volta_almoco" : !registroHoje.hora_saida ? "saida" : "completo";
  const LABEL_ACAO = { entrada: "Bater Entrada", saida_almoco: "Bater Saída (Almoço)", volta_almoco: "Bater Volta do Almoço", saida: "Bater Saída", completo: "Ponto do dia completo ✓" };
  const baterPonto = async () => {
    setBusyPonto(true);
    const agora = new Date().toTimeString().slice(0, 5);
    if (proximaAcao === "entrada") await add({ data: hoje, hora_entrada: agora });
    else if (proximaAcao === "saida_almoco") await update(registroHoje.id, { hora_saida_almoco: agora });
    else if (proximaAcao === "volta_almoco") await update(registroHoje.id, { hora_volta_almoco: agora });
    else if (proximaAcao === "saida") { const horas = calcHoras(registroHoje.hora_entrada, agora, registroHoje.hora_saida_almoco, registroHoje.hora_volta_almoco); await update(registroHoje.id, { hora_saida: agora, horas_total: horas }); }
    setBusyPonto(false);
  };
  const mesAtual = todayISO().slice(0, 7);
  const totalMes = data.filter((r) => r.data.slice(0, 7) === mesAtual).reduce((s, r) => s + (Number(r.horas_total) || 0), 0);
  const cadastro = colaboradoresCat.find((c) => c.nome === (perfil && perfil.nome));
  const cargaHoraria = cadastro ? Number(cadastro.cargaHorariaMensal) : 0;
  const faltaCumprir = Math.max(cargaHoraria - totalMes, 0);
  const pctCumprido = cargaHoraria ? (totalMes / cargaHoraria) * 100 : null;
  return (
    <>
      <Card className="mb-5" style={{ background: `linear-gradient(135deg, ${T.tealDeep}, ${T.teal})` }}>
        <p className="text-[11px] font-semibold uppercase mb-2" style={{ color: "#D7F2F4", letterSpacing: "0.06em" }}>Ponto do dia — {fmtDate(hoje)}</p>
        <div className="flex flex-wrap items-center gap-6 mb-4">
          <div><div className="text-[10px] uppercase" style={{ color: "#D7F2F4" }}>Entrada</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{(registroHoje && registroHoje.hora_entrada) || "—"}</div></div>
          <div><div className="text-[10px] uppercase" style={{ color: "#D7F2F4" }}>Saída almoço</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{(registroHoje && registroHoje.hora_saida_almoco) || "—"}</div></div>
          <div><div className="text-[10px] uppercase" style={{ color: "#D7F2F4" }}>Volta almoço</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{(registroHoje && registroHoje.hora_volta_almoco) || "—"}</div></div>
          <div><div className="text-[10px] uppercase" style={{ color: "#D7F2F4" }}>Saída</div><div className="text-lg font-bold" style={{ color: "#fff" }}>{(registroHoje && registroHoje.hora_saida) || "—"}</div></div>
        </div>
        <button disabled={busyPonto || proximaAcao === "completo"} onClick={baterPonto} className="px-6 py-3 rounded-xl font-bold text-sm transition-transform hover:-translate-y-0.5" style={{ background: proximaAcao === "completo" ? "#FFFFFF30" : "#fff", color: proximaAcao === "completo" ? "#fff" : T.tealDeep, opacity: busyPonto ? 0.7 : 1 }}>
          {busyPonto ? "Registrando…" : LABEL_ACAO[proximaAcao]}
        </button>
      </Card>
      <Card className="mb-5">
      <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Corrigir ou lançar um dia manualmente</p>
      <div className="flex flex-wrap gap-3 items-end mb-4">
        <Field label="Data"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={form.data} onChange={(e) => setForm((p) => ({ ...p, data: e.target.value }))} /></Field>
        <Field label="Entrada"><input type="time" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={form.hora_entrada} onChange={(e) => setForm((p) => ({ ...p, hora_entrada: e.target.value }))} /></Field>
        <Field label="Saída para o almoço"><input type="time" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={form.hora_saida_almoco} onChange={(e) => setForm((p) => ({ ...p, hora_saida_almoco: e.target.value }))} /></Field>
        <Field label="Volta do almoço"><input type="time" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={form.hora_volta_almoco} onChange={(e) => setForm((p) => ({ ...p, hora_volta_almoco: e.target.value }))} /></Field>
        <Field label="Saída"><input type="time" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={form.hora_saida} onChange={(e) => setForm((p) => ({ ...p, hora_saida: e.target.value }))} /></Field>
        <Btn icon={busy ? undefined : Plus} disabled={busy} onClick={async () => {
          setBusy(true);
          const horas = calcHoras(form.hora_entrada, form.hora_saida, form.hora_saida_almoco, form.hora_volta_almoco);
          await add({ data: form.data, hora_entrada: form.hora_entrada || null, hora_saida: form.hora_saida || null, hora_saida_almoco: form.hora_saida_almoco || null, hora_volta_almoco: form.hora_volta_almoco || null, horas_total: horas });
          setForm({ data: todayISO(), hora_entrada: "", hora_saida: "", hora_saida_almoco: "", hora_volta_almoco: "" });
          setBusy(false);
        }}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Registrar</Btn>
      </div>
      <div className="grid gap-3 mb-4" style={{ gridTemplateColumns: cargaHoraria ? "repeat(3, minmax(0,1fr))" : "1fr" }}>
        <KpiCard label="Total de horas no mês" value={`${totalMes.toFixed(2)} h`} tone="purple" />
        {cargaHoraria > 0 && <>
          <KpiCard label="Carga horária mensal" value={`${cargaHoraria.toFixed(0)} h`} />
          <KpiCard label="Falta cumprir" value={`${faltaCumprir.toFixed(2)} h`} tone={faltaCumprir > 0 ? "amber" : "green"} sub={pctCumprido !== null ? fmtPct(pctCumprido) + " cumprido" : undefined} />
        </>}
      </div>
      {!loading && data.length > 0 && (
        <div className="overflow-x-auto -mx-5 px-5">
          <table className="w-full text-sm">
            <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Data</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Entrada</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Almoço</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Saída</th><th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Horas</th><th></th></tr></thead>
            <tbody>{[...data].sort((a, b) => b.data.localeCompare(a.data)).map((r) => (<tr key={r.id} style={{ borderBottom: `1px solid ${T.border}` }}><td className="py-2 px-2">{fmtDate(r.data)}</td><td className="py-2 px-2">{r.hora_entrada || "—"}</td><td className="py-2 px-2">{r.hora_saida_almoco && r.hora_volta_almoco ? `${r.hora_saida_almoco}–${r.hora_volta_almoco}` : "—"}</td><td className="py-2 px-2">{r.hora_saida || "—"}</td><td className="py-2 px-2">{r.horas_total ?? "—"}</td><td className="py-2 px-2 text-right"><button onClick={() => { if (confirm("Remover este registro?")) remove(r.id); }}><Trash2 size={13} style={{ color: T.red }} /></button></td></tr>))}</tbody>
          </table>
        </div>
      )}
    </Card>
    </>
  );
}

const TERMO_USO_IMAGEM = `Autorizo a Clínica Olhar de Mãe a utilizar minha imagem (fotos e vídeos captados durante o exercício da função, eventos internos ou materiais institucionais) para fins de divulgação interna e em redes sociais, site e materiais de marketing da clínica, sem que isso gere direito a qualquer tipo de remuneração. Esta autorização é válida enquanto durar o vínculo com a clínica e pode ser revogada a qualquer momento mediante solicitação por escrito.`;

function TermoUsoImagem() {
  const { session, perfil } = useAuth();
  const { unidadeId } = useUnidade();
  const [aceite, setAceite] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    sbRest(`termos_aceites?colaborador_id=eq.${perfil.id}&tipo=eq.Uso de Imagem&select=*&order=aceito_em.desc&limit=1`, { token: session.access_token })
      .then((r) => setAceite(r && r[0] ? r[0] : null)).finally(() => setLoading(false));
  }, []);
  const assinar = async () => {
    setBusy(true);
    try {
      await sbRest("termos_aceites", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, colaborador_id: perfil.id, tipo: "Uso de Imagem" } });
      const r = await sbRest(`termos_aceites?colaborador_id=eq.${perfil.id}&tipo=eq.Uso de Imagem&select=*&order=aceito_em.desc&limit=1`, { token: session.access_token });
      setAceite(r && r[0] ? r[0] : null);
    } catch (e) { alert("Não foi possível assinar: " + e.message); }
    setBusy(false);
  };
  return (
    <Card className="mb-5">
      <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Termo de Consentimento de Uso de Imagem</p>
      <TermoBox texto={TERMO_USO_IMAGEM} />
      {loading ? <p className="text-sm" style={{ color: T.muted }}>Carregando…</p> : aceite ? (
        <div className="flex items-center gap-2 text-sm" style={{ color: T.green }}><CheckCircle2 size={16} /> Assinado em {fmtDate(aceite.aceito_em.slice(0, 10))}</div>
      ) : (
        <Btn disabled={busy} onClick={assinar}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Assinar termo</Btn>
      )}
    </Card>
  );
}

function AgendamentosPacientes() {
  const { perfil } = useAuth();
  const { data, add, update, remove, loading } = useOwnRecords("agendamentos_pacientes", "data_agendamento.desc");
  const { data: vacinasCat } = useRecords("vacinas");
  const { data: profissionaisCat } = useRecords("cadProfissionais");
  const { data: conveniosCat } = useRecords("cadConvenios");
  const nomesVacinas = vacinasCat.map((v) => v.nome);
  const nomesProfissionais = profissionaisCat.map((p) => p.nome);
  const nomesConvenios = conveniosCat.length ? conveniosCat.map((c) => c.nome) : CONVENIOS;
  const [form, setForm] = useState({ tipo: "Consulta", paciente: "", pacienteNovo: "Já é paciente", contato: "", data: todayISO(), convenio: "", vacina: "", medico: "", plantao: false });
  const [busy, setBusy] = useState(false);
  const mesAtual = todayISO().slice(0, 7);
  const doMes = data.filter((r) => r.data_agendamento.slice(0, 7) === mesAtual);
  const registrar = async () => {
    if (!form.paciente) return;
    setBusy(true);
    await add({
      tipo: form.tipo, paciente: form.paciente, paciente_novo: form.pacienteNovo, contato: form.contato || null, data_agendamento: form.data,
      convenio: form.tipo === "Consulta" ? (form.convenio || null) : null, vacina: form.tipo === "Vacina" ? (form.vacina || null) : null,
      medico: form.tipo === "Consulta" ? (form.medico || null) : null, plantao: form.tipo === "Consulta" ? !!form.plantao : false,
      colaborador_nome: perfil.nome, compareceu: "Aguardando",
    });
    setForm({ tipo: form.tipo, paciente: "", pacienteNovo: "Já é paciente", contato: "", data: todayISO(), convenio: "", vacina: "", medico: "", plantao: false });
    setBusy(false);
  };
  return (
    <Card className="mb-5">
      <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Agendamentos — consulta ou vacina</p>
      <div className="flex flex-wrap gap-3 items-end mb-4">
        <Field label="Tipo">
          <select className="rounded-lg px-3 py-2 text-sm outline-none w-36" style={inputStyle} value={form.tipo} onChange={(e) => setForm((p) => ({ ...p, tipo: e.target.value }))}>
            <option value="Consulta">Consulta</option>
            <option value="Vacina">Vacina</option>
          </select>
        </Field>
        <Field label="Paciente novo ou já é paciente?">
          <select className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={form.pacienteNovo} onChange={(e) => setForm((p) => ({ ...p, pacienteNovo: e.target.value }))}>
            <option value="Já é paciente">Já é paciente</option>
            <option value="Novo">Novo</option>
          </select>
        </Field>
        <Field label="Nome do paciente"><input className="rounded-lg px-3 py-2 text-sm outline-none w-48" style={inputStyle} value={form.paciente} onChange={(e) => setForm((p) => ({ ...p, paciente: e.target.value }))} /></Field>
        <Field label="Contato (telefone)"><input className="rounded-lg px-3 py-2 text-sm outline-none w-40" style={inputStyle} value={form.contato} onChange={(e) => setForm((p) => ({ ...p, contato: e.target.value }))} /></Field>
        <Field label="Data do agendamento"><input type="date" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={form.data} onChange={(e) => setForm((p) => ({ ...p, data: e.target.value }))} /></Field>
        {form.tipo === "Consulta" && (
          <>
            <Field label="Médico(a)">
              <select className="rounded-lg px-3 py-2 text-sm outline-none w-44" style={inputStyle} value={form.medico} onChange={(e) => setForm((p) => ({ ...p, medico: e.target.value }))}>
                <option value="">— não informar —</option>
                {nomesProfissionais.map((m) => <option key={m} value={m}>{m}</option>)}
              </select>
            </Field>
            <Field label="Convênio (opcional)">
              <select className="rounded-lg px-3 py-2 text-sm outline-none w-44" style={inputStyle} value={form.convenio} onChange={(e) => setForm((p) => ({ ...p, convenio: e.target.value }))}>
                <option value="">— não informar —</option>
                {nomesConvenios.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </Field>
            <Field label="É plantão?">
              <div className="flex items-center h-[38px] gap-2"><input type="checkbox" className="w-4 h-4" checked={form.plantao} onChange={(e) => setForm((p) => ({ ...p, plantao: e.target.checked }))} /><span className="text-sm" style={{ color: T.text }}>Sim</span></div>
            </Field>
          </>
        )}
        {form.tipo === "Vacina" && (
          <Field label="Qual vacina (opcional)">
            <select className="rounded-lg px-3 py-2 text-sm outline-none w-44" style={inputStyle} value={form.vacina} onChange={(e) => setForm((p) => ({ ...p, vacina: e.target.value }))}>
              <option value="">— não informar —</option>
              {nomesVacinas.map((v) => <option key={v} value={v}>{v}</option>)}
            </select>
          </Field>
        )}
        <Btn icon={busy ? undefined : Plus} disabled={busy || !form.paciente} onClick={registrar}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Registrar agendamento</Btn>
      </div>
      <div className="mb-3"><KpiCard label="Agendamentos no mês" value={doMes.length} tone="teal" /></div>
      {!loading && doMes.length > 0 && (
        <div className="overflow-x-auto -mx-5 px-5">
          <table className="w-full text-sm">
            <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}>
              <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Data</th>
              <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Paciente</th>
              <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Tipo</th>
              <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Médico/Vacina</th>
              <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Plantão</th>
              <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Compareceu</th>
              <th></th>
            </tr></thead>
            <tbody>{[...doMes].sort((a, b) => b.data_agendamento.localeCompare(a.data_agendamento)).map((r) => (
              <tr key={r.id} style={{ borderBottom: `1px solid ${T.border}` }}>
                <td className="py-2 px-2">{fmtDate(r.data_agendamento)}</td><td className="py-2 px-2" style={{ color: T.text }}>{r.paciente}</td>
                <td className="py-2 px-2"><Badge tone={r.tipo === "Consulta" ? "teal" : "coral"}>{r.tipo}</Badge></td>
                <td className="py-2 px-2" style={{ color: T.muted }}>{r.medico || r.vacina || "—"}</td>
                <td className="py-2 px-2">{r.plantao ? <Badge tone="amber">Plantão</Badge> : "—"}</td>
                <td className="py-2 px-2"><Badge tone={r.compareceu === "Sim" ? "green" : r.compareceu === "Não" ? "red" : "muted"}>{r.compareceu}</Badge></td>
                <td className="py-2 px-2 text-right"><button onClick={() => { if (confirm("Remover este agendamento?")) remove(r.id); }}><Trash2 size={13} style={{ color: T.red }} /></button></td>
              </tr>
            ))}</tbody>
          </table>
        </div>
      )}
    </Card>
  );
}

