function PlantaoResumoModulo() {
  const { data: atendimentos, loading: l1, erro: e1 } = useRecords("plantaoAtendimentos");
  const { data: valoresConvenio, loading: l2 } = useRecords("plantaoValoresConvenio");
  const { data: profissionais, loading: l3 } = useRecords("cadProfissionais");
  const loading = l1 || l2 || l3;
  const [mes, setMes] = useState(todayISO().slice(0, 7));
  const [aliquotaImposto, setAliquotaImposto] = useState(0);

  const doMes = atendimentos.filter((a) => monthKey(a.data) === mes);
  const valorConvenioMap = {}; valoresConvenio.forEach((v) => { valorConvenioMap[v.convenio] = v.valorAtendimento; });

  const porMedico = useMemo(() => {
    const map = {};
    doMes.forEach((a) => {
      if (!map[a.medico]) map[a.medico] = { medico: a.medico, pacientes: 0, dias: new Set(), valorProduzido: 0 };
      map[a.medico].pacientes += Number(a.qtdPacientes);
      map[a.medico].dias.add(a.data);
      map[a.medico].valorProduzido += Number(a.qtdPacientes) * (valorConvenioMap[a.convenio] || 0);
    });
    return Object.values(map).map((m) => {
      const config = profissionais.find((p) => p.nome === m.medico) || {};
      const diasTrabalhados = m.dias.size;
      const valorPlantaoFixoTotal = diasTrabalhados * Number(config.valorPlantaoFixo || 0);
      const valorRepasseAtendimentos = m.pacientes * Number(config.valorRepasseAtendimentoPlantao || 0);
      const valorRepasseTotal = valorPlantaoFixoTotal + valorRepasseAtendimentos;
      const valorClinicaBruto = m.valorProduzido - valorRepasseTotal;
      const valorClinicaLiquido = valorClinicaBruto * (1 - aliquotaImposto / 100);
      const mediaAtendimentos = diasTrabalhados ? m.pacientes / diasTrabalhados : 0;
      return { ...m, diasTrabalhados, valorPlantaoFixoTotal, valorRepasseAtendimentos, valorRepasseTotal, valorClinicaBruto, valorClinicaLiquido, mediaAtendimentos };
    }).sort((a, b) => b.valorProduzido - a.valorProduzido);
  }, [doMes, profissionais, aliquotaImposto]);

  const totalProduzido = porMedico.reduce((s, m) => s + m.valorProduzido, 0);
  const totalRepasse = porMedico.reduce((s, m) => s + m.valorRepasseTotal, 0);
  const totalBruto = porMedico.reduce((s, m) => s + m.valorClinicaBruto, 0);
  const totalLiquido = porMedico.reduce((s, m) => s + m.valorClinicaLiquido, 0);
  const mediaGeral = porMedico.length ? porMedico.reduce((s, m) => s + m.mediaAtendimentos, 0) / porMedico.length : 0;

  return (
    <div>
      <SectionHeader icon={ClipboardList} title="Resumo Financeiro — Plantão" subtitle="Valor produzido, repasse e resultado da clínica por profissional — visível só para administradores e gestores" tone="coral" />
      {e1 && <Card className="mb-5" style={{ borderColor: `${T.red}55` }}><span className="text-sm" style={{ color: T.red }}>Erro ao carregar: {e1}</span></Card>}
      <Card className="mb-5">
        <div className="flex flex-wrap gap-4 items-end">
          <Field label="Mês (AAAA-MM)"><input className="rounded-lg px-3 py-2 text-sm outline-none w-32" style={inputStyle} value={mes} onChange={(e) => setMes(e.target.value)} /></Field>
          <Field label="Alíquota de imposto sobre o valor bruto (%)"><input type="number" className="rounded-lg px-3 py-2 text-sm outline-none w-32" style={inputStyle} value={aliquotaImposto} onChange={(e) => setAliquotaImposto(Number(e.target.value) || 0)} /></Field>
        </div>
      </Card>
      <div className="grid gap-3 mb-6 md:grid-cols-3">
        <KpiCard label="Total produzido" value={fmtBRL(totalProduzido)} tone="teal" />
        <KpiCard label="Total de repasse" value={fmtBRL(totalRepasse)} tone="amber" />
        <KpiCard label="Média de atendimentos/dia" value={mediaGeral.toFixed(1)} tone="coral" />
        <KpiCard label="Valor bruto da clínica" value={fmtBRL(totalBruto)} />
        <KpiCard label="Valor líquido da clínica" value={fmtBRL(totalLiquido)} tone="green" />
      </div>
      {!loading && porMedico.length > 0 && (
        <ChartCard title="Valor produzido por profissional">
          <BarChart data={porMedico}>
            <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
            <XAxis dataKey="medico" tick={{ fontSize: 10, fill: T.muted }} interval={0} angle={-15} textAnchor="end" height={60} />
            <YAxis tick={{ fontSize: 11, fill: T.muted }} tickFormatter={(v) => `${v / 1000}k`} />
            <Tooltip formatter={(v) => fmtBRL(v)} contentStyle={{ fontSize: 12, borderRadius: 8 }} />
            <Bar dataKey="valorProduzido" fill={T.teal} radius={[4, 4, 0, 0]} />
          </BarChart>
        </ChartCard>
      )}
      <Card>
        <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>Detalhamento por profissional</p>
        {loading ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}><Loader2 size={16} className="animate-spin inline mr-2" />Carregando…</div> :
          porMedico.length === 0 ? <div className="text-center py-10 text-sm" style={{ color: T.muted }}>Nenhum registro de plantão neste mês.</div> : (
          <div className="overflow-x-auto -mx-5 px-5">
            <table className="w-full text-sm min-w-[820px]">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Profissional</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Dias</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Pacientes</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Média/dia</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Produzido</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Repasse</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Clínica (bruto)</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Clínica (líquido)</th>
              </tr></thead>
              <tbody>{porMedico.map((m, i) => (
                <tr key={i} style={{ borderBottom: `1px solid ${T.border}` }}>
                  <td className="py-2 px-2 font-medium" style={{ color: T.text }}>{m.medico}</td>
                  <td className="py-2 px-2">{m.diasTrabalhados}</td>
                  <td className="py-2 px-2">{m.pacientes}</td>
                  <td className="py-2 px-2">{m.mediaAtendimentos.toFixed(1)}</td>
                  <td className="py-2 px-2">{fmtBRL(m.valorProduzido)}</td>
                  <td className="py-2 px-2" style={{ color: T.amber }}>{fmtBRL(m.valorRepasseTotal)}</td>
                  <td className="py-2 px-2">{fmtBRL(m.valorClinicaBruto)}</td>
                  <td className="py-2 px-2" style={{ color: T.green, fontWeight: 600 }}>{fmtBRL(m.valorClinicaLiquido)}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
}

/* ============================== IMPORTAÇÃO DE OFX ============================== */
function parseOFX(texto) {
  const blocos = texto.split(/<STMTTRN>/i).slice(1);
  return blocos.map((bloco) => {
    const pegar = (tag) => { const m = bloco.match(new RegExp(`<${tag}>([^<\r\n]+)`, "i")); return m ? m[1].trim() : ""; };
    const dtRaw = pegar("DTPOSTED");
    const data = dtRaw && dtRaw.length >= 8 ? `${dtRaw.slice(0, 4)}-${dtRaw.slice(4, 6)}-${dtRaw.slice(6, 8)}` : "";
    const valorRaw = pegar("TRNAMT").replace(",", ".");
    const valor = parseFloat(valorRaw) || 0;
    const fitid = pegar("FITID");
    const memo = pegar("MEMO") || pegar("NAME") || "Sem descrição";
    return { data, valor, fitid, memo };
  }).filter((t) => t.data && t.valor !== 0);
}
const chaveDescricaoOfx = (memo) => normalizarTexto(memo).slice(0, 60);

function ImportarOFXModulo() {
  const { session } = useAuth();
  const { unidadeId } = useUnidade();
  const { data: bancos, loading: loadingBancos } = useRecords("cadBancos");
  const { data: financeiro, add: addFinanceiro } = useRecords("financeiro");
  const { data: contasPagar, update: updateConta } = useRecords("contas");
  const { data: contasReceber, update: updateGuia } = useRecords("faturamento");
  const [bancoId, setBancoId] = useState("");
  const [transacoes, setTransacoes] = useState([]);
  const [memorizadas, setMemorizadas] = useState({});
  const [busy, setBusy] = useState(false);
  const [resultado, setResultado] = useState(null);

  useEffect(() => {
    sbRest(`ofx_categorias_memorizadas?unidade_id=eq.${unidadeId}&select=*`, { token: session.access_token })
      .then((r) => { const map = {}; (r || []).forEach((m) => { map[m.descricao_chave] = { linha: m.linha_dre, tipo: m.tipo }; }); setMemorizadas(map); }).catch(() => {});
  }, [unidadeId]);

  const fitidsJaImportados = new Set(financeiro.data ? financeiro.data.map((f) => f.fitid).filter(Boolean) : []);

  const encontrarContaCorrespondente = (tipo, valorAbs) => {
    const tolerancia = 0.01;
    if (tipo === "saida") {
      const conta = contasPagar.find((c) => c.status !== "Pago" && (!c.bancoId || c.bancoId === bancoId) && Math.abs(Number(c.valor) - valorAbs) < tolerancia);
      return conta ? { id: conta.id, tipoConta: "pagar", descricao: conta.descricao } : null;
    }
    const guia = contasReceber.find((g) => g.status !== "Paga" && (!g.bancoId || g.bancoId === bancoId) && Math.abs(Number(g.valor) - valorAbs) < tolerancia);
    return guia ? { id: guia.id, tipoConta: "receber", descricao: `Guia ${guia.numeroGuia || ""} — ${guia.convenio}` } : null;
  };

  const handleArquivo = async (file) => {
    const texto = await file.text();
    const parsed = parseOFX(texto);
    const enriquecidas = parsed.map((t, i) => {
      const chave = chaveDescricaoOfx(t.memo);
      const memo = memorizadas[chave];
      const tipo = memo ? memo.tipo : (t.valor >= 0 ? "entrada" : "saida");
      const valorAbs = Math.abs(t.valor);
      const contaMatch = bancoId ? encontrarContaCorrespondente(tipo, valorAbs) : null;
      return {
        idTemp: i, data: t.data, memo: t.memo, valorAbs, fitid: t.fitid,
        tipo, linha: memo ? memo.linha : (t.valor >= 0 ? "Receita de Convênios" : "Outras Despesas"),
        jaImportado: t.fitid && fitidsJaImportados.has(t.fitid),
        incluir: !(t.fitid && fitidsJaImportados.has(t.fitid)),
        contaMatch, conciliar: !!contaMatch,
      };
    });
    setTransacoes(enriquecidas);
    setResultado(null);
  };

  const atualizarLinha = (idTemp, campo, valor) => setTransacoes((prev) => prev.map((t) => t.idTemp === idTemp ? { ...t, [campo]: valor } : t));

  const confirmarImportacao = async () => {
    setBusy(true);
    const banco = bancos.find((b) => b.id === bancoId);
    let ok = 0, conciliados = 0;
    for (const t of transacoes.filter((x) => x.incluir)) {
      try {
        await sbRest("financeiro_transacoes", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, data: t.data, tipo: t.tipo, linha_dre: t.linha, descricao: t.memo, valor: t.valorAbs, fitid: t.fitid || null, banco: banco ? banco.nome : null } });
        await sbRest("ofx_categorias_memorizadas", { method: "POST", token: session.access_token, body: { unidade_id: unidadeId, descricao_chave: chaveDescricaoOfx(t.memo), linha_dre: t.linha, tipo: t.tipo } }).catch(async () => {
          // já existe — atualiza
          await sbRest(`ofx_categorias_memorizadas?unidade_id=eq.${unidadeId}&descricao_chave=eq.${encodeURIComponent(chaveDescricaoOfx(t.memo))}`, { method: "PATCH", token: session.access_token, body: { linha_dre: t.linha, tipo: t.tipo } });
        });
        if (t.contaMatch && t.conciliar) {
          if (t.contaMatch.tipoConta === "pagar") await updateConta(t.contaMatch.id, { status: "Pago", dataPagamento: t.data });
          else await updateGuia(t.contaMatch.id, { status: "Paga", dataPagamento: t.data });
          conciliados++;
        }
        ok++;
      } catch (e) { /* segue tentando os outros */ }
    }
    setResultado({ ok, total: transacoes.filter((x) => x.incluir).length, conciliados });
    setBusy(false);
  };

  return (
    <div>
      <SectionHeader icon={Wallet} title="Importar Extrato (OFX)" subtitle="Importe o arquivo do banco — o sistema lembra como você categorizou cada descrição da próxima vez" tone="coral" />
      <Card className="mb-5">
        <div className="flex flex-wrap gap-3 items-end mb-1">
          <Field label="Banco">
            <select className="rounded-lg px-3 py-2 text-sm outline-none w-56" style={inputStyle} value={bancoId} onChange={(e) => setBancoId(e.target.value)}>
              <option value="" disabled>Selecione…</option>
              {bancos.map((b) => <option key={b.id} value={b.id}>{b.nome}</option>)}
            </select>
          </Field>
          <Field label="Arquivo .ofx"><input type="file" accept=".ofx,.qfx" className="text-sm" onChange={(e) => e.target.files[0] && handleArquivo(e.target.files[0])} /></Field>
        </div>
        {bancos.length === 0 && !loadingBancos && <p className="text-sm mt-2" style={{ color: T.amber }}>Cadastre um banco primeiro em Cadastros → Bancos.</p>}
      </Card>

      {transacoes.length > 0 && (
        <Card className="mb-5">
          <p className="text-[11px] font-semibold uppercase mb-3" style={{ color: T.muted, letterSpacing: "0.06em" }}>{transacoes.length} transação(ões) encontradas — confira e ajuste antes de importar</p>
          <div className="overflow-x-auto -mx-5 px-5">
            <table className="w-full text-sm min-w-[820px]">
              <thead><tr style={{ borderBottom: `1px solid ${T.border}` }}>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Incluir</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Data</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Descrição</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Valor</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Tipo</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Linha do DRE</th>
                <th className="text-left py-2 px-2 text-[11px] uppercase" style={{ color: T.muted }}>Conciliação</th>
              </tr></thead>
              <tbody>{transacoes.map((t) => (
                <tr key={t.idTemp} style={{ borderBottom: `1px solid ${T.border}`, opacity: t.incluir ? 1 : 0.45 }}>
                  <td className="py-2 px-2"><input type="checkbox" checked={t.incluir} onChange={(e) => atualizarLinha(t.idTemp, "incluir", e.target.checked)} /></td>
                  <td className="py-2 px-2">{fmtDate(t.data)}</td>
                  <td className="py-2 px-2" style={{ color: T.text }}>{t.memo}{t.jaImportado && <span className="block text-xs" style={{ color: T.amber }}>já importado antes</span>}</td>
                  <td className="py-2 px-2">{fmtBRL(t.valorAbs)}</td>
                  <td className="py-2 px-2"><select className="rounded-lg px-2 py-1 text-xs outline-none" style={inputStyle} value={t.tipo} onChange={(e) => atualizarLinha(t.idTemp, "tipo", e.target.value)}><option value="entrada">Entrada</option><option value="saida">Saída</option></select></td>
                  <td className="py-2 px-2"><select className="rounded-lg px-2 py-1 text-xs outline-none" style={inputStyle} value={t.linha} onChange={(e) => atualizarLinha(t.idTemp, "linha", e.target.value)}>{TODAS_LINHAS_DRE.map((l) => <option key={l} value={l}>{l}</option>)}</select></td>
                  <td className="py-2 px-2">
                    {t.contaMatch ? (
                      <label className="flex items-center gap-1.5 text-xs" style={{ color: T.text }}>
                        <input type="checkbox" checked={t.conciliar} onChange={(e) => atualizarLinha(t.idTemp, "conciliar", e.target.checked)} />
                        Marcar "{t.contaMatch.descricao}" como {t.contaMatch.tipoConta === "pagar" ? "pago" : "paga"}
                      </label>
                    ) : <span className="text-xs" style={{ color: T.muted }}>Sem correspondência</span>}
                  </td>
                </tr>
              ))}</tbody>
            </table>
          </div>
          <div className="mt-4"><Btn disabled={busy || !bancoId} onClick={confirmarImportacao}>{busy ? <Loader2 size={14} className="animate-spin" /> : null} Importar {transacoes.filter((t) => t.incluir).length} transação(ões)</Btn></div>
          {resultado && <p className="text-sm mt-3" style={{ color: T.green }}>{resultado.ok} de {resultado.total} importadas com sucesso{resultado.conciliados > 0 && ` — ${resultado.conciliados} conta(s) marcada(s) como paga(s) automaticamente`}.</p>}
        </Card>
      )}
    </div>
  );
}

