function NotificationsMenu({ setTab }) {
  const { perfil } = useAuth();
  const somenteAdmin = perfil && perfil.papel === "admin";
  const [open, setOpen] = useState(false);
  const vacinas = useRecords("vacinas");
  const lotesVacinas = useRecords("entradasEstoqueVacinas");
  const insumos = useRecords("insumos");
  const contas = useRecords("contas", somenteAdmin);
  const leads = useRecords("marketing");
  const calendario = useRecords("marketingCalendario");
  const perfisAprovacao = useRecords("perfisAprovacao", somenteAdmin);
  const loading = vacinas.loading || lotesVacinas.loading || insumos.loading || contas.loading || leads.loading || calendario.loading || perfisAprovacao.loading;
  const nomeVacina = (id) => (vacinas.data.find((v) => v.id === id) || {}).nome || "—";

  const notificacoes = [
    ...(somenteAdmin ? perfisAprovacao.data.filter((p) => p.aprovado === false).map((p) => ({ texto: `🔒 "${p.nome}" aguardando aprovação de acesso`, tone: "amber", tab: "aprovarContas" })) : []),
    ...calendario.data.filter(ehHojeOuAniversarioHoje).map((c) => ({ texto: `${c.tipo === "Aniversário" ? "🎂" : "📌"} Hoje: ${c.titulo}`, tone: "coral", tab: "calendarioMarketing" })),
    ...vacinas.data.filter((v) => v.qtdEstoque < v.qtdMinima).map((v) => ({ texto: `Vacina "${v.nome}" abaixo do estoque mínimo`, tone: "red", tab: "vacinas" })),
    ...lotesVacinas.data.filter((l) => { if (!l.validade) return false; const dias = Math.ceil((new Date(l.validade) - new Date(todayISO())) / 86400000); return dias <= 90; }).map((l) => { const dias = Math.ceil((new Date(l.validade) - new Date(todayISO())) / 86400000); return { texto: `"${nomeVacina(l.vacinaId)}" — lote ${l.lote} ${dias < 0 ? "vencido" : `vence em ${dias} dias`} (${fmtDate(l.validade)})`, tone: dias <= 45 ? "red" : "amber", tab: "entradaEstoqueVacinas" }; }),
    ...insumos.data.filter((i) => i.qtd < i.qtdMinima).map((i) => ({ texto: `Insumo "${i.nome}" em ponto crítico`, tone: "red", tab: "insumos" })),
    ...(somenteAdmin ? contas.data.filter((c) => c.status !== "Pago" && c.vencimento < todayISO()).map((c) => ({ texto: `Conta vencida: "${c.descricao}" — vencimento ${fmtDate(c.vencimento)}`, tone: "red", tab: "contas" })) : []),
    ...(somenteAdmin ? contas.data.filter((c) => c.status === "Pendente" && c.vencimento === diasAFrente(2)).map((c) => ({ texto: `Conta "${c.descricao}" vence em 2 dias — ${fmtDate(c.vencimento)}`, tone: "amber", tab: "contas" })) : []),
    ...leads.data.filter((l) => l.status === "Novo").map((l) => ({ texto: `Lead novo: ${l.nome} — ainda não contatado`, tone: "teal", tab: "marketing" })),
  ];

  return (
    <div className="relative">
      <button title="Notificações" onClick={() => setOpen((o) => !o)} className="relative">
        <Bell size={18} style={{ color: T.muted }} />
        {notificacoes.length > 0 && <span className="absolute -top-1.5 -right-1.5 w-4 h-4 rounded-full flex items-center justify-center text-[10px] font-bold text-white" style={{ background: T.coral }}>{notificacoes.length > 9 ? "9+" : notificacoes.length}</span>}
      </button>
      {open && (
        <div className="absolute right-0 mt-2 w-80 rounded-xl overflow-hidden z-50 shadow-lg max-h-96 overflow-y-auto" style={{ background: T.card, border: `1px solid ${T.border}` }} onMouseLeave={() => setOpen(false)}>
          <div className="px-4 py-3 sticky top-0" style={{ background: T.card, borderBottom: `1px solid ${T.border}` }}><span className="text-sm font-semibold" style={{ color: T.text }}>Notificações</span></div>
          {loading ? <div className="px-4 py-6 text-sm text-center" style={{ color: T.muted }}>Carregando…</div> :
            notificacoes.length === 0 ? <div className="px-4 py-6 text-sm text-center" style={{ color: T.muted }}>Tudo em dia — nenhum alerta no momento.</div> :
            notificacoes.map((n, i) => (
              <button key={i} onClick={() => { setTab(n.tab); setOpen(false); }} className="w-full text-left px-4 py-3 text-sm flex items-start gap-2" style={{ borderBottom: `1px solid ${T.border}` }}>
                <span className="w-1.5 h-1.5 rounded-full mt-1.5 flex-shrink-0" style={{ background: n.tone === "red" ? T.red : n.tone === "amber" ? T.amber : n.tone === "coral" ? T.coral : T.teal }} />
                <span style={{ color: T.text }}>{n.texto}</span>
              </button>
            ))}
        </div>
      )}
    </div>
  );
}

