/* ============================== PROVEDOR DE UNIDADE ============================== */
function UnidadeProvider({ children }) {
  const { session, perfil } = useAuth();
  const [unidades, setUnidades] = useState([]);
  const [unidadeId, setUnidadeId] = useState(null);
  const [loading, setLoading] = useState(true);

  const reloadUnidades = useCallback(async () => {
    const rows = await sbRest("unidades?select=*&order=nome.asc", { token: session.access_token });
    setUnidades(rows || []);
    return rows || [];
  }, [session.access_token]);

  useEffect(() => {
    (async () => {
      const rows = await reloadUnidades();
      setUnidadeId(perfil && perfil.unidade_id ? perfil.unidade_id : (rows[0] ? rows[0].id : null));
      setLoading(false);
    })();
  }, [reloadUnidades]);

  const addUnidade = async (nome) => {
    const row = await sbRest("unidades", { method: "POST", token: session.access_token, body: { nome } });
    await reloadUnidades();
    if (row && row[0]) setUnidadeId(row[0].id);
  };

  const [, forcarAtualizacao] = useReducer((x) => x + 1, 0);
  const atualizarCores = async (corPrimaria, corSecundaria) => {
    await sbRest(`unidades?id=eq.${unidadeId}`, { method: "PATCH", token: session.access_token, body: { cor_primaria: corPrimaria, cor_secundaria: corSecundaria } });
    applyTheme(corPrimaria, corSecundaria);
    await reloadUnidades();
    forcarAtualizacao();
  };
  const atualizarContatosAlerta = async (email, whatsapp) => {
    await sbRest(`unidades?id=eq.${unidadeId}`, { method: "PATCH", token: session.access_token, body: { email_alertas: email, whatsapp_alertas: whatsapp } });
    await reloadUnidades();
  };

  const unidade = unidades.find((u) => u.id === unidadeId);
  useEffect(() => {
    if (unidade) { applyTheme(unidade.cor_primaria, unidade.cor_secundaria); forcarAtualizacao(); }
  }, [unidade && unidade.id, unidade && unidade.cor_primaria, unidade && unidade.cor_secundaria]);

  if (loading || !unidadeId) return <div className="min-h-screen flex items-center justify-center" style={{ background: T.canvas, color: T.muted }}><Loader2 size={20} className="animate-spin mr-2" /> Carregando unidades…</div>;

  return <UnidadeContext.Provider value={{ unidadeId, unidade, unidades, setUnidadeId, addUnidade, reloadUnidades, atualizarCores, atualizarContatosAlerta }}>{children}</UnidadeContext.Provider>;
}

/* ============================== PROVEDOR DE AUTENTICAÇÃO ============================== */
function AuthProvider({ children }) {
  const [session, setSession] = useState(null);
  const [perfil, setPerfil] = useState(null);
  const [checkingPerfil, setCheckingPerfil] = useState(false);
  const [unidadesIniciais, setUnidadesIniciais] = useState([]);
  const refreshTimerRef = useRef(null);

  const agendarRenovacao = (sess) => {
    if (refreshTimerRef.current) clearTimeout(refreshTimerRef.current);
    if (!sess || !sess.refresh_token) return;
    const expiraEmMs = (sess.expires_in || 3600) * 1000;
    const renovarEmMs = Math.max(expiraEmMs - 5 * 60 * 1000, 10000); // renova 5min antes de expirar
    refreshTimerRef.current = setTimeout(() => renovarSessao(sess), renovarEmMs);
  };

  const renovarSessao = async (sess) => {
    try {
      const data = await sbAuth("token?grant_type=refresh_token", { refresh_token: sess.refresh_token });
      setSession(data);
      agendarRenovacao(data);
    } catch (e) {
      // sessão não pôde ser renovada — desloga para a pessoa entrar de novo
      setSession(null);
      setPerfil(null);
    }
  };

  const carregarPerfil = async (sess) => {
    setCheckingPerfil(true);
    try {
      const rows = await sbRest(`perfis?id=eq.${sess.user.id}&select=*`, { token: sess.access_token });
      if (rows && rows[0]) setPerfil(rows[0]);
      else {
        const un = await sbRest("unidades?select=*&order=nome.asc", { token: sess.access_token });
        setUnidadesIniciais(un || []);
        setPerfil(null);
      }
    } catch (e) { setPerfil(null); }
    setCheckingPerfil(false);
  };

  const login = async (email, senha) => { const data = await sbAuth("token?grant_type=password", { email, password: senha }); setSession(data); agendarRenovacao(data); await carregarPerfil(data); };
  const signUp = async (email, senha, nome) => { const data = await sbAuth("signup", { email, password: senha, data: { nome } }); if (data.access_token) { setSession(data); agendarRenovacao(data); await carregarPerfil(data); } };
  const logout = () => { if (refreshTimerRef.current) clearTimeout(refreshTimerRef.current); setSession(null); setPerfil(null); };
  const marcarTourVisto = async () => {
    setPerfil((p) => ({ ...p, tour_visto: true }));
    try { await sbRest(`perfis?id=eq.${session.user.id}`, { method: "PATCH", token: session.access_token, body: { tour_visto: true } }); } catch (e) { /* não bloqueia a experiência */ }
  };

  const value = { session, perfil, login, signUp, logout, unidadesIniciais };

  useEffect(() => {
    const aoVoltarVisivel = () => {
      if (document.visibilityState === "visible" && session && session.refresh_token) renovarSessao(session);
    };
    document.addEventListener("visibilitychange", aoVoltarVisivel);
    return () => document.removeEventListener("visibilitychange", aoVoltarVisivel);
  }, [session]);

  if (!session) return <AuthContext.Provider value={value}><LoginScreen /></AuthContext.Provider>;
  if (checkingPerfil) return <div className="min-h-screen flex items-center justify-center" style={{ background: T.canvas, color: T.muted }}><Loader2 size={20} className="animate-spin mr-2" /> Verificando perfil…</div>;
  if (!perfil) return (
    <AuthContext.Provider value={value}>
      <OnboardingPerfil onDone={() => carregarPerfil(session)} />
    </AuthContext.Provider>
  );
  if (perfil.aprovado === false) return (
    <AuthContext.Provider value={value}>
      <AguardandoAprovacaoScreen onAtualizar={() => carregarPerfil(session)} onSair={logout} />
    </AuthContext.Provider>
  );

  return (
    <AuthContext.Provider value={value}>
      {children}
      {!perfil.tour_visto && <TourGuiado onFinalizar={marcarTourVisto} />}
    </AuthContext.Provider>
  );
}

function TourGuiado({ onFinalizar }) {
  const passos = [
    { titulo: "Bem-vindo(a) ao Olhar de Mãe! 👋", texto: "Esse é o sistema de gestão da clínica. Vamos te mostrar rapidinho como ele funciona — leva menos de 1 minuto." },
    { titulo: "Menu lateral", texto: "Do lado esquerdo, tudo fica organizado por área — Financeiro, Atendimento, Estoque, Pessoas, e mais. Clique em qualquer item para abrir." },
    { titulo: "Meu RH", texto: "Essa é a sua área pessoal — registre sua produtividade, bata ponto, envie atestados e veja seus documentos, sempre visível só para você." },
    { titulo: "Notificações", texto: "O sininho no topo da tela avisa sobre estoque baixo, contas vencendo e outras pendências." },
    { titulo: "Pronto! 🎉", texto: "Você já pode explorar o sistema à vontade. Qualquer dúvida, fale com o administrador." },
  ];
  const [i, setI] = useState(0);
  const passo = passos[i];
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4" style={{ background: "#132030cc" }}>
      <div className="w-full max-w-sm rounded-2xl p-6" style={{ background: T.card }}>
        <div className="flex items-center gap-2 mb-4">
          <img src={LOGO_DATA_URI} alt="Olhar de Mãe" style={{ width: 32, height: 32, objectFit: "contain" }} />
          <span className="text-xs" style={{ color: T.muted }}>{i + 1} de {passos.length}</span>
        </div>
        <p className="font-bold text-lg mb-2" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>{passo.titulo}</p>
        <p className="text-sm mb-6" style={{ color: T.muted }}>{passo.texto}</p>
        <div className="flex justify-between items-center">
          <button onClick={onFinalizar} className="text-xs" style={{ color: T.muted }}>Pular tour</button>
          <Btn onClick={() => (i < passos.length - 1 ? setI(i + 1) : onFinalizar())}>{i < passos.length - 1 ? "Próximo" : "Concluir"}</Btn>
        </div>
      </div>
    </div>
  );
}

function ResetPasswordScreen({ accessToken, onDone }) {
  const [senha, setSenha] = useState(""); const [confirmar, setConfirmar] = useState("");
  const [busy, setBusy] = useState(false); const [msg, setMsg] = useState(null);
  const salvar = async () => {
    if (senha.length < 6) { setMsg({ tone: "red", text: "A senha precisa ter pelo menos 6 caracteres." }); return; }
    if (senha !== confirmar) { setMsg({ tone: "red", text: "As senhas digitadas não são iguais." }); return; }
    setBusy(true); setMsg(null);
    try {
      const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
        method: "PUT",
        headers: { apikey: ANON_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ password: senha }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.msg || data.error_description || "Não foi possível trocar a senha. Peça um novo link.");
      setMsg({ tone: "green", text: "Senha alterada! Redirecionando para o login…" });
      setTimeout(() => { window.location.hash = ""; onDone(); }, 1800);
    } catch (e) { setMsg({ tone: "red", text: e.message }); }
    setBusy(false);
  };
  return (
    <div className="min-h-screen flex items-center justify-center p-4" style={{ background: T.sidebar }}>
      <div className="w-full max-w-sm rounded-2xl p-7" style={{ background: T.card }}>
        <div className="flex items-center gap-2.5 mb-6">
          <img src={LOGO_DATA_URI} alt="Olhar de Mãe" style={{ width: 46, height: 46, objectFit: "contain" }} />
          <div><div className="font-bold" style={{ color: T.text, fontFamily: "'Roboto', sans-serif" }}>Olhar de Mãe</div><div className="text-xs" style={{ color: T.muted }}>Painel de Gestão da Rede</div></div>
        </div>
        <p className="font-bold mb-1" style={{ color: T.text }}>Criar nova senha</p>
        <p className="text-sm mb-4" style={{ color: T.muted }}>Digite sua nova senha duas vezes para confirmar.</p>
        <div className="flex flex-col gap-3">
          <Field label="Nova senha"><input type="password" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={senha} onChange={(e) => setSenha(e.target.value)} /></Field>
          <Field label="Confirmar nova senha"><input type="password" className="rounded-lg px-3 py-2 text-sm outline-none w-full" style={inputStyle} value={confirmar} onChange={(e) => setConfirmar(e.target.value)} /></Field>
          {msg && <div className="text-sm" style={{ color: msg.tone === "red" ? T.red : T.green }}>{msg.text}</div>}
          <Btn onClick={salvar} disabled={busy || !senha || !confirmar}>{busy ? <Loader2 size={14} className="animate-spin" /> : <Lock size={14} />} Salvar nova senha</Btn>
        </div>
      </div>
    </div>
  );
}

/* ============================== APP ROOT ============================== */
function lerParametrosDeRecuperacao() {
  if (typeof window === "undefined") return null;
  const hash = window.location.hash.startsWith("#") ? window.location.hash.slice(1) : window.location.hash;
  const params = new URLSearchParams(hash);
  if (params.get("type") === "recovery" && params.get("access_token")) return params.get("access_token");
  return null;
}
export default function ClinicaOlharDeMaeApp() {
  const [tokenRecuperacao, setTokenRecuperacao] = useState(() => lerParametrosDeRecuperacao());
  if (tokenRecuperacao) return <ResetPasswordScreen accessToken={tokenRecuperacao} onDone={() => setTokenRecuperacao(null)} />;
  return (
    <AuthProvider>
      <UnidadeProvider>
        <AppInner />
      </UnidadeProvider>
    </AuthProvider>
  );
}
